/**
 * Build the `interpolate` expression that paints the circle layer.
 * Feature properties are pre-computed in `toGeoJson`, so the GPU reads a plain
 * number and no per-frame JavaScript runs.
 */
export function colorExpression(mode: ColorMode): Expression {
  const ramp = RAMPS[mode];
  const property = mode === "recency" ? "age" : mode === "depth" ? "depth" : "mag";
  const expr: Expression = ["interpolate", ["linear"], ["get", property]];
  for (const stop of ramp.stops) {
    expr.push(stop.at, stop.color);
  }
  return expr;
}

/**
 * Circle radius in pixels. Magnitude is a log scale already, so a quadratic
 * ramp on top of it approximates "area ∝ felt footprint" without letting an
 * M8 swallow a continent. Radius also grows with zoom so dense sequences
 * separate as you move in.
 */
export function radiusExpression(): Expression {
  const byMag = (scale: number): Expression => [
    "interpolate",
    ["exponential", 1.9],
    ["get", "mag"],
    0,
    1.6 * scale,
    2,
    2.6 * scale,
    4,
    5 * scale,
    6,
    10 * scale,
    8,
    19 * scale,
  ];
  return ["interpolate", ["linear"], ["zoom"], 0, byMag(0.72), 3, byMag(1), 7, byMag(1.7), 12, byMag(2.6)];
