import { useCallback, useEffect, useRef, useState } from "react";
import maplibregl, { type GeoJSONSource, type LngLatBoundsLike, type Map as MapLibreMap } from "maplibre-gl";
import "maplibre-gl/dist/maplibre-gl.css";

import { basemap, USGS_ATTRIBUTION, type BasemapId, type ProjectionId } from "../lib/basemaps";
import { colorExpression, quakeColor, radiusExpression, type ColorMode } from "../lib/color";
import { toCollection, EMPTY_COLLECTION } from "../lib/geojson";
import type { Bounds } from "../lib/geo";
import { magnitudeLabel, depthLabel, relativeTime } from "../lib/format";
import type { Quake } from "../lib/usgs";

const SRC_QUAKES = "quakes";
const SRC_PLATES = "plates";
const LYR_PLATES = "plate-boundaries";
const LYR_GLOW = "quake-glow";
const LYR_CORE = "quake-core";
const LYR_SELECTED = "quake-selected";
const LYR_HIT = "quake-hit";

export interface MapViewProps {
  quakes: Quake[];
  colorMode: ColorMode;
  basemapId: BasemapId;
  projection: ProjectionId;
  showPlates: boolean;
  selected: Quake | null;
  now: number;
  /** Bumped by the parent to request a camera move to the selected event. */
  flyToken: number;
  onSelect: (id: string | null) => void;
  onBoundsChange: (bounds: Bounds) => void;
}

interface HoverState {
  quake: Quake;
  x: number;
  y: number;
}

export function MapView({
  quakes,
  colorMode,
  basemapId,
  projection,
  showPlates,
  selected,
  now,
  flyToken,
  onSelect,
  onBoundsChange,
}: MapViewProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<MapLibreMap | null>(null);
  const [ready, setReady] = useState(false);
  const [hover, setHover] = useState<HoverState | null>(null);

  // Latest props for the imperative MapLibre handlers, which are bound once.
  const quakesRef = useRef(quakes);
  quakesRef.current = quakes;
  const nowRef = useRef(now);
  nowRef.current = now;
  const onSelectRef = useRef(onSelect);
  onSelectRef.current = onSelect;
  const onBoundsChangeRef = useRef(onBoundsChange);
  onBoundsChangeRef.current = onBoundsChange;
  const colorModeRef = useRef(colorMode);
  colorModeRef.current = colorMode;
  const showPlatesRef = useRef(showPlates);
  showPlatesRef.current = showPlates;
  const basemapRef = useRef(basemapId);
  basemapRef.current = basemapId;
  const selectedRef = useRef(selected);
  selectedRef.current = selected;

  /** (Re)create every app-owned source and layer on top of the current style. */
  const installLayers = useCallback((map: MapLibreMap) => {
    const theme = basemap(basemapRef.current);

    if (!map.getSource(SRC_PLATES)) {
      map.addSource(SRC_PLATES, { type: "geojson", data: "/data/plate-boundaries.json" });
    }
    if (!map.getLayer(LYR_PLATES)) {
      map.addLayer({
        id: LYR_PLATES,
        type: "line",
        source: SRC_PLATES,
        layout: {
          "line-cap": "round",
          "line-join": "round",
          visibility: showPlatesRef.current ? "visible" : "none",
        },
        paint: {
          "line-color": theme.plateColor,
          "line-opacity": 0.75,
          "line-width": ["interpolate", ["linear"], ["zoom"], 0, 0.6, 4, 1.3, 9, 2.4],
          "line-dasharray": [3, 2],
        },
      });
    }

    if (!map.getSource(SRC_QUAKES)) {
      map.addSource(SRC_QUAKES, {
        type: "geojson",
        // Explicitly unclustered: one dot per event, always.
        cluster: false,
        promoteId: "qid",
        data: toCollection(quakesRef.current, nowRef.current),
      });
    }

    const color = colorExpression(colorModeRef.current);
    const radius = radiusExpression();

    if (!map.getLayer(LYR_GLOW)) {
      map.addLayer({
        id: LYR_GLOW,
        type: "circle",
        source: SRC_QUAKES,
        // Only the events worth drawing attention to get a halo, otherwise the
        // map turns into fog in dense sequences.
        filter: [">=", ["get", "mag"], 3.5],
        paint: {
          "circle-color": color as never,
          "circle-radius": ["*", ["number", radius as never], 2.4] as never,
          "circle-blur": 1,
          "circle-opacity": 0.28,
          "circle-pitch-alignment": "map",
        },
      });
    }

    if (!map.getLayer(LYR_CORE)) {
      map.addLayer({
        id: LYR_CORE,
        type: "circle",
        source: SRC_QUAKES,
        paint: {
          "circle-color": color as never,
          "circle-radius": radius as never,
          "circle-opacity": [
            "interpolate",
            ["linear"],
            ["get", "mag"],
            0,
            0.62,
            3,
            0.82,
            6,
            0.95,
          ],
          "circle-stroke-color": [
            "case",
            ["boolean", ["feature-state", "hover"], false],
            "#ffffff",
            theme.haloColor,
          ],
          "circle-stroke-width": [
            "case",
            ["boolean", ["feature-state", "hover"], false],
            2,
            ["interpolate", ["linear"], ["get", "mag"], 2, 0.4, 5, 1.1],
          ],
          "circle-stroke-opacity": 0.9,
        },
      });
    }

    if (!map.getLayer(LYR_SELECTED)) {
      map.addLayer({
        id: LYR_SELECTED,
        type: "circle",
        source: SRC_QUAKES,
        filter: ["==", ["get", "qid"], "�"],
        paint: {
          "circle-color": "rgba(0,0,0,0)",
          "circle-radius": 14,
          "circle-stroke-color": "#ffffff",
          "circle-stroke-width": 2,
          "circle-stroke-opacity": 1,
        },
      });
    }

    if (!map.getLayer(LYR_HIT)) {
      // Invisible, generously sized target so an M0.4 dot is still tappable.
      map.addLayer({
        id: LYR_HIT,
        type: "circle",
        source: SRC_QUAKES,
        paint: {
          "circle-color": "rgba(0,0,0,0)",
          "circle-radius": ["+", ["number", radius as never], 7] as never,
        },
      });
    }
  }, []);

  /* ---------------------------------------------------------------------- */
  /* Map lifecycle                                                          */
  /* ---------------------------------------------------------------------- */

  useEffect(() => {
    if (!containerRef.current || mapRef.current) return;

    const map = new maplibregl.Map({
      container: containerRef.current,
      style: basemap(basemapRef.current).style,
      center: [12, 18],
      zoom: 1.35,
      minZoom: 0.6,
      maxZoom: 14,
      attributionControl: false,
      dragRotate: false,
      pitchWithRotate: false,
      hash: false,
    });
    mapRef.current = map;

    map.addControl(new maplibregl.NavigationControl({ showCompass: false }), "bottom-right");
    map.addControl(
      new maplibregl.AttributionControl({ compact: true, customAttribution: USGS_ATTRIBUTION }),
      "bottom-right",
    );
    map.addControl(
      new maplibregl.ScaleControl({ maxWidth: 96, unit: "metric" }),
      "bottom-left",
    );
    map.touchZoomRotate.disableRotation();

    let hovered: string | null = null;
    const clearHover = () => {
      if (hovered !== null) {
        map.setFeatureState({ source: SRC_QUAKES, id: hovered }, { hover: false });
        hovered = null;
      }
      map.getCanvas().style.cursor = "";
      setHover(null);
    };

    map.on("style.load", () => {
      installLayers(map);
      setReady(true);
    });

    map.on("mousemove", LYR_HIT, (event) => {
      const feature = event.features?.[0];
      const id = feature?.properties?.qid as string | undefined;
      if (!id) return;
      if (hovered !== id) {
        if (hovered !== null) {
          map.setFeatureState({ source: SRC_QUAKES, id: hovered }, { hover: false });
        }
        hovered = id;
        map.setFeatureState({ source: SRC_QUAKES, id }, { hover: true });
      }
      map.getCanvas().style.cursor = "pointer";
      const quake = quakesRef.current.find((q) => q.id === id);
      if (quake) setHover({ quake, x: event.point.x, y: event.point.y });
    });

    map.on("mouseleave", LYR_HIT, clearHover);
    map.on("dragstart", clearHover);
    map.on("zoomstart", clearHover);

    map.on("click", (event) => {
      const features = map.queryRenderedFeatures(event.point, { layers: [LYR_HIT] });
      if (features.length === 0) {
        onSelectRef.current(null);
        return;
      }
      // Multiple dots can overlap; prefer the largest magnitude under the cursor.
      let best = features[0];
      for (const feature of features) {
        if (Number(feature.properties?.mag ?? 0) > Number(best.properties?.mag ?? 0)) best = feature;
      }
      onSelectRef.current((best.properties?.qid as string) ?? null);
    });

    const emitBounds = () => {
      const b = map.getBounds();
      onBoundsChangeRef.current({
        west: b.getWest(),
        south: b.getSouth(),
        east: b.getEast(),
        north: b.getNorth(),
      });
    };
    map.on("moveend", emitBounds);
    map.once("load", emitBounds);

    return () => {
      map.remove();
      mapRef.current = null;
      setReady(false);
    };
  }, [installLayers]);

  /* ---------------------------------------------------------------------- */
  /* Prop-driven updates                                                    */
  /* ---------------------------------------------------------------------- */

  // Basemap switch: setStyle tears down every layer, `style.load` rebuilds them.
  useEffect(() => {
    const map = mapRef.current;
    if (!map) return;
    setReady(false);
    map.setStyle(basemap(basemapId).style);
  }, [basemapId]);

  useEffect(() => {
    const map = mapRef.current;
    if (!map) return;
    map.setProjection({ type: projection === "globe" ? "globe" : "mercator" });
  }, [projection]);

  useEffect(() => {
    const map = mapRef.current;
    if (!map || !ready) return;
    const source = map.getSource(SRC_QUAKES) as GeoJSONSource | undefined;
    source?.setData(toCollection(quakes, now) as never);
  }, [quakes, now, ready]);

  useEffect(() => {
    const map = mapRef.current;
    if (!map || !ready || !map.getLayer(LYR_CORE)) return;
    const color = colorExpression(colorMode);
    map.setPaintProperty(LYR_CORE, "circle-color", color as never);
    map.setPaintProperty(LYR_GLOW, "circle-color", color as never);
  }, [colorMode, ready]);

  useEffect(() => {
    const map = mapRef.current;
    if (!map || !ready || !map.getLayer(LYR_PLATES)) return;
    map.setLayoutProperty(LYR_PLATES, "visibility", showPlates ? "visible" : "none");
  }, [showPlates, ready]);

  // Selected ring: filter to the chosen event, then breathe.
  useEffect(() => {
    const map = mapRef.current;
    if (!map || !ready || !map.getLayer(LYR_SELECTED)) return;

    map.setFilter(LYR_SELECTED, ["==", ["get", "qid"], selected?.id ?? "�"]);
    if (!selected) return;

    map.setPaintProperty(LYR_SELECTED, "circle-stroke-color", quakeColor(colorMode, selected, now));

    let frame = 0;
    const start = performance.now();
    const tick = (t: number) => {
      const phase = ((t - start) % 1800) / 1800;
      const eased = 1 - (1 - phase) ** 3;
      map.setPaintProperty(LYR_SELECTED, "circle-radius", 10 + eased * 26);
      map.setPaintProperty(LYR_SELECTED, "circle-stroke-opacity", 0.9 * (1 - eased));
      frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [selected, colorMode, now, ready]);

  // Camera moves are requested explicitly so that selecting from the map does
  // not yank the view out from under the pointer.
  useEffect(() => {
    const map = mapRef.current;
    if (!map || !selected || flyToken === 0) return;
    map.flyTo({
      center: [selected.lon, selected.lat],
      zoom: Math.max(map.getZoom(), 4.5),
      duration: 1100,
      essential: true,
    });
  }, [flyToken, selected]);

  // Empty state / data cleared.
  useEffect(() => {
    const map = mapRef.current;
    if (!map || !ready || quakes.length > 0) return;
    const source = map.getSource(SRC_QUAKES) as GeoJSONSource | undefined;
    source?.setData(EMPTY_COLLECTION as never);
  }, [quakes.length, ready]);

  const fitAll = useCallback(() => {
    const map = mapRef.current;
    const list = quakesRef.current;
    if (!map || list.length === 0) return;
    let west = 180;
    let east = -180;
    let south = 90;
    let north = -90;
    for (const q of list) {
      west = Math.min(west, q.lon);
      east = Math.max(east, q.lon);
      south = Math.min(south, q.lat);
      north = Math.max(north, q.lat);
    }
    const bounds: LngLatBoundsLike = [
      [west, south],
      [east, north],
    ];
    map.fitBounds(bounds, { padding: 64, duration: 900, maxZoom: 8 });
  }, []);

  const resetView = useCallback(() => {
    mapRef.current?.flyTo({ center: [12, 18], zoom: 1.35, duration: 900 });
  }, []);

  return (
    <div className="map-shell">
      <div ref={containerRef} className="map-canvas" role="application" aria-label="World map of recent earthquakes" />

      <div className="map-actions">
        <button type="button" className="map-btn" onClick={fitAll} title="Zoom to the filtered events">
          Fit results
        </button>
        <button type="button" className="map-btn" onClick={resetView} title="Back to the world view">
          Reset view
        </button>
      </div>

      {hover ? <MapTooltip hover={hover} colorMode={colorMode} now={now} /> : null}
    </div>
  );
}

function MapTooltip({
  hover,
  colorMode,
  now,
}: {
  hover: HoverState;
  colorMode: ColorMode;
  now: number;
}) {
  const { quake, x, y } = hover;
  const color = quakeColor(colorMode, quake, now);
  return (
    <div
      className="map-tooltip"
      style={{
        transform: `translate(${x}px, ${y}px)`,
        // Flip the card to the other side of the cursor near the right edge.
        ["--flip" as string]: x > 260 ? "-100%" : "0%",
      }}
    >
      <div className="map-tooltip-head">
        <span className="map-tooltip-mag" style={{ color }}>
          M {magnitudeLabel(quake.mag)}
        </span>
        <span className="map-tooltip-time">{relativeTime(quake.time, now)}</span>
      </div>
      <div className="map-tooltip-place">{quake.place}</div>
      <div className="map-tooltip-depth">{depthLabel(quake.depth)} deep</div>
    </div>
  );
}

