/* ------------------------------------------------------------------ */
/* Tokens                                                              */
/* ------------------------------------------------------------------ */

:root {
  --bg: #05070b;
  --surface-0: #0a0e15;
  --surface-1: #0e131c;
  --surface-2: #141a25;
  --surface-3: #1b2331;

  --line: rgba(148, 163, 184, 0.13);
  --line-strong: rgba(148, 163, 184, 0.26);

  --text: #e9eef7;
  --text-2: #97a3b6;
  --text-3: #63708a;

  --accent: #7dd3fc;
  --accent-dim: rgba(125, 211, 252, 0.14);
  --danger: #f87171;

  --radius-sm: 6px;
  --radius: 10px;
  --radius-lg: 16px;

  --shadow-panel: 0 24px 60px -18px rgba(0, 0, 0, 0.85), 0 2px 8px rgba(0, 0, 0, 0.5);
  --shadow-pop: 0 12px 32px -10px rgba(0, 0, 0, 0.8);

  --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Inter, Roboto, "Helvetica Neue",
    Arial, sans-serif;
  --font-mono: ui-monospace, SFMono-Regular, "SF Mono", "JetBrains Mono", Menlo, Consolas,
    monospace;

  --header-h: 62px;
  --timeline-h: 116px;
  --sidebar-w: 372px;

  color-scheme: dark;
}

/* ------------------------------------------------------------------ */
/* Reset                                                               */
/* ------------------------------------------------------------------ */

*,
*::before,
*::after {
  box-sizing: border-box;
}

html,
body,
#root {
  height: 100%;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font-sans);
  font-size: 14px;
