  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 6px;
}

.mode-card {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 7px 8px 8px;
  border-radius: var(--radius);
  border: 1px solid var(--line);
  background: var(--surface-1);
  transition: border-color 0.15s ease, background 0.15s ease;
}

.mode-card:hover {
