  background: var(--surface-2);
}

.mode-swatch {
  height: 7px;
  border-radius: 99px;
}

.mode-name {
  font-size: 11px;
  font-weight: 550;
  color: var(--text-2);
  text-align: left;
}

.mode-card.is-active .mode-name {
  color: var(--text);
}

/* ------------------------------------------------------------------ */
/* Search                                                              */
/* ------------------------------------------------------------------ */

.search-field {
  position: relative;
  display: flex;
  align-items: center;
}

.search-icon {
  position: absolute;
  left: 10px;
  width: 14px;
  height: 14px;
  color: var(--text-3);
  pointer-events: none;
}

.search-input {
  width: 100%;
  height: 34px;
  padding: 0 30px 0 30px;
  border-radius: var(--radius);
  border: 1px solid var(--line);
  background: var(--surface-1);
  color: var(--text);
  font-size: 12.5px;
  transition: border-color 0.15s ease, background 0.15s ease;
}

.search-input::placeholder {
  color: var(--text-3);
}

.search-input:focus {
  outline: none;
  border-color: rgba(125, 211, 252, 0.5);
  background: var(--surface-2);
}

.search-input::-webkit-search-cancel-button {
  display: none;
}

.search-clear {
  position: absolute;
  right: 8px;
  width: 18px;
  height: 18px;
  border-radius: 4px;
  color: var(--text-3);
  font-size: 16px;
  line-height: 1;
  display: grid;
  place-items: center;
}

.search-clear:hover {
  color: var(--text);
  background: var(--surface-3);
}

/* ------------------------------------------------------------------ */
/* Range slider                                                        */
/* ------------------------------------------------------------------ */

.range {
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.range-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
}

.range-value {
  font-family: var(--font-mono);
  font-size: 11.5px;
  color: var(--text);
  font-variant-numeric: tabular-nums;
}

.range-track-wrap {
  position: relative;
  height: 22px;
  display: flex;
  align-items: center;
}

.range-track {
  position: absolute;
  inset-inline: 0;
  height: 5px;
  border-radius: 99px;
  background: var(--surface-3);
  background-size: 100% 100%;
  opacity: 0.42;
}

.range-fill {
  position: absolute;
  height: 5px;
  border-radius: 99px;
  background: rgba(125, 211, 252, 0.85);
  box-shadow: 0 0 10px rgba(125, 211, 252, 0.35);
}

.range-input {
  position: absolute;
  inset-inline: 0;
  width: 100%;
  height: 22px;
  margin: 0;
  background: none;
  appearance: none;
  pointer-events: none;
}

.range-input::-webkit-slider-thumb {
  appearance: none;
  pointer-events: auto;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: #eaf6ff;
  border: 2px solid #0c1420;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.6);
  cursor: grab;
  transition: transform 0.12s ease;
}

.range-input::-webkit-slider-thumb:active {
  cursor: grabbing;
  transform: scale(1.16);
}

.range-input::-moz-range-thumb {
  pointer-events: auto;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: #eaf6ff;
  border: 2px solid #0c1420;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.6);
  cursor: grab;
}

.range-input:focus-visible::-webkit-slider-thumb {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

/* The upper thumb sits on top so the two never trap each other at the ends. */
.range-input-high {
  z-index: 2;
}

/* ------------------------------------------------------------------ */
