/* ------------------------------------------------------------------ */

.chips {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
}

.chip {
  height: 25px;
  padding: 0 10px;
  border-radius: 99px;
  border: 1px solid var(--line);
