  font-size: 11.5px;
  font-weight: 500;
  transition: background 0.15s ease, color 0.15s ease, border-color 0.15s ease;
}

.chip:hover {
  color: var(--text);
  background: var(--surface-2);
}

.chip.is-active {
  background: var(--accent-dim);
  border-color: rgba(125, 211, 252, 0.45);
  color: #cdeeff;
}

/* ------------------------------------------------------------------ */
/* Select                                                              */
/* ------------------------------------------------------------------ */

