  position: relative;
  display: flex;
}

.select {
  width: 100%;
  height: 32px;
  padding: 0 30px 0 11px;
  border-radius: var(--radius);
  border: 1px solid var(--line);
  background: var(--surface-1);
  color: var(--text);
  font-size: 12.5px;
  appearance: none;
  cursor: pointer;
}

.select:hover {
  background: var(--surface-2);
}

.select-chevron {
  position: absolute;
  right: 10px;
  top: 50%;
  transform: translateY(-50%);
  width: 14px;
  height: 14px;
  color: var(--text-3);
  pointer-events: none;
}

/* ------------------------------------------------------------------ */
/* Switch                                                              */
/* ------------------------------------------------------------------ */

.switch {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  cursor: pointer;
  padding: 2px 0;
}

.switch input {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
}

.switch-track {
  position: relative;
  flex-shrink: 0;
  width: 32px;
  height: 18px;
  margin-top: 1px;
  border-radius: 99px;
  background: var(--surface-3);
  border: 1px solid var(--line);
  transition: background 0.18s ease, border-color 0.18s ease;
}

.switch-thumb {
  position: absolute;
  top: 2px;
  left: 2px;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--text-3);
  transition: transform 0.18s cubic-bezier(0.4, 0, 0.2, 1), background 0.18s ease;
}

.switch input:checked + .switch-track {
  background: var(--accent-dim);
  border-color: rgba(125, 211, 252, 0.5);
}

