  height: 26px;
  padding: 0 13px;
  border-radius: 99px;
  font-size: 11.5px;
  font-weight: 500;
  color: var(--text-2);
  white-space: nowrap;
  transition: background 0.15s ease, color 0.15s ease;
}

.map-btn:hover {
