  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
}

.map-tooltip-mag {
  font-family: var(--font-mono);
  font-size: 13px;
  font-weight: 700;
  letter-spacing: -0.01em;
}

.map-tooltip-time {
  font-size: 10.5px;
  color: var(--text-3);
  white-space: nowrap;
}

.map-tooltip-place {
  margin-top: 3px;
  font-size: 11.5px;
  color: var(--text);
  line-height: 1.35;
}

.map-tooltip-depth {
  margin-top: 2px;
  font-size: 10.5px;
  color: var(--text-3);
  font-variant-numeric: tabular-nums;
}

