.maplibregl-ctrl-attrib {
  background: rgba(10, 14, 21, 0.82) !important;
  border-radius: var(--radius-sm) !important;
  border: 1px solid var(--line);
  font-size: 10px !important;
  backdrop-filter: blur(8px);
}

.maplibregl-ctrl-attrib a {
  color: var(--text-2) !important;
}

.maplibregl-ctrl-attrib-inner {
  color: var(--text-3);
}

.maplibregl-ctrl-attrib-button {
  background-color: rgba(148, 163, 184, 0.18) !important;
}

.maplibregl-ctrl-bottom-left,
.maplibregl-ctrl-bottom-right {
  z-index: 5;
}

/* ------------------------------------------------------------------ */
/* Floating map actions                                                */
/* ------------------------------------------------------------------ */

.map-actions {
  position: absolute;
  left: 50%;
  bottom: 14px;
  transform: translateX(-50%);
  display: flex;
  gap: 2px;
  padding: 3px;
  border-radius: 99px;
  border: 1px solid var(--line);
  background: rgba(12, 17, 25, 0.85);
  box-shadow: var(--shadow-pop);
  backdrop-filter: blur(12px);
  z-index: 8;
}

.map-btn {
  height: 26px;
  padding: 0 13px;
  border-radius: 99px;
  font-size: 11.5px;
  font-weight: 500;
  color: var(--text-2);
  white-space: nowrap;
  transition: background 0.15s ease, color 0.15s ease;
}

.map-btn:hover {
  background: rgba(148, 163, 184, 0.14);
  color: var(--text);
}

/* ------------------------------------------------------------------ */
/* Hover tooltip                                                       */
/* ------------------------------------------------------------------ */

.map-tooltip {
  position: absolute;
  top: 0;
  left: 0;
  z-index: 12;
  pointer-events: none;
  will-change: transform;
}

.map-tooltip > * {
  position: relative;
}

.map-tooltip {
  padding: 8px 11px;
  min-width: 168px;
  max-width: 240px;
  border-radius: var(--radius);
  border: 1px solid var(--line-strong);
  background: rgba(10, 14, 21, 0.94);
  box-shadow: var(--shadow-pop);
  backdrop-filter: blur(14px);
  margin-left: 14px;
  margin-top: -14px;
  translate: var(--flip, 0) 0;
}

.map-tooltip-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
}

.map-tooltip-mag {
  font-family: var(--font-mono);
  font-size: 13px;
  font-weight: 700;
  letter-spacing: -0.01em;
}

.map-tooltip-time {
  font-size: 10.5px;
  color: var(--text-3);
  white-space: nowrap;
}

.map-tooltip-place {
  margin-top: 3px;
  font-size: 11.5px;
  color: var(--text);
  line-height: 1.35;
}

.map-tooltip-depth {
  margin-top: 2px;
  font-size: 10.5px;
  color: var(--text-3);
  font-variant-numeric: tabular-nums;
}

/* ------------------------------------------------------------------ */
/* Legend                                                              */
/* ------------------------------------------------------------------ */

.legend {
  width: 246px;
  padding: 11px 13px 12px;
  border-radius: var(--radius);
  border: 1px solid var(--line);
  background: rgba(10, 14, 21, 0.86);
  box-shadow: var(--shadow-pop);
  backdrop-filter: blur(14px);
}

.legend-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 8px;
}

.legend-title {
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.11em;
  text-transform: uppercase;
  color: var(--text-2);
}

.legend-unit {
  font-family: var(--font-mono);
  font-size: 10px;
  color: var(--text-3);
}

.legend-bar {
  height: 9px;
  border-radius: 99px;
  border: 1px solid rgba(255, 255, 255, 0.09);
}

.legend-ticks {
  position: relative;
  height: 15px;
  margin-top: 4px;
}

.legend-tick {
  position: absolute;
  top: 0;
  font-family: var(--font-mono);
  font-size: 9.5px;
  color: var(--text-3);
  white-space: nowrap;
}

.legend-blurb {
  margin-top: 2px;
  font-size: 10.5px;
  line-height: 1.45;
  color: var(--text-3);
}

.legend-size {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 10px;
  padding-top: 9px;
  border-top: 1px solid var(--line);
}

.legend-size-label {
  font-size: 9.5px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--text-3);
  white-space: nowrap;
}

.legend-size-dots {
  display: flex;
  align-items: center;
  gap: 5px;
  flex: 1;
  justify-content: center;
}

.legend-size-dots i {
  display: block;
  border-radius: 50%;
  background: rgba(233, 238, 247, 0.55);
  border: 1px solid rgba(255, 255, 255, 0.25);
}

