  selected,
  now,
  flyToken,
  onSelect,
  onBoundsChange,
}: MapViewProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<MapLibreMap | null>(null);
  const [ready, setReady] = useState(false);
  const [hover, setHover] = useState<HoverState | null>(null);

  // Latest props for the imperative MapLibre handlers, which are bound once.
  const quakesRef = useRef(quakes);
  quakesRef.current = quakes;
  const nowRef = useRef(now);
  nowRef.current = now;
  const onSelectRef = useRef(onSelect);
  onSelectRef.current = onSelect;
  const onBoundsChangeRef = useRef(onBoundsChange);
  onBoundsChangeRef.current = onBoundsChange;
  const colorModeRef = useRef(colorMode);
  colorModeRef.current = colorMode;
  const showPlatesRef = useRef(showPlates);
  showPlatesRef.current = showPlates;
  const basemapRef = useRef(basemapId);
  basemapRef.current = basemapId;
  const selectedRef = useRef(selected);
  selectedRef.current = selected;

  const projectionRef = useRef(projection);
  projectionRef.current = projection;

  /** (Re)create every app-owned source and layer on top of the current style. */
  const installLayers = useCallback((map: MapLibreMap) => {
    const theme = basemap(basemapRef.current);

    // A new style resets the projection, so re-assert it before anything paints.
    map.setProjection({ type: projectionRef.current === "globe" ? "globe" : "mercator" });

    if (!map.getSource(SRC_PLATES)) {
      map.addSource(SRC_PLATES, { type: "geojson", data: "/data/plate-boundaries.json" });
    }
    if (!map.getLayer(LYR_PLATES)) {
      map.addLayer({
        id: LYR_PLATES,
        type: "line",
        source: SRC_PLATES,
        layout: {
          "line-cap": "round",
          "line-join": "round",
          visibility: showPlatesRef.current ? "visible" : "none",
        },
        paint: {
          "line-color": theme.plateColor,
          "line-opacity": 0.75,
          "line-width": ["interpolate", ["linear"], ["zoom"], 0, 0.6, 4, 1.3, 9, 2.4],
          "line-dasharray": [3, 2],
        },
      });
    }

    if (!map.getSource(SRC_QUAKES)) {
      map.addSource(SRC_QUAKES, {
        type: "geojson",
        // Explicitly unclustered: one dot per event, always.
        cluster: false,
        promoteId: "qid",
        data: toCollection(quakesRef.current, nowRef.current),
      });
    }

    const color = colorExpression(colorModeRef.current);

    if (!map.getLayer(LYR_GLOW)) {
      map.addLayer({
        id: LYR_GLOW,
        type: "circle",
        source: SRC_QUAKES,
        // Only events worth drawing attention to get a halo, otherwise a dense
        // aftershock sequence turns the map into fog.
        filter: [">=", ["get", "mag"], 3.5],
        paint: {
          "circle-color": color,
          "circle-radius": radiusExpression(2.4),
          "circle-blur": 1,
          "circle-opacity": 0.28,
        },
      });
    }

    if (!map.getLayer(LYR_CORE)) {
      map.addLayer({
        id: LYR_CORE,
        type: "circle",
        source: SRC_QUAKES,
        paint: {
          "circle-color": color,
          "circle-radius": radiusExpression(),
          "circle-opacity": [
            "interpolate",
            ["linear"],
            ["get", "mag"],
            0,
            0.62,
            3,
            0.82,
            6,
            0.95,
          ],
          "circle-stroke-color": [
            "case",
            ["boolean", ["feature-state", "hover"], false],
            "#ffffff",
            theme.haloColor,
          ],
          "circle-stroke-width": [
            "case",
            ["boolean", ["feature-state", "hover"], false],
            2,
            ["interpolate", ["linear"], ["get", "mag"], 2, 0.4, 5, 1.1],
          ],
          "circle-stroke-opacity": 0.9,
        },
      });
    }

    if (!map.getLayer(LYR_SELECTED)) {
      map.addLayer({
        id: LYR_SELECTED,
        type: "circle",
        source: SRC_QUAKES,
        filter: ["==", ["get", "qid"], "�"],
        paint: {
          "circle-color": "rgba(0,0,0,0)",
          "circle-radius": 14,
          "circle-stroke-color": "#ffffff",
          "circle-stroke-width": 2,
          "circle-stroke-opacity": 1,
        },
      });
    }

    if (!map.getLayer(LYR_HIT)) {
      // Invisible, generously sized target so an M0.4 dot is still tappable.
      map.addLayer({
        id: LYR_HIT,
        type: "circle",
        source: SRC_QUAKES,
        paint: {
          "circle-color": "rgba(0,0,0,0)",
          "circle-radius": ["+", radiusExpression(), 7],
        },
      });
    }
  }, []);

  /* ---------------------------------------------------------------------- */
  /* Map lifecycle                                                          */
  /* ---------------------------------------------------------------------- */

  useEffect(() => {
    if (!containerRef.current || mapRef.current) return;

    const map = new maplibregl.Map({
      container: containerRef.current,
      style: basemap(basemapRef.current).style,
      center: [12, 18],
      zoom: 1.35,
      minZoom: 0.6,
      maxZoom: 14,
      attributionControl: false,
      dragRotate: false,
      pitchWithRotate: false,
      hash: false,
    });
    mapRef.current = map;

    map.addControl(new maplibregl.NavigationControl({ showCompass: false }), "bottom-right");
    map.addControl(
      new maplibregl.AttributionControl({ compact: true, customAttribution: USGS_ATTRIBUTION }),
      "bottom-right",
    );
    map.addControl(
      new maplibregl.ScaleControl({ maxWidth: 96, unit: "metric" }),
      "bottom-left",
    );
    map.touchZoomRotate.disableRotation();

    let hovered: string | null = null;
    const clearHover = () => {
      if (hovered !== null) {
        map.setFeatureState({ source: SRC_QUAKES, id: hovered }, { hover: false });
        hovered = null;
      }
      map.getCanvas().style.cursor = "";
      setHover(null);
    };

    map.on("style.load", () => {
      installLayers(map);
      setReady(true);
    });

    map.on("mousemove", LYR_HIT, (event) => {
      const feature = event.features?.[0];
      const id = feature?.properties?.qid as string | undefined;
      if (!id) return;
      if (hovered !== id) {
        if (hovered !== null) {
          map.setFeatureState({ source: SRC_QUAKES, id: hovered }, { hover: false });
        }
        hovered = id;
        map.setFeatureState({ source: SRC_QUAKES, id }, { hover: true });
      }
      map.getCanvas().style.cursor = "pointer";
      const quake = quakesRef.current.find((q) => q.id === id);
      if (quake) {
        const width = map.getCanvas().clientWidth;
        setHover({
          quake,
          x: event.point.x,
          y: event.point.y,
          flip: event.point.x > width - 270,
        });
      }
    });

    map.on("mouseleave", LYR_HIT, clearHover);
    map.on("dragstart", clearHover);
    map.on("zoomstart", clearHover);

    map.on("click", (event) => {
      const features = map.queryRenderedFeatures(event.point, { layers: [LYR_HIT] });
      if (features.length === 0) {
        onSelectRef.current(null);
        return;
      }
      // Multiple dots can overlap; prefer the largest magnitude under the cursor.
      let best = features[0];
      for (const feature of features) {
        if (Number(feature.properties?.mag ?? 0) > Number(best.properties?.mag ?? 0)) best = feature;
      }
      onSelectRef.current((best.properties?.qid as string) ?? null);
    });

    const emitBounds = () => {
      const b = map.getBounds();
      onBoundsChangeRef.current({
        west: b.getWest(),
        south: b.getSouth(),
        east: b.getEast(),
        north: b.getNorth(),
      });
    };
    map.on("moveend", emitBounds);
    map.once("load", emitBounds);

    return () => {
      map.remove();
      mapRef.current = null;
      setReady(false);
    };
  }, [installLayers]);

  /* ---------------------------------------------------------------------- */
  /* Prop-driven updates                                                    */
  /* ---------------------------------------------------------------------- */

  // Basemap switch: setStyle tears down every layer, `style.load` rebuilds them.
  useEffect(() => {
    const map = mapRef.current;
    if (!map) return;
    setReady(false);
    map.setStyle(basemap(basemapId).style);
  }, [basemapId]);

  useEffect(() => {
    const map = mapRef.current;
    if (!map) return;
    map.setProjection({ type: projection === "globe" ? "globe" : "mercator" });
  }, [projection]);

  useEffect(() => {
    const map = mapRef.current;
    if (!map || !ready) return;
    const source = map.getSource(SRC_QUAKES) as GeoJSONSource | undefined;
    source?.setData(toCollection(quakes, now));
  }, [quakes, now, ready]);

  useEffect(() => {
    const map = mapRef.current;
    if (!map || !ready || !map.getLayer(LYR_CORE)) return;
    const color = colorExpression(colorMode);
    map.setPaintProperty(LYR_CORE, "circle-color", color);
    map.setPaintProperty(LYR_GLOW, "circle-color", color);
  }, [colorMode, ready]);

  useEffect(() => {
    const map = mapRef.current;
    if (!map || !ready || !map.getLayer(LYR_PLATES)) return;
    map.setLayoutProperty(LYR_PLATES, "visibility", showPlates ? "visible" : "none");
  }, [showPlates, ready]);

  // Selected ring: filter to the chosen event, then breathe.
  useEffect(() => {
    const map = mapRef.current;
    if (!map || !ready || !map.getLayer(LYR_SELECTED)) return;

    map.setFilter(LYR_SELECTED, ["==", ["get", "qid"], selected?.id ?? "�"]);
    if (!selected) return;

    map.setPaintProperty(LYR_SELECTED, "circle-stroke-color", quakeColor(colorMode, selected, now));

    let frame = 0;
    const start = performance.now();
    const tick = (t: number) => {
      const phase = ((t - start) % 1800) / 1800;
      const eased = 1 - (1 - phase) ** 3;
      map.setPaintProperty(LYR_SELECTED, "circle-radius", 10 + eased * 26);
      map.setPaintProperty(LYR_SELECTED, "circle-stroke-opacity", 0.9 * (1 - eased));
      frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [selected, colorMode, now, ready]);

  // Camera moves are requested explicitly so that selecting from the map does
  // not yank the view out from under the pointer.
  useEffect(() => {
    const map = mapRef.current;
    if (!map || !selected || flyToken === 0) return;
    map.flyTo({
      center: [selected.lon, selected.lat],
      zoom: Math.max(map.getZoom(), 4.5),
      duration: 1100,
      essential: true,
    });
  }, [flyToken, selected]);

  // Empty state / data cleared.
  useEffect(() => {
    const map = mapRef.current;
    if (!map || !ready || quakes.length > 0) return;
    const source = map.getSource(SRC_QUAKES) as GeoJSONSource | undefined;
    source?.setData(EMPTY_COLLECTION);
  }, [quakes.length, ready]);

  const fitAll = useCallback(() => {
    const map = mapRef.current;
    const list = quakesRef.current;
    if (!map || list.length === 0) return;
    let west = 180;
    let east = -180;
    let south = 90;
    let north = -90;
    for (const q of list) {
      west = Math.min(west, q.lon);
      east = Math.max(east, q.lon);
      south = Math.min(south, q.lat);
      north = Math.max(north, q.lat);
    }
    const bounds: LngLatBoundsLike = [
      [west, south],
      [east, north],
    ];
    map.fitBounds(bounds, { padding: 64, duration: 900, maxZoom: 8 });
  }, []);

  const resetView = useCallback(() => {
    mapRef.current?.flyTo({ center: [12, 18], zoom: 1.35, duration: 900 });
  }, []);

  return (
    <div className="map-shell">
      <div ref={containerRef} className="map-canvas" role="application" aria-label="World map of recent earthquakes" />

      <div className="map-actions">
        <button type="button" className="map-btn" onClick={fitAll} title="Zoom to the filtered events">
          Fit results
        </button>
        <button type="button" className="map-btn" onClick={resetView} title="Back to the world view">
          Reset view
        </button>
      </div>

      {hover ? <MapTooltip hover={hover} colorMode={colorMode} now={now} /> : null}
    </div>
  );
}

function MapTooltip({
  hover,
  colorMode,
  now,
}: {
  hover: HoverState;
  colorMode: ColorMode;
  now: number;
}) {
  const { quake, x, y, flip } = hover;
  const color = quakeColor(colorMode, quake, now);
  return (
    <div
      className="map-tooltip"
      style={{
        transform: `translate(${x + (flip ? -14 : 14)}px, ${y - 14}px) translateX(${flip ? "-100%" : "0"})`,
      }}
    >
      <div className="map-tooltip-head">
        <span className="map-tooltip-mag" style={{ color }}>
          M {magnitudeLabel(quake.mag)}
        </span>
        <span className="map-tooltip-time">{relativeTime(quake.time, now)}</span>
      </div>
      <div className="map-tooltip-place">{quake.place}</div>
      <div className="map-tooltip-depth">{depthLabel(quake.depth)} deep</div>
    </div>
  );
}

input.content:
.detail {
  position: absolute;
  top: 12px;
  right: 12px;
  bottom: 12px;
  width: min(408px, 46%);
  display: flex;
  flex-direction: column;
  border-radius: var(--radius-lg);
  border: 1px solid var(--line-strong);
  background: rgba(9, 13, 20, 0.94);
  box-shadow: var(--shadow-panel);
  backdrop-filter: blur(18px);
  z-index: 14;
  overflow: hidden;
  animation: detail-in 0.24s cubic-bezier(0.16, 1, 0.3, 1);
}

@keyframes detail-in {
  from {
    opacity: 0;
    transform: translateX(16px) scale(0.985);
  }
}

.detail-head {
  padding: 13px 16px 14px;
  border-bottom: 1px solid var(--line);
  background: linear-gradient(180deg, rgba(148, 163, 184, 0.05), transparent);
}

.detail-head-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 12px;
}

.detail-eyebrow {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.13em;
  text-transform: uppercase;
  color: var(--text-3);
}

.detail-status {
  padding: 2px 6px;
  border-radius: 4px;
  background: var(--surface-2);
  border: 1px solid var(--line);
  letter-spacing: 0.07em;
  color: var(--text-2);
}

.detail-status[data-status="reviewed"] {
  color: #86efac;
  border-color: rgba(134, 239, 172, 0.28);
  background: rgba(134, 239, 172, 0.09);
}

.detail-hero {
  display: flex;
  align-items: flex-start;
  gap: 14px;
}

.detail-mag {
  flex-shrink: 0;
  width: 74px;
  height: 74px;
  display: grid;
  place-content: center;
  justify-items: center;
  gap: 1px;
  border-radius: var(--radius);
  border: 1.5px solid;
  background: rgba(255, 255, 255, 0.04);
}

.detail-mag-value {
  font-family: var(--font-mono);
  font-size: 27px;
  font-weight: 700;
  line-height: 1;
  letter-spacing: -0.03em;
  font-variant-numeric: tabular-nums;
}

.detail-mag-type {
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.12em;
  opacity: 0.72;
}

.detail-hero-text {
  min-width: 0;
  padding-top: 2px;
}

.detail-place {
  font-size: 16px;
  font-weight: 600;
  line-height: 1.25;
  letter-spacing: -0.01em;
}

.detail-prefix {
  color: var(--text-3);
  font-weight: 400;
}

.detail-when {
  margin-top: 6px;
  display: flex;
  align-items: baseline;
  gap: 7px;
  flex-wrap: wrap;
  font-size: 11.5px;
  color: var(--text-2);
  font-variant-numeric: tabular-nums;
}

.detail-when strong {
  color: var(--text);
}

.detail-when-sep {
  opacity: 0.4;
}

.detail-when-utc {
  margin-top: 2px;
  font-size: 10.5px;
  color: var(--text-3);
  font-variant-numeric: tabular-nums;
}

.detail-flags {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
  margin-top: 13px;
}

.flag {
  padding: 3px 9px;
  border-radius: 99px;
  border: 1px solid var(--line);
  background: var(--surface-2);
  font-size: 10.5px;
  font-weight: 550;
  color: var(--text-2);
  white-space: nowrap;
}

.flag-tsunami {
  background: rgba(56, 189, 248, 0.14);
  border-color: rgba(56, 189, 248, 0.4);
  color: #a5e8ff;
}

.flag-sig {
  background: rgba(251, 146, 60, 0.13);
  border-color: rgba(251, 146, 60, 0.36);
  color: #fed7aa;
}

.flag-green {
  background: rgba(74, 222, 128, 0.12);
  border-color: rgba(74, 222, 128, 0.35);
  color: #bbf7d0;
}

.flag-yellow {
  background: rgba(250, 204, 21, 0.14);
  border-color: rgba(250, 204, 21, 0.38);
  color: #fef08a;
}

.flag-orange {
  background: rgba(251, 146, 60, 0.16);
  border-color: rgba(251, 146, 60, 0.45);
  color: #fed7aa;
}

.flag-red {
  background: rgba(239, 68, 68, 0.18);
  border-color: rgba(239, 68, 68, 0.5);
  color: #fecaca;
}

.detail-actions {
  display: flex;
  gap: 7px;
  margin-top: 14px;
}

/* ------------------------------------------------------------------ */
/* Body                                                                */
/* ------------------------------------------------------------------ */

.detail-body {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  padding: 4px 16px 18px;
}

.detail-section {
  padding: 14px 0;
  border-bottom: 1px solid rgba(148, 163, 184, 0.08);
}

.detail-section:last-of-type {
  border-bottom: none;
}

.detail-section-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 10px;
}

.detail-section-head h3 {
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.11em;
  text-transform: uppercase;
  color: var(--text-2);
}

.detail-section-head span {
  font-size: 10px;
  color: var(--text-3);
  text-align: right;
}

.detail-empty {
  font-size: 11.5px;
  color: var(--text-3);
}

.detail-id {
  margin-top: 14px;
  padding-top: 12px;
  border-top: 1px solid rgba(148, 163, 184, 0.08);
  font-size: 10.5px;
  color: var(--text-3);
}

.detail-id code {
  color: var(--text-2);
}

/* ------------------------------------------------------------------ */
/* Facts grid                                                          */
/* ------------------------------------------------------------------ */

.facts {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1px;
  background: var(--line);
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  overflow: hidden;
}

.fact {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 8px 10px;
  background: var(--surface-1);
}

.fact dt {
  font-size: 9.5px;
  font-weight: 600;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: var(--text-3);
}

.fact dd {
  font-family: var(--font-mono);
  font-size: 12px;
  color: var(--text);
  font-variant-numeric: tabular-nums;
}

/* ------------------------------------------------------------------ */
/* Energy                                                              */
/* ------------------------------------------------------------------ */

.energy-line {
  font-size: 12.5px;
  color: var(--text-2);
}

.energy-line strong {
  color: var(--text);
  font-family: var(--font-mono);
  font-size: 13px;
}

.energy-note {
  margin-top: 4px;
  font-size: 10.5px;
  color: var(--text-3);
}

/* ------------------------------------------------------------------ */
/* Intensity meter                                                     */
/* ------------------------------------------------------------------ */

.intensity-scale {
  display: grid;
  grid-template-columns: repeat(11, 1fr);
  gap: 2px;
  height: 16px;
}

.intensity-step {
  position: relative;
  border-radius: 2px;
  opacity: 0.34;
  transition: opacity 0.2s ease;
}

.intensity-step.is-active {
  opacity: 1;
  box-shadow: 0 0 0 1.5px rgba(255, 255, 255, 0.85);
}

.intensity-caret {
  position: absolute;
  left: 50%;
  bottom: -7px;
  width: 0;
  height: 0;
  transform: translateX(-50%);
  border-left: 4px solid transparent;
  border-right: 4px solid transparent;
  border-bottom: 5px solid rgba(255, 255, 255, 0.85);
}

.intensity-read {
  display: flex;
  align-items: baseline;
  gap: 9px;
  margin-top: 13px;
}

.intensity-roman {
  font-family: var(--font-mono);
  font-size: 17px;
  font-weight: 700;
  letter-spacing: 0.02em;
}

.intensity-word {
  font-size: 12.5px;
  color: var(--text-2);
  flex: 1;
}

.intensity-num {
  font-family: var(--font-mono);
  font-size: 10.5px;
  color: var(--text-3);
}

/* ------------------------------------------------------------------ */
/* Depth profile                                                       */
/* ------------------------------------------------------------------ */

.depth-profile {
  display: flex;
  flex-direction: column;
  gap: 9px;
}

.depth-scale {
  position: relative;
  height: 128px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--line);
  background: linear-gradient(180deg, rgba(148, 163, 184, 0.07), rgba(2, 4, 8, 0.6));
  overflow: hidden;
}

.depth-band {
  position: absolute;
  left: 0;
  right: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 10px;
  border-top: 1px dashed rgba(148, 163, 184, 0.16);
}

.depth-band:first-of-type {
  border-top: none;
}

.depth-band-label {
  font-size: 10.5px;
  font-weight: 600;
  color: var(--text-2);
}

.depth-band-range {
  font-family: var(--font-mono);
  font-size: 9.5px;
  color: var(--text-3);
}

.depth-surface {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: linear-gradient(90deg, rgba(233, 238, 247, 0.6), rgba(233, 238, 247, 0.15));
}

.depth-marker {
  position: absolute;
  left: 0;
  right: 0;
  height: 2px;
  box-shadow: 0 0 12px currentColor;
}

.depth-marker-flag {
  position: absolute;
  right: 8px;
  top: 50%;
  transform: translateY(-50%);
  padding: 2px 7px;
  border-radius: 4px;
  border: 1px solid;
  background: rgba(5, 7, 11, 0.92);
  font-family: var(--font-mono);
  font-size: 10.5px;
  font-weight: 600;
  white-space: nowrap;
}

.depth-caption {
  font-size: 11.5px;
  color: var(--text-3);
}

/* ------------------------------------------------------------------ */
