/* ------------------------------------------------------------------ */
/* Body                                                                */
/* ------------------------------------------------------------------ */

.detail-body {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  padding: 4px 16px 18px;
}

.detail-section {
  padding: 14px 0;
  border-bottom: 1px solid rgba(148, 163, 184, 0.08);
}

.detail-section:last-of-type {
  border-bottom: none;
}

.detail-section-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 10px;
}

.detail-section-head h3 {
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.11em;
  text-transform: uppercase;
  color: var(--text-2);
}

.detail-section-head span {
  font-size: 10px;
  color: var(--text-3);
  text-align: right;
}

.detail-empty {
  font-size: 11.5px;
  color: var(--text-3);
}

.detail-id {
  margin-top: 14px;
  padding-top: 12px;
  border-top: 1px solid rgba(148, 163, 184, 0.08);
  font-size: 10.5px;
  color: var(--text-3);
}

.detail-id code {
  color: var(--text-2);
}

/* ------------------------------------------------------------------ */
/* Facts grid                                                          */
/* ------------------------------------------------------------------ */

.facts {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1px;
  background: var(--line);
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  overflow: hidden;
}

.fact {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 8px 10px;
  background: var(--surface-1);
}

.fact dt {
  font-size: 9.5px;
  font-weight: 600;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: var(--text-3);
}

.fact dd {
  font-family: var(--font-mono);
  font-size: 12px;
  color: var(--text);
  font-variant-numeric: tabular-nums;
}

/* ------------------------------------------------------------------ */
/* Energy                                                              */
/* ------------------------------------------------------------------ */

.energy-line {
  font-size: 12.5px;
  color: var(--text-2);
}

.energy-line strong {
  color: var(--text);
  font-family: var(--font-mono);
  font-size: 13px;
}

.energy-note {
  margin-top: 4px;
  font-size: 10.5px;
  color: var(--text-3);
}

/* ------------------------------------------------------------------ */
/* Intensity meter                                                     */
/* ------------------------------------------------------------------ */

.intensity-scale {
  display: grid;
  grid-template-columns: repeat(11, 1fr);
  gap: 2px;
  height: 16px;
}

.intensity-step {
  position: relative;
  border-radius: 2px;
  opacity: 0.34;
  transition: opacity 0.2s ease;
}

.intensity-step.is-active {
  opacity: 1;
  box-shadow: 0 0 0 1.5px rgba(255, 255, 255, 0.85);
}

.intensity-caret {
  position: absolute;
  left: 50%;
  bottom: -7px;
  width: 0;
  height: 0;
  transform: translateX(-50%);
  border-left: 4px solid transparent;
  border-right: 4px solid transparent;
  border-bottom: 5px solid rgba(255, 255, 255, 0.85);
}

.intensity-read {
  display: flex;
  align-items: baseline;
  gap: 9px;
  margin-top: 13px;
}

.intensity-roman {
  font-family: var(--font-mono);
  font-size: 17px;
  font-weight: 700;
  letter-spacing: 0.02em;
}

.intensity-word {
  font-size: 12.5px;
  color: var(--text-2);
  flex: 1;
}

.intensity-num {
  font-family: var(--font-mono);
  font-size: 10.5px;
  color: var(--text-3);
}

/* ------------------------------------------------------------------ */
/* Depth profile                                                       */
/* ------------------------------------------------------------------ */

.depth-profile {
  display: flex;
  flex-direction: column;
  gap: 9px;
}

.depth-scale {
  position: relative;
  height: 128px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--line);
  background: linear-gradient(180deg, rgba(148, 163, 184, 0.07), rgba(2, 4, 8, 0.6));
  overflow: hidden;
}

.depth-band {
  position: absolute;
  left: 0;
  right: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 10px;
  border-top: 1px dashed rgba(148, 163, 184, 0.16);
}

.depth-band:first-of-type {
  border-top: none;
}

.depth-band-label {
  font-size: 10.5px;
  font-weight: 600;
  color: var(--text-2);
}

.depth-band-range {
  font-family: var(--font-mono);
  font-size: 9.5px;
  color: var(--text-3);
}

.depth-surface {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: linear-gradient(90deg, rgba(233, 238, 247, 0.6), rgba(233, 238, 247, 0.15));
}

.depth-marker {
  position: absolute;
  left: 0;
  right: 0;
  height: 2px;
  box-shadow: 0 0 12px currentColor;
}

.depth-marker-flag {
  position: absolute;
  right: 8px;
  top: 50%;
  transform: translateY(-50%);
  padding: 2px 7px;
  border-radius: 4px;
  border: 1px solid;
  background: rgba(5, 7, 11, 0.92);
