1	/**
2	 * USGS Earthquake Hazards Program real-time feeds.
3	 * https://earthquake.usgs.gov/earthquakes/feed/v1.0/geojson.php
4	 *
5	 * No API key required. Feeds are regenerated by USGS every minute.
6	 */
7	
8	export type WindowId = "hour" | "day" | "week" | "month";
9	
10	export interface FeedWindow {
11	  id: WindowId;
12	  /** Short label used in the segmented control. */
13	  label: string;
14	  /** Long label used in prose ("in the past 24 hours"). */
15	  longLabel: string;
16	  /** Duration of the window in milliseconds. */
17	  durationMs: number;
18	  /** USGS feed slug. */
19	  slug: string;
20	  /** Completeness caveat shown next to the control, if the feed is filtered. */
21	  note: string | null;
22	}
23	
24	export const FEED_WINDOWS: FeedWindow[] = [
25	  {
26	    id: "hour",
27	    label: "1H",
28	    longLabel: "past hour",
29	    durationMs: 3_600_000,
30	    slug: "all_hour",
31	    note: null,
32	  },
33	  {
34	    id: "day",
35	    label: "24H",
36	    longLabel: "past 24 hours",
37	    durationMs: 86_400_000,
38	    slug: "all_day",
39	    note: null,
40	  },
41	  {
42	    id: "week",
43	    label: "7D",
44	    longLabel: "past 7 days",
45	    durationMs: 604_800_000,
46	    slug: "all_week",
47	    note: null,
48	  },
49	  {
50	    id: "month",
51	    label: "30D",
52	    longLabel: "past 30 days",
53	    durationMs: 2_592_000_000,
54	    // The unfiltered 30-day feed is a 7 MB download dominated by micro-events in
55	    // densely instrumented regions; the M2.5+ feed is the globally comparable one.
56	    slug: "2.5_month",
57	    note: "M2.5+",
58	  },
59	];
60	
61	export function feedWindow(id: WindowId): FeedWindow {
62	  return FEED_WINDOWS.find((w) => w.id === id) ?? FEED_WINDOWS[1];
63	}
64	
65	export function feedUrl(id: WindowId): string {
66	  return `https://earthquake.usgs.gov/earthquakes/feed/v1.0/summary/${feedWindow(id).slug}.geojson`;
67	}
68	
69	/** Alert levels come from the USGS PAGER impact model. */
70	export type AlertLevel = "green" | "yellow" | "orange" | "red";
71	
72	export interface Quake {
73	  id: string;
74	  /** Moment / local magnitude. Null for a handful of unreviewed events. */
75	  mag: number;
76	  magType: string | null;
77	  /** "68 km SSW of Whitehorse, Canada" */
78	  place: string;
79	  /** "M 5.0 - 68 km SSW of Whitehorse, Canada" */
80	  title: string;
81	  /** Origin time, ms since epoch (UTC). */
82	  time: number;
83	  updated: number;
84	  lon: number;
85	  lat: number;
86	  /** Depth below sea level in km. Negative values exist for a few shallow events. */
87	  depth: number;
88	  /** USGS significance score, 0–1000. */
89	  sig: number;
90	  /** Number of "Did you feel it?" responses. */
91	  felt: number | null;
92	  /** Community-reported intensity (DYFI), Modified Mercalli. */
93	  cdi: number | null;
94	  /** Instrumental intensity (ShakeMap), Modified Mercalli. */
95	  mmi: number | null;
96	  alert: AlertLevel | null;
97	  tsunami: boolean;
98	  status: string;
99	  /** Event type: "earthquake", "quarry blast", "explosion", "ice quake"… */
100	  type: string;
101	  /** Number of seismic stations used to locate the event. */
102	  nst: number | null;
103	  /** Largest azimuthal gap between stations, degrees. Lower is better. */
104	  gap: number | null;
105	  /** Horizontal distance to the nearest station, degrees. */
106	  dmin: number | null;
107	  rms: number | null;
108	  net: string;
109	  url: string;
110	}
111	
112	export interface FeedResult {
113	  quakes: Quake[];
114	  /** Time the feed itself was generated by USGS. */
115	  generated: number;
116	  title: string;
117	}
118	
119	interface RawFeature {
120	  id?: string;
121	  properties?: Record<string, unknown>;
122	  geometry?: { coordinates?: unknown } | null;
123	}
124	
125	function num(value: unknown): number | null {
126	  return typeof value === "number" && Number.isFinite(value) ? value : null;
127	}
128	
129	function str(value: unknown): string | null {
130	  return typeof value === "string" && value.length > 0 ? value : null;
131	}
132	
133	const ALERTS: AlertLevel[] = ["green", "yellow", "orange", "red"];
134	
