406	    let south = 90;
407	    let north = -90;
408	    for (const q of list) {
409	      west = Math.min(west, q.lon);
410	      east = Math.max(east, q.lon);
411	      south = Math.min(south, q.lat);
412	      north = Math.max(north, q.lat);
413	    }
414	    const bounds: LngLatBoundsLike = [
415	      [west, south],
416	      [east, north],
417	    ];
418	    map.fitBounds(bounds, { padding: 64, duration: 900, maxZoom: 8 });
419	  }, []);
420	
421	  const resetView = useCallback(() => {
422	    mapRef.current?.flyTo({ center: [12, 18], zoom: 1.35, duration: 900 });
423	  }, []);
424	
425	  return (
426	    <div className="map-shell">
427	      <div ref={containerRef} className="map-canvas" role="application" aria-label="World map of recent earthquakes" />
428	
429	      <div className="map-actions">
430	        <button type="button" className="map-btn" onClick={fitAll} title="Zoom to the filtered events">
431	          Fit results
432	        </button>
433	        <button type="button" className="map-btn" onClick={resetView} title="Back to the world view">
434	          Reset view
435	        </button>
436	      </div>
437	
438	      {hover ? <MapTooltip hover={hover} colorMode={colorMode} now={now} /> : null}
439	    </div>
440	  );
441	}
442	
443	function MapTooltip({
444	  hover,
445	  colorMode,
446	  now,
447	}: {
448	  hover: HoverState;
449	  colorMode: ColorMode;
450	  now: number;
451	}) {
452	  const { quake, x, y, flip } = hover;
453	  const color = quakeColor(colorMode, quake, now);
454	  return (
455	    <div
456	      className="map-tooltip"
457	      style={{
458	        transform: `translate(${x + (flip ? -14 : 14)}px, ${y - 14}px) translateX(${flip ? "-100%" : "0"})`,
459	      }}
460	    >
461	      <div className="map-tooltip-head">
462	        <span className="map-tooltip-mag" style={{ color }}>
463	          M {magnitudeLabel(quake.mag)}
464	        </span>
465	        <span className="map-tooltip-time">{relativeTime(quake.time, now)}</span>
466	      </div>
467	      <div className="map-tooltip-place">{quake.place}</div>
468	      <div className="map-tooltip-depth">{depthLabel(quake.depth)} deep</div>
469	    </div>
470	  );
471	}
