import { connect, waitFor } from "./cdp.mjs";

const SCRATCH = new URL(".", import.meta.url).pathname;
const cdp = await connect();

await cdp.send("Emulation.setDeviceMetricsOverride", {
  width: 1600,
  height: 1000,
  deviceScaleFactor: 2,
  mobile: false,
});

await cdp.goto("http://localhost:9219/");
await waitFor(cdp, "window.__map && window.__map.isStyleLoaded()", { label: "map style" });
await waitFor(
  cdp,
  "window.__map.getSource('quakes') && window.__map.getSource('quakes')._data && window.__map.getSource('quakes')._data.features.length > 0",
  { label: "quake data loaded", timeout: 40000 },
);
// Let tiles paint.
await new Promise((r) => setTimeout(r, 5000));

const report = await cdp.evaluate(`
  const map = window.__map;
  const src = map.getSource('quakes');
  const data = src._data;
  const rendered = map.queryRenderedFeatures({ layers: ['quake-core'] });

  // Positional fidelity: does every rendered dot sit where its raw coordinates say?
  const sample = data.features.slice(0, 400);
  let maxDrift = 0;
  for (const f of sample) {
    const [lon, lat] = f.geometry.coordinates;
    const p = map.project([lon, lat]);
    const back = map.unproject([p.x, p.y]);
    maxDrift = Math.max(maxDrift, Math.abs(back.lng - lon) + Math.abs(back.lat - lat));
  }

  // Clustering check: any aggregated feature would carry point_count / cluster props.
  const clustered = rendered.filter(f => 'point_count' in (f.properties||{}) || f.properties?.cluster);

  // Unique geometries among rendered features == no merging of distinct events.
  const ids = new Set(rendered.map(f => f.properties.qid));

  return {
    title: document.title,
    h1: document.querySelector('h1.header-title')?.textContent,
    canvas: (() => { const c = map.getCanvas(); return { w: c.clientWidth, h: c.clientHeight }; })(),
    styleName: map.getStyle().name || '(unnamed)',
    basemapRasterOrVector: map.getStyle().layers.filter(l => l.id.startsWith('quake')||l.id==='plate-boundaries').length,
    totalStyleLayers: map.getStyle().layers.length,
    sourceClusterOption: src.workerOptions ? src.workerOptions.cluster : src._options?.cluster,
    featureCount: data.features.length,
    renderedCoreFeatures: rendered.length,
    uniqueRenderedIds: ids.size,
    clusteredFeatures: clustered.length,
    maxProjectionDriftDeg: maxDrift,
    firstFeature: data.features[0],
    listRows: document.querySelectorAll('[role="option"]').length,
    legendSwatches: document.querySelectorAll('.legend-gradient, .legend-bar').length,
    statTexts: [...document.querySelectorAll('.stat-value, .header-stat-value')].map(n=>n.textContent).slice(0,6),
    resultReadout: document.querySelector('.control-readout, .panel-readout')?.textContent ?? null,
  };
`);

console.log(JSON.stringify(report, null, 2));
console.log("\n--- console ---");
console.log(cdp.consoleLines.slice(-25).join("\n") || "(clean)");

await cdp.screenshot(`${SCRATCH}/shot-01-overview.png`);
cdp.close();

