/**
 * The colour system.
 *
 * Three interchangeable encodings, each a piecewise-linear ramp over stops.
 * Every ramp is also the source of truth for the on-map legend, so the swatches
 * a user reads and the pixels they see can never drift apart.
 */

import type { Quake } from "./usgs";

export type ColorMode = "magnitude" | "depth" | "recency";

export interface Stop {
  /** Position along the ramp's domain (magnitude, km, or ms of age). */
  at: number;
  color: string;
  /** Legend caption. Omitted on interior stops that only shape the gradient. */
  label?: string;
}

export interface Ramp {
  id: ColorMode;
  name: string;
  /** One line explaining what the colour is telling you. */
  blurb: string;
  unit: string;
  stops: Stop[];
  /** Legend tick captions are read left-to-right from `stops`; reverse for depth. */
  scale: "linear" | "log-age";
}

/** Rising heat: cool cyan for the imperceptible, white-hot for the destructive. */
const MAGNITUDE_STOPS: Stop[] = [
  { at: 0, color: "#22d3ee", label: "0" },
  { at: 1.5, color: "#38e0a5", label: "1.5" },
  { at: 3, color: "#a3e635", label: "3" },
  { at: 4.5, color: "#facc15", label: "4.5" },
  { at: 6, color: "#f97316", label: "6" },
  { at: 7, color: "#ef4444", label: "7" },
  { at: 8, color: "#fecdd3", label: "8+" },
];

/**
 * Depth follows seismological convention: shallow events (the damaging ones,
 * because their energy has less crust to cross) burn hot; slab events deep in
 * the mantle cool through violet into blue.
 */
const DEPTH_STOPS: Stop[] = [
  { at: 0, color: "#fde047", label: "0" },
  { at: 35, color: "#fb923c", label: "35" },
  { at: 70, color: "#f43f5e", label: "70" },
  { at: 150, color: "#c026d3", label: "150" },
  { at: 300, color: "#7c3aed", label: "300" },
  { at: 500, color: "#3b82f6", label: "500" },
  { at: 700, color: "#67e8f9", label: "700" },
];

/** A cooling ember: minutes old is white-hot, weeks old is a dark cinder. */
const RECENCY_STOPS: Stop[] = [
  { at: 0, color: "#fff7ed", label: "now" },
  { at: 3_600_000, color: "#fde047", label: "1h" },
  { at: 21_600_000, color: "#fb923c", label: "6h" },
  { at: 86_400_000, color: "#ef4444", label: "1d" },
  { at: 604_800_000, color: "#9f1239", label: "7d" },
  { at: 2_592_000_000, color: "#6d3550", label: "30d" },
];

export const RAMPS: Record<ColorMode, Ramp> = {
  magnitude: {
    id: "magnitude",
    name: "Magnitude",
    blurb: "Energy released. Each whole step is ~32× more energy.",
    unit: "M",
    stops: MAGNITUDE_STOPS,
    scale: "linear",
  },
  depth: {
    id: "depth",
    name: "Depth",
    blurb: "Shallow quakes shake the surface hardest. Deep ones mark sinking slabs.",
    unit: "km",
    stops: DEPTH_STOPS,
    scale: "linear",
  },
  recency: {
    id: "recency",
    name: "Recency",
    blurb: "How long ago it struck. Fresh events glow, older ones cool to ember.",
    unit: "ago",
    stops: RECENCY_STOPS,
    scale: "log-age",
  },
};

export const COLOR_MODES = Object.values(RAMPS);

/* -------------------------------------------------------------------------- */
/* Colour maths                                                               */
/* -------------------------------------------------------------------------- */

export interface Rgb {
  r: number;
  g: number;
  b: number;
}

export function hexToRgb(hex: string): Rgb {
  const value = hex.replace("#", "");
  const full =
    value.length === 3
      ? value
          .split("")
          .map((c) => c + c)
          .join("")
      : value;
  const int = Number.parseInt(full, 16);
  return { r: (int >> 16) & 255, g: (int >> 8) & 255, b: int & 255 };
}

export function rgbToHex({ r, g, b }: Rgb): string {
  const part = (n: number) =>
    Math.max(0, Math.min(255, Math.round(n)))
      .toString(16)
      .padStart(2, "0");
  return `#${part(r)}${part(g)}${part(b)}`;
}

export function mixHex(a: string, b: string, t: number): string {
  const from = hexToRgb(a);
  const to = hexToRgb(b);
  const k = Math.max(0, Math.min(1, t));
  return rgbToHex({
    r: from.r + (to.r - from.r) * k,
    g: from.g + (to.g - from.g) * k,
    b: from.b + (to.b - from.b) * k,
  });
}

/** Sample a stop list at `value`, clamping outside the domain. */
export function sampleStops(stops: Stop[], value: number): string {
  if (value <= stops[0].at) return stops[0].color;
  const last = stops[stops.length - 1];
  if (value >= last.at) return last.color;

  for (let i = 1; i < stops.length; i += 1) {
    const prev = stops[i - 1];
    const next = stops[i];
    if (value <= next.at) {
      const span = next.at - prev.at;
      return mixHex(prev.color, next.color, span === 0 ? 0 : (value - prev.at) / span);
    }
  }
  return last.color;
}

/** The value a quake contributes to a given ramp. */
export function rampValue(mode: ColorMode, quake: Quake, now: number): number {
  if (mode === "magnitude") return quake.mag;
  if (mode === "depth") return quake.depth;
  return Math.max(0, now - quake.time);
}

export function quakeColor(mode: ColorMode, quake: Quake, now: number): string {
  return sampleStops(RAMPS[mode].stops, rampValue(mode, quake, now));
}

/**
 * A CSS `linear-gradient` matching the ramp, for legend bars.
 * `log-age` ramps are laid out on a log scale so the first hour is not a sliver.
 */
export function rampGradient(ramp: Ramp): string {
  const positions = stopPositions(ramp);
  const parts = ramp.stops.map((stop, i) => `${stop.color} ${(positions[i] * 100).toFixed(2)}%`);
  return `linear-gradient(90deg, ${parts.join(", ")})`;
}

/** Normalised 0–1 position of each stop along the legend bar. */
export function stopPositions(ramp: Ramp): number[] {
  const stops = ramp.stops;
  if (ramp.scale === "log-age") {
    // log1p keeps the "now" stop at exactly 0 while spreading the decades evenly.
    const max = Math.log1p(stops[stops.length - 1].at);
    return stops.map((s) => Math.log1p(s.at) / max);
  }
  const min = stops[0].at;
  const max = stops[stops.length - 1].at;
  return stops.map((s) => (s.at - min) / (max - min));
}

/* -------------------------------------------------------------------------- */
/* MapLibre expressions                                                       */
/* -------------------------------------------------------------------------- */

/**
 * MapLibre style expressions are heterogeneous nested arrays that the library
 * types as a large discriminated union. Building them programmatically is far
 * more readable with a local alias than with the full spec type.
 */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export type Expression = any;

/**
 * Build the `interpolate` expression that paints the circle layer.
 * Feature properties are pre-computed in `toCollection`, so the GPU reads a
 * plain number and no per-frame JavaScript runs.
 */
export function colorExpression(mode: ColorMode): Expression {
  const ramp = RAMPS[mode];
  const property = mode === "recency" ? "age" : mode === "depth" ? "depth" : "mag";
  const expr: unknown[] = ["interpolate", ["linear"], ["get", property]];
  for (const stop of ramp.stops) {
    expr.push(stop.at, stop.color);
  }
  return expr;
}

/**
 * Circle radius in pixels, scaled by `scale`.
 *
 * Magnitude is already logarithmic, so an exponential ramp on top of it makes
 * a felt M5 unmistakable next to an instrument-only M1 without letting an M8
 * swallow a continent. Radius also grows with zoom, so dense aftershock
 * sequences pull apart as you move in.
 */
export function radiusExpression(scale = 1): Expression {
  const byMag = (zoomScale: number): unknown[] => {
    const k = scale * zoomScale;
    return [
      "interpolate",
      ["exponential", 1.9],
      ["get", "mag"],
      0,
      1.6 * k,
      2,
      2.6 * k,
      4,
      5 * k,
      6,
      10 * k,
      8,
      19 * k,
    ];
  };
  return [
    "interpolate",
    ["linear"],
    ["zoom"],
    0,
    byMag(0.72),
    3,
    byMag(1),
    7,
    byMag(1.7),
    12,
    byMag(2.6),
  ];
}

import { useCallback, useEffect, useRef, useState } from "react";
import {
  AttributionControl,
  Map as MapLibreMap,
  NavigationControl,
  type GeoJSONSource,
  type LngLatBoundsLike,
  type MapLayerMouseEvent,
} from "maplibre-gl";
import "maplibre-gl/dist/maplibre-gl.css";

import { basemap, USGS_ATTRIBUTION, type BasemapId, type ProjectionId } from "../lib/basemaps";
import { colorExpression, quakeColor, radiusExpression, type ColorMode } from "../lib/color";
import { toCollection, EMPTY_COLLECTION } from "../lib/geojson";
import type { Bounds } from "../lib/geo";
import { magnitudeLabel, depthLabel, relativeTime } from "../lib/format";
import type { Quake } from "../lib/usgs";

const SRC_QUAKES = "quakes";
const SRC_PLATES = "plates";
const LYR_PLATES = "plate-boundaries";
const LYR_GLOW = "quake-glow";
const LYR_CORE = "quake-core";
const LYR_SELECTED = "quake-selected";
const LYR_HIT = "quake-hit";

export interface MapViewProps {
  quakes: Quake[];
  colorMode: ColorMode;
  basemapId: BasemapId;
  projection: ProjectionId;
  showPlates: boolean;
  selected: Quake | null;
  now: number;
  /** Bumped by the parent to request a camera move to the selected event. */
  flyToken: number;
  onSelect: (id: string | null) => void;
  onBoundsChange: (bounds: Bounds) => void;
}

interface HoverState {
  quake: Quake;
  x: number;
  y: number;
  /** Render the card to the left of the cursor, near the right edge. */
  flip: boolean;
}

export function MapView({
  quakes,
  colorMode,
  basemapId,
  projection,
  showPlates,
  selected,
  now,
  flyToken,
  onSelect,
  onBoundsChange,
}: MapViewProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<MapLibreMap | null>(null);
  const [ready, setReady] = useState(false);
  const [hover, setHover] = useState<HoverState | null>(null);

  // Latest props for the imperative MapLibre handlers, which are bound once.
  const quakesRef = useRef(quakes);
  quakesRef.current = quakes;
  const nowRef = useRef(now);
  nowRef.current = now;
  const onSelectRef = useRef(onSelect);
  onSelectRef.current = onSelect;
  const onBoundsChangeRef = useRef(onBoundsChange);
  onBoundsChangeRef.current = onBoundsChange;
  const colorModeRef = useRef(colorMode);
  colorModeRef.current = colorMode;
  const showPlatesRef = useRef(showPlates);
  showPlatesRef.current = showPlates;
  const basemapRef = useRef(basemapId);
  basemapRef.current = basemapId;
  const selectedRef = useRef(selected);
  selectedRef.current = selected;

  const projectionRef = useRef(projection);
  projectionRef.current = projection;

  /** (Re)create every app-owned source and layer on top of the current style. */
  const installLayers = useCallback((map: MapLibreMap) => {
    const theme = basemap(basemapRef.current);

    // A new style resets the projection, so re-assert it before anything paints.
    map.setProjection({ type: projectionRef.current === "globe" ? "globe" : "mercator" });

    if (!map.getSource(SRC_PLATES)) {
      map.addSource(SRC_PLATES, { type: "geojson", data: "/data/plate-boundaries.json" });
    }
    if (!map.getLayer(LYR_PLATES)) {
      map.addLayer({
        id: LYR_PLATES,
        type: "line",
        source: SRC_PLATES,
        layout: {
          "line-cap": "round",
          "line-join": "round",
          visibility: showPlatesRef.current ? "visible" : "none",
        },
        paint: {
          "line-color": theme.plateColor,
          "line-opacity": 0.75,
          "line-width": ["interpolate", ["linear"], ["zoom"], 0, 0.6, 4, 1.3, 9, 2.4],
          "line-dasharray": [3, 2],
        },
      });
    }

    if (!map.getSource(SRC_QUAKES)) {
      map.addSource(SRC_QUAKES, {
        type: "geojson",
        // Explicitly unclustered: one dot per event, always.
        cluster: false,
        promoteId: "qid",
        data: toCollection(quakesRef.current, nowRef.current),
      });
    }

    const color = colorExpression(colorModeRef.current);

    if (!map.getLayer(LYR_GLOW)) {
      map.addLayer({
        id: LYR_GLOW,
        type: "circle",
        source: SRC_QUAKES,
        // Only events worth drawing attention to get a halo, otherwise a dense
        // aftershock sequence turns the map into fog.
        filter: [">=", ["get", "mag"], 3.5],
        paint: {
          "circle-color": color,
          "circle-radius": radiusExpression(2.4),
          "circle-blur": 1,
          "circle-opacity": 0.28,
        },
      });
    }

    if (!map.getLayer(LYR_CORE)) {
      map.addLayer({
        id: LYR_CORE,
        type: "circle",
        source: SRC_QUAKES,
        paint: {
          "circle-color": color,
          "circle-radius": radiusExpression(),
          "circle-opacity": [
            "interpolate",
            ["linear"],
            ["get", "mag"],
            0,
            0.62,
            3,
            0.82,
            6,
            0.95,
          ],
          "circle-stroke-color": [
            "case",
            ["boolean", ["feature-state", "hover"], false],
            "#ffffff",
            theme.haloColor,
          ],
          "circle-stroke-width": [
            "case",
            ["boolean", ["feature-state", "hover"], false],
            2,
            ["interpolate", ["linear"], ["get", "mag"], 2, 0.4, 5, 1.1],
          ],
          "circle-stroke-opacity": 0.9,
        },
      });
    }

    if (!map.getLayer(LYR_SELECTED)) {
      map.addLayer({
        id: LYR_SELECTED,
        type: "circle",
        source: SRC_QUAKES,
        filter: ["==", ["get", "qid"], "�"],
        paint: {
          "circle-color": "rgba(0,0,0,0)",
          "circle-radius": 14,
          "circle-stroke-color": "#ffffff",
          "circle-stroke-width": 2,
          "circle-stroke-opacity": 1,
        },
      });
    }

    if (!map.getLayer(LYR_HIT)) {
      // Invisible, generously sized target so an M0.4 dot is still tappable.
      map.addLayer({
        id: LYR_HIT,
        type: "circle",
        source: SRC_QUAKES,
        paint: {
          "circle-color": "rgba(0,0,0,0)",
          "circle-radius": ["+", radiusExpression(), 7],
        },
      });
    }
  }, []);

  /* ---------------------------------------------------------------------- */
  /* Map lifecycle                                                          */
  /* ---------------------------------------------------------------------- */

  useEffect(() => {
    if (!containerRef.current || mapRef.current) return;

    const map = new MapLibreMap({
      container: containerRef.current,
      style: basemap(basemapRef.current).style,
      center: [12, 18],
      zoom: 1.35,
      minZoom: 0.6,
      maxZoom: 14,
      attributionControl: false,
      dragRotate: false,
      pitchWithRotate: false,
      hash: false,
    });
    mapRef.current = map;

    if (import.meta.env.DEV) {
      // Handle for inspecting live layers and features from the console during
      // development. `import.meta.env.DEV` is false in builds, so this is
      // eliminated from the production bundle.
      (window as unknown as { __map?: MapLibreMap }).__map = map;
    }

    // Everything lives bottom-left: the legend owns the top-left and the detail
    // panel owns the right edge.
    map.addControl(new NavigationControl({ showCompass: false }), "bottom-left");
    map.addControl(
      new AttributionControl({ compact: true, customAttribution: USGS_ATTRIBUTION }),
      "bottom-left",
    );
    map.touchZoomRotate.disableRotation();

    let hovered: string | null = null;
    const clearHover = () => {
      if (hovered !== null) {
        map.setFeatureState({ source: SRC_QUAKES, id: hovered }, { hover: false });
        hovered = null;
      }
      map.getCanvas().style.cursor = "";
      setHover(null);
    };

    map.on("style.load", () => {
      installLayers(map);
      setReady(true);
    });

    map.on("mousemove", LYR_HIT, (event: MapLayerMouseEvent) => {
      const feature = event.features?.[0];
      const id = feature?.properties?.qid as string | undefined;
      if (!id) return;
      if (hovered !== id) {
        if (hovered !== null) {
          map.setFeatureState({ source: SRC_QUAKES, id: hovered }, { hover: false });
        }
        hovered = id;
        map.setFeatureState({ source: SRC_QUAKES, id }, { hover: true });
      }
      map.getCanvas().style.cursor = "pointer";
      const quake = quakesRef.current.find((q) => q.id === id);
      if (quake) {
        const width = map.getCanvas().clientWidth;
        setHover({
          quake,
          x: event.point.x,
          y: event.point.y,
          flip: event.point.x > width - 270,
        });
      }
    });

    map.on("mouseleave", LYR_HIT, clearHover);
    map.on("dragstart", clearHover);
    map.on("zoomstart", clearHover);

    map.on("click", (event) => {
      const features = map.queryRenderedFeatures(event.point, { layers: [LYR_HIT] });
      if (features.length === 0) {
        onSelectRef.current(null);
        return;
      }
      // Multiple dots can overlap; prefer the largest magnitude under the cursor.
      let best = features[0];
      for (const feature of features) {
        if (Number(feature.properties?.mag ?? 0) > Number(best.properties?.mag ?? 0)) best = feature;
      }
      onSelectRef.current((best.properties?.qid as string) ?? null);
    });

    const emitBounds = () => {
      const b = map.getBounds();
      onBoundsChangeRef.current({
        west: b.getWest(),
        south: b.getSouth(),
        east: b.getEast(),
        north: b.getNorth(),
      });
    };
    map.on("moveend", emitBounds);
    map.once("load", emitBounds);

    return () => {
      map.remove();
      mapRef.current = null;
      setReady(false);
    };
  }, [installLayers]);

  /* ---------------------------------------------------------------------- */
  /* Prop-driven updates                                                    */
  /* ---------------------------------------------------------------------- */

  // Basemap switch: setStyle tears down every layer, `style.load` rebuilds them.
  // The map is constructed with the initial basemap already applied, so the
  // first run must not re-set it — that would clear `ready` without a matching
  // `style.load` to restore it.
  const appliedBasemap = useRef(basemapId);
  useEffect(() => {
    const map = mapRef.current;
    if (!map || appliedBasemap.current === basemapId) return;
    appliedBasemap.current = basemapId;
    setReady(false);
    map.setStyle(basemap(basemapId).style);
  }, [basemapId]);

  // `installLayers` asserts the projection as each style loads, so this only
  // handles later toggles. Calling it before the style is loaded throws.
  useEffect(() => {
    const map = mapRef.current;
    if (!map || !ready) return;
    map.setProjection({ type: projection === "globe" ? "globe" : "mercator" });
  }, [projection, ready]);

  useEffect(() => {
    const map = mapRef.current;
    if (!map || !ready) return;
    const source = map.getSource(SRC_QUAKES) as GeoJSONSource | undefined;
    source?.setData(toCollection(quakes, now));
  }, [quakes, now, ready]);

  useEffect(() => {
    const map = mapRef.current;
    if (!map || !ready || !map.getLayer(LYR_CORE)) return;
    const color = colorExpression(colorMode);
    map.setPaintProperty(LYR_CORE, "circle-color", color);
    map.setPaintProperty(LYR_GLOW, "circle-color", color);
  }, [colorMode, ready]);

  useEffect(() => {
    const map = mapRef.current;
    if (!map || !ready || !map.getLayer(LYR_PLATES)) return;
    map.setLayoutProperty(LYR_PLATES, "visibility", showPlates ? "visible" : "none");
  }, [showPlates, ready]);

  // Selected ring: filter to the chosen event, then breathe.
  useEffect(() => {
    const map = mapRef.current;
    if (!map || !ready || !map.getLayer(LYR_SELECTED)) return;

    map.setFilter(LYR_SELECTED, ["==", ["get", "qid"], selected?.id ?? "�"]);
    if (!selected) return;

    map.setPaintProperty(LYR_SELECTED, "circle-stroke-color", quakeColor(colorMode, selected, now));

    let frame = 0;
    const start = performance.now();
    const tick = (t: number) => {
      const phase = ((t - start) % 1800) / 1800;
      const eased = 1 - (1 - phase) ** 3;
      map.setPaintProperty(LYR_SELECTED, "circle-radius", 10 + eased * 26);
      map.setPaintProperty(LYR_SELECTED, "circle-stroke-opacity", 0.9 * (1 - eased));
      frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [selected, colorMode, now, ready]);

  // Camera moves are requested explicitly so that selecting from the map does
  // not yank the view out from under the pointer.
  useEffect(() => {
    const map = mapRef.current;
    if (!map || !selected || flyToken === 0) return;
    map.flyTo({
      center: [selected.lon, selected.lat],
      zoom: Math.max(map.getZoom(), 4.5),
      duration: 1100,
      essential: true,
    });
  }, [flyToken, selected]);

  // Empty state / data cleared.
  useEffect(() => {
    const map = mapRef.current;
    if (!map || !ready || quakes.length > 0) return;
    const source = map.getSource(SRC_QUAKES) as GeoJSONSource | undefined;
    source?.setData(EMPTY_COLLECTION);
  }, [quakes.length, ready]);

  const fitAll = useCallback(() => {
    const map = mapRef.current;
    const list = quakesRef.current;
    if (!map || list.length === 0) return;
    let west = 180;
    let east = -180;
    let south = 90;
    let north = -90;
    for (const q of list) {
      west = Math.min(west, q.lon);
      east = Math.max(east, q.lon);
      south = Math.min(south, q.lat);
      north = Math.max(north, q.lat);
    }
    const bounds: LngLatBoundsLike = [
      [west, south],
      [east, north],
    ];
    map.fitBounds(bounds, { padding: 64, duration: 900, maxZoom: 8 });
  }, []);

  const resetView = useCallback(() => {
    mapRef.current?.flyTo({ center: [12, 18], zoom: 1.35, duration: 900 });
  }, []);

  return (
    <div className="map-shell">
      <div ref={containerRef} className="map-canvas" role="application" aria-label="World map of recent earthquakes" />

      <div className="map-actions">
        <button type="button" className="map-btn" onClick={fitAll} title="Zoom to the filtered events">
          Fit results
        </button>
        <button type="button" className="map-btn" onClick={resetView} title="Back to the world view">
          Reset view
        </button>
      </div>

      {hover ? <MapTooltip hover={hover} colorMode={colorMode} now={now} /> : null}
    </div>
  );
}

function MapTooltip({
  hover,
  colorMode,
  now,
}: {
  hover: HoverState;
  colorMode: ColorMode;
  now: number;
}) {
  const { quake, x, y, flip } = hover;
  const color = quakeColor(colorMode, quake, now);
  return (
    <div
      className="map-tooltip"
      style={{
        transform: `translate(${x + (flip ? -14 : 14)}px, ${y - 14}px) translateX(${flip ? "-100%" : "0"})`,
      }}
    >
      <div className="map-tooltip-head">
        <span className="map-tooltip-mag" style={{ color }}>
          M {magnitudeLabel(quake.mag)}
        </span>
        <span className="map-tooltip-time">{relativeTime(quake.time, now)}</span>
      </div>
      <div className="map-tooltip-place">{quake.place}</div>
      <div className="map-tooltip-depth">{depthLabel(quake.depth)} deep</div>
    </div>
  );
}

