import { connect } from "./cdp.mjs";

const cdp = await connect();
const tileReqs = [];
cdp.on((msg) => {
  if (msg.method === "Network.requestWillBeSent") {
    const u = msg.params.request.url;
    if (/\.(mvt|pbf)|\/\d+\/\d+\/\d+/.test(u)) tileReqs.push(u.slice(0, 100));
  }
});

await cdp.send("Emulation.setDeviceMetricsOverride", {
  width: 1600, height: 1000, deviceScaleFactor: 1, mobile: false,
});
await cdp.goto("http://localhost:9219/");
await new Promise((r) => setTimeout(r, 12000));

console.log(await cdp.evaluate(`
  const m = window.__map;
  const c = m.getCanvas();
  const gl = m.painter?.context?.gl;
  const container = m.getContainer();
  return {
    canvasClient: [c.clientWidth, c.clientHeight],
    canvasAttr: [c.width, c.height],
    containerRect: (() => { const r = container.getBoundingClientRect(); return [r.width, r.height]; })(),
    glRenderer: gl ? gl.getParameter(gl.getExtension('WEBGL_debug_renderer_info')?.UNMASKED_RENDERER_WEBGL ?? gl.RENDERER) : 'no gl',
    glContextLost: gl ? gl.isContextLost() : null,
    repaintCount: m.painter ? 'painter ok' : 'no painter',
    zoom: m.getZoom(),
    center: m.getCenter(),
    sourceLoadedQuakes: m.isSourceLoaded('quakes'),
    sourceLoadedCarto: m.isSourceLoaded('carto'),
    renderedQuakeFeatures: m.queryRenderedFeatures({layers:['quake-core']}).length,
    querySourceFeatures: m.querySourceFeatures('quakes').length,
  };
`));

console.log("\ntile requests:", tileReqs.length);
console.log(tileReqs.slice(0, 5).join("\n"));

// Is the WebGL canvas non-black? Read a pixel directly from the canvas.
console.log("\ncanvas pixel probe:", await cdp.evaluate(`
  const m = window.__map;
  m.triggerRepaint();
  await new Promise(r => setTimeout(r, 1200));
  const c = m.getCanvas();
  const gl = c.getContext('webgl2') || c.getContext('webgl');
  const px = new Uint8Array(4 * 16);
  // sample a horizontal strip across the middle of the drawing buffer
  gl.readPixels(Math.floor(c.width/2), Math.floor(c.height/2), 16, 1, gl.RGBA, gl.UNSIGNED_BYTE, px);
  return Array.from(px.slice(0, 24));
`));

cdp.close();

