import { connect } from "./cdp.mjs";

const cdp = await connect();
const workerLines = [];

// Attach to workers so their console/exceptions surface.
cdp.on(async (msg) => {
  if (msg.method === "Target.attachedToTarget") {
    const { sessionId, targetInfo } = msg.params;
    workerLines.push(`+ attached ${targetInfo.type} ${targetInfo.url.slice(0, 80)}`);
    await cdp.send("Runtime.enable", {}).catch(() => {});
  }
  if (msg.method === "Target.receivedMessageFromTarget") {
    const inner = JSON.parse(msg.params.message);
    if (inner.method === "Runtime.exceptionThrown") {
      workerLines.push(`! worker exception: ${inner.params.exceptionDetails.exception?.description}`);
    }
    if (inner.method === "Runtime.consoleAPICalled") {
      workerLines.push(`  worker log: ${inner.params.args.map((a) => a.value).join(" ")}`);
    }
  }
});

await cdp.send("Target.setAutoAttach", {
  autoAttach: true,
  waitForDebuggerOnStart: false,
  flatten: false,
});

await cdp.send("Emulation.setDeviceMetricsOverride", {
  width: 1600, height: 1000, deviceScaleFactor: 1, mobile: false,
});
await cdp.goto("http://localhost:9219/");
await new Promise((r) => setTimeout(r, 9000));

console.log("plain worker smoke test:", await cdp.evaluate(`
  try {
    const src = 'self.onmessage = e => self.postMessage(e.data * 2);';
    const url = URL.createObjectURL(new Blob([src], {type:'text/javascript'}));
    const w = new Worker(url);
    const result = await new Promise((res, rej) => {
      w.onmessage = (e) => res(e.data);
      w.onerror = (e) => rej(new Error('worker error: ' + e.message));
      w.postMessage(21);
      setTimeout(() => rej(new Error('worker timeout')), 4000);
    });
    w.terminate();
    return 'blob worker ok, got ' + result;
  } catch (err) { return 'FAILED: ' + err.message; }
`));

console.log("\nmaplibre worker state:", await cdp.evaluate(`
  const m = window.__map;
  const dispatcher = m.style?.dispatcher ?? m.style?._dispatcher;
  const src = m.getSource('quakes');
  return {
    workerCount: dispatcher?.actors?.length ?? 'unknown',
    quakeSourceLoaded: src.loaded(),
    quakeSourceHasData: !!src._data,
    quakeSourceDataFeatures: src._data?.features?.length ?? null,
    quakeSourcePendingLoads: src._pendingLoads ?? null,
  };
`));

console.log("\n--- worker/target events ---");
console.log(workerLines.join("\n") || "(none)");
console.log("\n--- page console errors ---");
console.log(cdp.consoleLines.filter((l) => /error|exception/i.test(l)).slice(0, 10).join("\n") || "(clean)");

cdp.close();

