const cdp = await connect();

// Intercept the Worker constructor before any app code runs so we can watch the
// actor handshake in both directions.
await cdp.send("Page.addScriptToEvaluateOnNewDocument", {
  source: `
    window.__wlog = [];
    const RealWorker = window.Worker;
    window.Worker = function (url, opts) {
      window.__wlog.push('construct ' + String(url).slice(0, 90) + ' opts=' + JSON.stringify(opts));
      const w = new RealWorker(url, opts);
      const realPost = w.postMessage.bind(w);
      w.postMessage = (msg, transfer) => {
        try { window.__wlog.push('-> ' + JSON.stringify(msg).slice(0, 160)); }
        catch { window.__wlog.push('-> [unserialisable]'); }
        return realPost(msg, transfer);
      };
      w.addEventListener('message', (e) => {
        try { window.__wlog.push('<- ' + JSON.stringify(e.data).slice(0, 160)); }
        catch { window.__wlog.push('<- [unserialisable]'); }
      });
      w.addEventListener('error', (e) => {
        window.__wlog.push('!! worker error: ' + e.message + ' @ ' + e.filename + ':' + e.lineno);
      });
      w.addEventListener('messageerror', (e) => {
        window.__wlog.push('!! messageerror: ' + String(e));
      });
      return w;
    };
    window.Worker.prototype = RealWorker.prototype;
  `,
});

await cdp.send("Emulation.setDeviceMetricsOverride", { width: 1600, height: 1000, deviceScaleFactor: 1, mobile: false });
await cdp.goto("http://localhost:9219/");
await new Promise((r) => setTimeout(r, 9000));

const log = await cdp.evaluate(`return window.__wlog;`);
console.log(`worker traffic (${log.length} entries):`);
console.log(log.slice(0, 40).join("\n"));

cdp.close();

