import { connect, waitFor } from "./cdp.mjs";

const SCRATCH = new URL(".", import.meta.url).pathname;
const cdp = await connect();

await cdp.send("Emulation.setDeviceMetricsOverride", {
  width: 1600, height: 1000, deviceScaleFactor: 2, mobile: false,
});

await cdp.goto("http://localhost:9219/");
await waitFor(cdp, "window.__map && window.__map.isStyleLoaded()", { label: "map style" });
await waitFor(
  cdp,
  "window.__map.queryRenderedFeatures({layers:['quake-core']}).length > 0",
  { label: "quake dots rendered", timeout: 40000 },
);
await new Promise((r) => setTimeout(r, 6000));

const report = await cdp.evaluate(`
  const map = window.__map;
  const src = map.getSource('quakes');
  const raw = src._data.geojson;
  const rendered = map.queryRenderedFeatures({ layers: ['quake-core'] });

  // Positional fidelity: round-trip each raw coordinate through the projection.
  let maxDrift = 0;
  for (const f of raw.features) {
    const [lon, lat] = f.geometry.coordinates;
    const p = map.project([lon, lat]);
    const back = map.unproject([p.x, p.y]);
    maxDrift = Math.max(maxDrift, Math.abs(back.lng - lon) + Math.abs(back.lat - lat));
  }

  // Clustering would show up as aggregated features carrying point_count.
  const clustered = rendered.filter(f => 'point_count' in (f.properties||{}) || f.properties?.cluster);
  const ids = new Set(rendered.map(f => f.properties.qid));

  // Does each rendered dot still carry its own distinct coordinates?
  const coordKeys = new Set(rendered.map(f => f.geometry.coordinates.join(',')));

  const style = map.getStyle();
  return {
    title: document.title,
    h1: document.querySelector('h1.header-title')?.textContent,
    canvas: [map.getCanvas().clientWidth, map.getCanvas().clientHeight],
    basemapSourceTypes: Object.entries(style.sources).map(([k,v]) => k+':'+v.type),
    totalStyleLayers: style.layers.length,
    appLayers: style.layers.filter(l => l.id.startsWith('quake') || l.id === 'plate-boundaries').map(l => l.id),
    clusterOption: style.sources.quakes.cluster,
    rawFeatureCount: raw.features.length,
    renderedCoreFeatures: rendered.length,
    uniqueRenderedIds: ids.size,
    uniqueRenderedCoords: coordKeys.size,
    clusteredFeatures: clustered.length,
    maxProjectionDriftDeg: Number(maxDrift.toFixed(10)),
    sampleFeature: {
      props: raw.features[0].properties,
      coords: raw.features[0].geometry.coordinates,
    },
    listRows: document.querySelectorAll('[role="option"]').length,
    listFirstRow: document.querySelector('[role="option"]')?.innerText.replace(/\\n/g,' | '),
    legendPresent: !!document.querySelector('.legend'),
    readout: [...document.querySelectorAll('*')].filter(n => /events match$/.test(n.textContent||'') && n.children.length<3).map(n=>n.textContent)[0] ?? null,
  };
`);

console.log(JSON.stringify(report, null, 2));
console.log("\n--- console (errors only) ---");
console.log(cdp.consoleLines.filter((l) => /error|exception/i.test(l)).join("\n") || "(clean)");

await cdp.screenshot(`${SCRATCH}/shot-01-overview.png`);
console.log("\nscreenshot: shot-01-overview.png");
cdp.close();

