.app {
  display: grid;
  grid-template-rows: var(--header-h) auto 1fr;
  height: 100dvh;
  overflow: hidden;
  /* A faint seismic wash so the black is never flat. */
  background:
    radial-gradient(1200px 600px at 18% -10%, rgba(56, 189, 248, 0.07), transparent 60%),
    radial-gradient(900px 500px at 92% 110%, rgba(244, 63, 94, 0.06), transparent 62%),
    var(--bg);
}

.layout {
  display: grid;
  grid-template-columns: var(--sidebar-w) 1fr;
  min-height: 0;
  position: relative;
}

/* ------------------------------------------------------------------ */
/* Header                                                              */
/* ------------------------------------------------------------------ */

.header {
  display: flex;
  align-items: center;
  gap: 20px;
  padding: 0 16px 0 18px;
  border-bottom: 1px solid var(--line);
  background: linear-gradient(180deg, rgba(14, 19, 28, 0.96), rgba(10, 14, 21, 0.92));
  backdrop-filter: blur(12px);
  z-index: 30;
}

.header-identity {
  display: flex;
  align-items: center;
  gap: 11px;
  flex-shrink: 0;
}

.seismo {
  width: 42px;
  height: 22px;
  color: var(--accent);
  opacity: 0.9;
  stroke-dasharray: 120;
  animation: trace 4.5s ease-in-out infinite;
}

@keyframes trace {
  0% {
    stroke-dashoffset: 120;
    opacity: 0.35;
  }
  35% {
    opacity: 0.95;
  }
  70% {
    stroke-dashoffset: 0;
    opacity: 0.9;
  }
  100% {
    stroke-dashoffset: -120;
    opacity: 0.35;
  }
}

.header-title {
  font-size: 15.5px;
  font-weight: 650;
  letter-spacing: -0.01em;
  white-space: nowrap;
}

.header-stats {
  display: flex;
  align-items: stretch;
  gap: 2px;
  flex: 1;
  min-width: 0;
  overflow: hidden;
  margin-left: 8px;
}

.stat {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 1px;
  padding: 0 14px;
  min-width: 0;
  border-left: 1px solid var(--line);
  text-align: left;
