import { connect, waitFor } from "./cdp.mjs";

const cdp = await connect();
const sizes = [
  [1920, 1080],
  [1600, 1000],
  [1512, 945], // MacBook Pro 14" default
  [1440, 900],
  [1280, 800],
];

for (const [w, h] of sizes) {
  await cdp.send("Emulation.setDeviceMetricsOverride", { width: w, height: h, deviceScaleFactor: 1, mobile: false });
  await cdp.goto("http://localhost:9219/");
  await waitFor(cdp, "document.querySelector('.sidebar-scroll')", { label: "sidebar" });
  await new Promise((r) => setTimeout(r, 1200));
  const m = await cdp.evaluate(`
    const s = document.querySelector('.sidebar-scroll');
    const l = document.querySelector('.sidebar-list');
    const t = document.querySelector('.timeline');
    return {
      scrollH: s.scrollHeight, clientH: s.clientHeight,
      hiddenPx: s.scrollHeight - s.clientHeight,
      listH: l?.getBoundingClientRect().height ?? null,
      timelineH: t?.getBoundingClientRect().height ?? null,
      mapH: document.querySelector('.stage-map')?.getBoundingClientRect().height ?? null,
      bodyScrollX: document.documentElement.scrollWidth > document.documentElement.clientWidth,
    };
  `);
  console.log(`${w}x${h}`.padEnd(11), JSON.stringify(m));
}
cdp.close();

