       expect(padded[2]).toEqual(["zoom"]); // must stay the direct interpolate input
       for (const zoomStop of [4, 6, 8, 10]) {
         for (const magStop of [4, 6, 8, 10, 12]) {
           expect(padded[zoomStop][magStop]).toBeCloseTo(base[zoomStop][magStop] + 7);
