1	import { useCallback, useEffect, useMemo, useRef, useState } from "react";
2	
3	import { ControlPanel } from "./components/ControlPanel";
4	import { DetailPanel } from "./components/DetailPanel";
5	import { EventList } from "./components/EventList";
6	import { Header } from "./components/Header";
7	import { Legend } from "./components/Legend";
8	import { MapView } from "./components/MapView";
9	import { Timeline } from "./components/Timeline";
10	import { useEarthquakes, useNow } from "./hooks/useEarthquakes";
11	import { useMediaQuery } from "./hooks/useMediaQuery";
12	import type { BasemapId, ProjectionId } from "./lib/basemaps";
13	import type { ColorMode } from "./lib/color";
14	import {
15	  DEFAULT_FILTERS,
16	  activeFilterCount,
17	  applyFilters,
18	  sortQuakes,
19	  summarize,
20	  type Filters,
21	  type SortKey,
22	} from "./lib/filters";
23	import type { Bounds } from "./lib/geo";
24	import { feedWindow, type WindowId } from "./lib/usgs";
25	
26	export default function App() {
27	  const [windowId, setWindowId] = useState<WindowId>("day");
28	  const [filters, setFilters] = useState<Filters>(DEFAULT_FILTERS);
29	  const [sort, setSort] = useState<SortKey>("recent");
30	  const [colorMode, setColorMode] = useState<ColorMode>("magnitude");
31	  const [basemapId, setBasemapId] = useState<BasemapId>("night");
32	  const [projection, setProjection] = useState<ProjectionId>("flat");
33	  const [showPlates, setShowPlates] = useState(true);
34	  const [selectedId, setSelectedId] = useState<string | null>(null);
35	  const [bounds, setBounds] = useState<Bounds | null>(null);
36	  const [flyToken, setFlyToken] = useState(0);
37	  const [drawerOpen, setDrawerOpen] = useState(false);
38	  const [mobilePane, setMobilePane] = useState<"map" | "list">("map");
39	
40	  const { data, status, error, refreshing, lastLoadedAt, refresh } = useEarthquakes(windowId);
41	  const now = useNow();
42	  const isCompact = useMediaQuery("(max-width: 1080px)");
43	
44	  const quakes = useMemo(() => data?.quakes ?? [], [data]);
45	
46	  // Bounds change on every pan; only re-filter when the viewport filter is on.
47	  const effectiveBounds = filters.viewportOnly ? bounds : null;
48	
49	  const filtered = useMemo(
50	    () => applyFilters(quakes, filters, effectiveBounds),
51	    [quakes, filters, effectiveBounds],
52	  );
53	  const sorted = useMemo(() => sortQuakes(filtered, sort), [filtered, sort]);
54	  const stats = useMemo(() => summarize(filtered), [filtered]);
55	
56	  const selected = useMemo(
57	    () => quakes.find((quake) => quake.id === selectedId) ?? null,
58	    [quakes, selectedId],
59	  );
60	
61	  /* -------------------------------------------------------------------- */
62	  /* Selection                                                            */
63	  /* -------------------------------------------------------------------- */
64	
65	  const selectFromMap = useCallback((id: string | null) => setSelectedId(id), []);
66	
67	  const selectAndFly = useCallback((id: string) => {
68	    setSelectedId(id);
69	    setFlyToken((token) => token + 1);
70	  }, []);
71	
72	  const closeDetail = useCallback(() => setSelectedId(null), []);
73	
74	  // Escape closes the detail panel, then the mobile drawer.
75	  useEffect(() => {
76	    const onKey = (event: KeyboardEvent) => {
77	      if (event.key !== "Escape") return;
78	      if (drawerOpen) setDrawerOpen(false);
79	      else setSelectedId(null);
80	    };
81	    window.addEventListener("keydown", onKey);
82	    return () => window.removeEventListener("keydown", onKey);
83	  }, [drawerOpen]);
84	
85	  // A selection that no longer exists after a refresh should not linger.
86	  useEffect(() => {
87	    if (selectedId && quakes.length > 0 && !quakes.some((q) => q.id === selectedId)) {
88	      setSelectedId(null);
89	    }
90	  }, [quakes, selectedId]);
91	
92	  /* -------------------------------------------------------------------- */
93	  /* Time window / brush                                                  */
94	  /* -------------------------------------------------------------------- */
95	
96	  const activeWindow = feedWindow(windowId);
97	
98	  // The strip always spans the full feed window, anchored to the newest event
99	  // so a stale feed does not leave a gap at the right edge.
100	  const timelineTo = useMemo(() => {
101	    const newest = quakes.length > 0 ? quakes[0].time : now;
102	    return Math.max(newest, data?.generated ?? 0, now - 60_000);
103	  }, [quakes, data, now]);
104	  const timelineFrom = timelineTo - activeWindow.durationMs;
105	
106	  const brush = useMemo<[number, number] | null>(
107	    () =>
108	      filters.timeFrom !== null && filters.timeTo !== null
109	        ? [filters.timeFrom, filters.timeTo]
110	        : null,
111	    [filters.timeFrom, filters.timeTo],
112	  );
113	
114	  const setBrush = useCallback((range: [number, number] | null) => {
115	    setFilters((prev) => ({
116	      ...prev,
117	      timeFrom: range?.[0] ?? null,
118	      timeTo: range?.[1] ?? null,
119	    }));
120	  }, []);
121	
122	  // Switching windows invalidates any brush drawn on the previous one.
123	  const changeWindow = useCallback((id: WindowId) => {
124	    setWindowId(id);
125	    setFilters((prev) => ({ ...prev, timeFrom: null, timeTo: null }));
126	  }, []);
127	
128	  const resetFilters = useCallback(() => setFilters(DEFAULT_FILTERS), []);
129	
130	  /* -------------------------------------------------------------------- */
131	  /* Layout                                                               */
132	  /* -------------------------------------------------------------------- */
133	
134	  const sidebarRef = useRef<HTMLDivElement>(null);
135	  useEffect(() => {
136	    if (!isCompact) setDrawerOpen(false);
137	  }, [isCompact]);
138	
139	  // On a phone, choosing an event should reveal it on the map.
140	  useEffect(() => {
141	    if (isCompact && selectedId) setMobilePane("map");
142	  }, [isCompact, selectedId]);
143	
144	  const controls = (
145	    <ControlPanel
146	      windowId={windowId}
147	      onWindowChange={changeWindow}
148	      filters={filters}
149	      onFiltersChange={setFilters}
150	      sort={sort}
151	      onSortChange={setSort}
152	      colorMode={colorMode}
153	      onColorModeChange={setColorMode}
154	      basemapId={basemapId}
155	      onBasemapChange={setBasemapId}
156	      projection={projection}
157	      onProjectionChange={setProjection}
158	      showPlates={showPlates}
159	      onShowPlatesChange={setShowPlates}
160	      onReset={resetFilters}
161	      resultCount={filtered.length}
162	      totalCount={quakes.length}
163	    />
164	  );
165	
166	  const isInitialLoad = status === "loading" && quakes.length === 0;
167	
168	  return (
169	    <div className={`app ${isCompact ? "is-compact" : ""}`} data-pane={mobilePane}>
170	      <Header
171	        stats={stats}
172	        status={status}
173	        refreshing={refreshing}
174	        lastLoadedAt={lastLoadedAt}
175	        now={now}
176	        colorMode={colorMode}
177	        windowLabel={activeWindow.longLabel}
178	        onRefresh={refresh}
179	        onSelect={(quake) => selectAndFly(quake.id)}
180	        onOpenControls={isCompact ? () => setDrawerOpen(true) : undefined}
181	        activeFilters={activeFilterCount(filters)}
182	      />
183	
184	      {status === "error" && quakes.length === 0 ? (
185	        <ErrorState message={error} onRetry={refresh} />
186	      ) : null}
187	
188	      <main className="layout">
189	        <div ref={sidebarRef} className={`sidebar ${drawerOpen ? "is-open" : ""}`}>
190	          <div className="sidebar-scroll">
191	            {isCompact ? (
192	              <div className="drawer-head">
193	                <span>Explore</span>
194	                <button
195	                  type="button"
196	                  className="icon-btn"
197	                  onClick={() => setDrawerOpen(false)}
198	                  aria-label="Close filters"
199	                >
200	                  <svg viewBox="0 0 16 16" aria-hidden="true">
201	                    <path d="m4 4 8 8M12 4l-8 8" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" />
202	                  </svg>
203	                </button>
204	              </div>
205	            ) : null}
206	            {controls}
207	          </div>
208	
209	          <div className="sidebar-list">
210	            <div className="sidebar-list-head">
211	              <h2>Events</h2>
212	              <span>{sorted.length.toLocaleString()}</span>
213	            </div>
214	            {isInitialLoad ? (
215	              <ListSkeleton />
216	            ) : (
217	              <EventList
218	                quakes={sorted}
219	                selectedId={selectedId}
220	                colorMode={colorMode}
221	                now={now}
222	                onSelect={(quake) => selectAndFly(quake.id)}
223	              />
224	            )}
225	          </div>
226	        </div>
227	
228	        {drawerOpen ? (
229	          <button
230	            type="button"
231	            className="scrim"
232	            aria-label="Close filters"
233	            onClick={() => setDrawerOpen(false)}
234	          />
235	        ) : null}
236	
237	        <div className="stage">
238	          <div className="stage-map">
239	            <MapView
240	              quakes={filtered}
241	              colorMode={colorMode}
242	              basemapId={basemapId}
243	              projection={projection}
244	              showPlates={showPlates}
245	              selected={selected}
246	              now={now}
247	              flyToken={flyToken}
248	              onSelect={selectFromMap}
249	              onBoundsChange={setBounds}
250	            />
251	
252	            <div className="stage-overlay stage-overlay-left">
253	              <Legend mode={colorMode} />
254	            </div>
255	
256	            {isInitialLoad ? (
257	              <div className="stage-loading">
258	                <span className="pulse-ring" aria-hidden="true" />
259	                <p>Reading the USGS feed…</p>
260	              </div>
261	            ) : null}
262	
263	            {selected ? (
264	              <DetailPanel
265	                quake={selected}
266	                allQuakes={quakes}
267	                colorMode={colorMode}
268	                now={now}
269	                onClose={closeDetail}
270	                onSelect={(quake) => selectAndFly(quake.id)}
271	                onLocate={() => setFlyToken((token) => token + 1)}
272	              />
273	            ) : null}
274	          </div>
275	
276	          <Timeline
277	            quakes={quakes}
278	            from={timelineFrom}
279	            to={timelineTo}
280	            selection={brush}
281	            onSelectionChange={setBrush}
282	            now={now}
283	            windowLabel={activeWindow.longLabel}
284	          />
285	        </div>
286	      </main>
287	
288	      {isCompact ? (
289	        <nav className="tabbar" aria-label="View switcher">
290	          <button
291	            type="button"
292	            className={mobilePane === "map" ? "is-active" : ""}
293	            aria-pressed={mobilePane === "map"}
294	            onClick={() => setMobilePane("map")}
295	          >
296	            Map
297	          </button>
298	          <button
299	            type="button"
300	            className={mobilePane === "list" ? "is-active" : ""}
301	            aria-pressed={mobilePane === "list"}
302	            onClick={() => setMobilePane("list")}
303	          >
304	            List <span className="tabbar-count">{sorted.length.toLocaleString()}</span>
305	          </button>
306	        </nav>
307	      ) : null}
308	    </div>
309	  );
310	}
311	
312	function ErrorState({ message, onRetry }: { message: string | null; onRetry: () => void }) {
313	  return (
314	    <div className="banner banner-error" role="alert">
315	      <strong>Could not load the USGS feed.</strong>
316	      <span>{message ?? "Check your connection and try again."}</span>
317	      <button type="button" className="btn" onClick={onRetry}>
318	        Retry
319	      </button>
320	    </div>
321	  );
322	}
323	
324	function ListSkeleton() {
