    bottom: 8px;
    width: auto;
    max-height: 74%;
  }

  @keyframes detail-in {
    from {
      opacity: 0;
      transform: translateY(20px);
    }
  }

  .legend {
    width: 208px;
    padding: 9px 11px 10px;
  }

  .legend-blurb,
  .legend-size {
    display: none;
  }

  .map-actions {
    bottom: 10px;
  }
}

/* ------------------------------------------------------------------ */
/* Phone                                                               */
/* ------------------------------------------------------------------ */

@media (max-width: 640px) {
  :root {
    --timeline-h: 86px;
  }

  .header {
    padding: 0 8px 0 10px;
  }

  .seismo {
    width: 30px;
  }

  .live {
    padding: 5px 9px;
  }

  .mode-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .facts {
    grid-template-columns: 1fr 1fr;
  }

  .detail-mag {
    width: 62px;
    height: 62px;
  }

  .detail-mag-value {
    font-size: 23px;
  }

  .detail-place {
    font-size: 15px;
  }

  .timeline {
    padding: 8px 12px 6px;
  }

  .timeline-selection {
    display: none;
  }

  .map-tooltip {
    display: none;
  }
}

/* Short viewports: give the map room by shrinking the list share. */
@media (max-height: 720px) and (min-width: 1081px) {
  :root {
    --timeline-h: 96px;
  }

  .sidebar-list {
    flex-basis: 40%;
  }

