  projection: ProjectionId;
  onProjectionChange: (projection: ProjectionId) => void;
  showPlates: boolean;
  onShowPlatesChange: (value: boolean) => void;
  onReset: () => void;
  /** Number of events surviving the current filters. */
  resultCount: number;
  totalCount: number;
}

