  padding-top: 2px;
}

.control-readout strong {
  color: var(--text);
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
}

/* ------------------------------------------------------------------ */
/* Segmented control                                                   */
/* ------------------------------------------------------------------ */

.segmented {
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: 1fr;
  gap: 2px;
  padding: 2px;
  border-radius: var(--radius);
  border: 1px solid var(--line);
  background: var(--surface-1);
}

.segment {
  height: 28px;
  border-radius: 7px;
  font-size: 12px;
  font-weight: 550;
  color: var(--text-2);
  letter-spacing: 0.01em;
  transition: background 0.15s ease, color 0.15s ease;
}

.segment:hover {
  color: var(--text);
  background: rgba(148, 163, 184, 0.07);
}

.segment.is-active {
  background: var(--surface-3);
  color: var(--text);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.06);
}

/* ------------------------------------------------------------------ */
/* Colour-mode cards                                                   */
/* ------------------------------------------------------------------ */

.mode-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 6px;
}

.mode-card {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 7px 8px 8px;
  border-radius: var(--radius);
  border: 1px solid var(--line);
  background: var(--surface-1);
  transition: border-color 0.15s ease, background 0.15s ease;
}

.mode-card:hover {
  background: var(--surface-2);
}

.mode-card.is-active {
  border-color: rgba(125, 211, 252, 0.5);
  background: var(--surface-2);
}

.mode-swatch {
  height: 7px;
  border-radius: 99px;
}

.mode-name {
  font-size: 11px;
  font-weight: 550;
  color: var(--text-2);
  text-align: left;
}

.mode-card.is-active .mode-name {
  color: var(--text);
}

/* ------------------------------------------------------------------ */
/* Search                                                              */
/* ------------------------------------------------------------------ */

.search-field {
  position: relative;
  display: flex;
  align-items: center;
}

.search-icon {
  position: absolute;
  left: 10px;
  width: 14px;
  height: 14px;
  color: var(--text-3);
  pointer-events: none;
}

.search-input {
  width: 100%;
  height: 34px;
  padding: 0 30px 0 30px;
  border-radius: var(--radius);
  border: 1px solid var(--line);
  background: var(--surface-1);
  color: var(--text);
  font-size: 12.5px;
  transition: border-color 0.15s ease, background 0.15s ease;
}

.search-input::placeholder {
  color: var(--text-3);
}

.search-input:focus {
  outline: none;
  border-color: rgba(125, 211, 252, 0.5);
  background: var(--surface-2);
}

.search-input::-webkit-search-cancel-button {
  display: none;
}

.search-clear {
  position: absolute;
  right: 8px;
  width: 18px;
  height: 18px;
  border-radius: 4px;
  color: var(--text-3);
  font-size: 16px;
  line-height: 1;
  display: grid;
  place-items: center;
}

.search-clear:hover {
  color: var(--text);
  background: var(--surface-3);
}

/* ------------------------------------------------------------------ */
/* Range slider                                                        */
/* ------------------------------------------------------------------ */

.range {
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.range-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
}

.range-value {
  font-family: var(--font-mono);
  font-size: 11.5px;
  color: var(--text);
  font-variant-numeric: tabular-nums;
}

.range-track-wrap {
  position: relative;
  height: 22px;
  display: flex;
  align-items: center;
}

.range-track {
  position: absolute;
  inset-inline: 0;
  height: 5px;
  border-radius: 99px;
  background: var(--surface-3);
  background-size: 100% 100%;
  opacity: 0.42;
}

.range-fill {
  position: absolute;
  height: 5px;
  border-radius: 99px;
  background: rgba(125, 211, 252, 0.85);
  box-shadow: 0 0 10px rgba(125, 211, 252, 0.35);
}

.range-input {
  position: absolute;
  inset-inline: 0;
  width: 100%;
  height: 22px;
  margin: 0;
  background: none;
  appearance: none;
  pointer-events: none;
}

.range-input::-webkit-slider-thumb {
  appearance: none;
  pointer-events: auto;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: #eaf6ff;
  border: 2px solid #0c1420;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.6);
  cursor: grab;
  transition: transform 0.12s ease;
}

.range-input::-webkit-slider-thumb:active {
  cursor: grabbing;
  transform: scale(1.16);
}

.range-input::-moz-range-thumb {
  pointer-events: auto;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: #eaf6ff;
  border: 2px solid #0c1420;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.6);
  cursor: grab;
}

.range-input:focus-visible::-webkit-slider-thumb {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

/* The upper thumb sits on top so the two never trap each other at the ends. */
.range-input-high {
  z-index: 2;
}

/* ------------------------------------------------------------------ */
/* Chips                                                               */
/* ------------------------------------------------------------------ */

.chips {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
}

.chip {
  height: 25px;
  padding: 0 10px;
  border-radius: 99px;
  border: 1px solid var(--line);
  background: var(--surface-1);
  color: var(--text-2);
  font-size: 11.5px;
  font-weight: 500;
  transition: background 0.15s ease, color 0.15s ease, border-color 0.15s ease;
}

.chip:hover {
  color: var(--text);
  background: var(--surface-2);
}

.chip.is-active {
  background: var(--accent-dim);
  border-color: rgba(125, 211, 252, 0.45);
  color: #cdeeff;
}

/* ------------------------------------------------------------------ */
/* Select                                                              */
/* ------------------------------------------------------------------ */

.select-wrap {
  position: relative;
  display: flex;
}

.select {
  width: 100%;
  height: 32px;
  padding: 0 30px 0 11px;
  border-radius: var(--radius);
  border: 1px solid var(--line);
  background: var(--surface-1);
  color: var(--text);
  font-size: 12.5px;
  appearance: none;
  cursor: pointer;
}

.select:hover {
  background: var(--surface-2);
}

.select-chevron {
  position: absolute;
  right: 10px;
  top: 50%;
  transform: translateY(-50%);
  width: 14px;
  height: 14px;
  color: var(--text-3);
  pointer-events: none;
}

/* ------------------------------------------------------------------ */
/* Switch                                                              */
/* ------------------------------------------------------------------ */

.switch {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  cursor: pointer;
  padding: 2px 0;
}

.switch input {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
}

.switch-track {
  position: relative;
  flex-shrink: 0;
  width: 32px;
  height: 18px;
  margin-top: 1px;
  border-radius: 99px;
  background: var(--surface-3);
  border: 1px solid var(--line);
  transition: background 0.18s ease, border-color 0.18s ease;
}

.switch-thumb {
  position: absolute;
  top: 2px;
  left: 2px;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--text-3);
  transition: transform 0.18s cubic-bezier(0.4, 0, 0.2, 1), background 0.18s ease;
}

.switch input:checked + .switch-track {
  background: var(--accent-dim);
  border-color: rgba(125, 211, 252, 0.5);
}

.switch input:checked + .switch-track .switch-thumb {
  transform: translateX(14px);
  background: var(--accent);
}

.switch input:focus-visible + .switch-track {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.switch-label {
  display: flex;
  flex-direction: column;
  gap: 1px;
  font-size: 12px;
  color: var(--text-2);
}

.switch-hint {
  font-size: 10.5px;
  color: var(--text-3);
}

