/* ------------------------------------------------------------------ */
/* Tablet: narrower rail, tighter header                               */
/* ------------------------------------------------------------------ */

@media (max-width: 1360px) {
  :root {
    --sidebar-w: 336px;
  }

  .header-stats .stat:nth-child(4) {
    display: none;
  }
}

@media (max-width: 1200px) {
  .header-stats .stat:nth-child(3) {
    display: none;
  }

  .detail {
    width: min(380px, 52%);
  }
}

/* ------------------------------------------------------------------ */
/* Compact: drawer + tab bar                                           */
/* ------------------------------------------------------------------ */

@media (max-width: 1080px) {
  :root {
    --header-h: 56px;
    --timeline-h: 100px;
  }

  .app {
    grid-template-rows: var(--header-h) auto 1fr;
  }

  .header {
    padding: 0 10px 0 12px;
    gap: 10px;
  }

  .header-stats {
    display: none;
  }

  .header-title {
    font-size: 14.5px;
  }

  .live-time {
    display: none;
  }

  .layout {
    grid-template-columns: 1fr;
  }

  .stage {
    grid-row: 1;
  }

  /* The rail becomes a full-height overlay driven by two independent
     switches: the Filters drawer and the List tab. */
  .is-compact .sidebar {
    position: fixed;
    top: var(--header-h);
    left: 0;
    right: 0;
    bottom: 54px;
    display: none;
    border-right: none;
    background: var(--surface-0);
    animation: sheet-in 0.22s cubic-bezier(0.16, 1, 0.3, 1);
  }

  @keyframes sheet-in {
    from {
      opacity: 0;
      transform: translateY(10px);
    }
  }

  .is-compact .sidebar.is-open,
  .is-compact[data-pane="list"] .sidebar {
    display: flex;
  }

  .is-compact .sidebar-scroll {
    display: none;
    flex: 1;
  }

  .is-compact .sidebar.is-open .sidebar-scroll {
    display: block;
  }

  .is-compact .sidebar.is-open .sidebar-list {
    display: none;
  }

  .is-compact .sidebar-list {
    flex: 1;
    border-top: none;
  }

  .drawer-head {
    display: flex;
  }

  .scrim {
    display: block;
    position: fixed;
    inset: 0;
    z-index: 15;
    background: rgba(3, 5, 8, 0.5);
    cursor: default;
  }

  .header-filters {
    height: 30px;
    padding: 0 10px;
    gap: 6px;
  }

  .tabbar {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 3px;
    padding: 5px 8px calc(5px + env(safe-area-inset-bottom));
    border-top: 1px solid var(--line);
    background: rgba(10, 14, 21, 0.96);
    backdrop-filter: blur(14px);
    position: fixed;
    left: 0;
    right: 0;
    bottom: 0;
    z-index: 45;
    height: 54px;
  }

  .tabbar button {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    border-radius: var(--radius);
    font-size: 12.5px;
    font-weight: 550;
    color: var(--text-3);
    transition: background 0.15s ease, color 0.15s ease;
  }

  .tabbar button.is-active {
    background: var(--surface-2);
    color: var(--text);
  }

  .tabbar-count {
    font-family: var(--font-mono);
    font-size: 10.5px;
    color: var(--text-3);
    font-variant-numeric: tabular-nums;
  }

  /* Leave room for the tab bar under the map and timeline. */
  .is-compact .layout {
    padding-bottom: 54px;
  }

  .detail {
    top: auto;
    left: 8px;
    right: 8px;
    bottom: 8px;
    width: auto;
    max-height: 74%;
  }

  @keyframes detail-in {
    from {
      opacity: 0;
      transform: translateY(20px);
    }
  }

  .legend {
    width: 208px;
    padding: 9px 11px 10px;
  }

  .legend-blurb,
  .legend-size {
    display: none;
  }

  .map-actions {
    bottom: 10px;
  }
}

/* ------------------------------------------------------------------ */
/* Phone                                                               */
/* ------------------------------------------------------------------ */

@media (max-width: 640px) {
  :root {
    --timeline-h: 86px;
  }

  .header {
    padding: 0 8px 0 10px;
  }

  .seismo {
    width: 30px;
  }

  .live {
    padding: 5px 9px;
  }

  .mode-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .facts {
    grid-template-columns: 1fr 1fr;
  }

  .detail-mag {
    width: 62px;
    height: 62px;
  }

  .detail-mag-value {
    font-size: 23px;
  }

  .detail-place {
    font-size: 15px;
  }

  .timeline {
    padding: 8px 12px 6px;
  }

  .timeline-selection {
    display: none;
  }

  .map-tooltip {
    display: none;
  }
}

/* Short viewports: give the map room by shrinking the list share. */
@media (max-height: 720px) and (min-width: 1081px) {
  :root {
    --timeline-h: 96px;
  }

  .sidebar-list {
    flex-basis: 40%;
  }
}

