.app {
  display: grid;
  grid-template-rows: var(--header-h) auto 1fr;
  height: 100dvh;
  overflow: hidden;
  /* A faint seismic wash so the black is never flat. */
  background:
    radial-gradient(1200px 600px at 18% -10%, rgba(56, 189, 248, 0.07), transparent 60%),
    radial-gradient(900px 500px at 92% 110%, rgba(244, 63, 94, 0.06), transparent 62%),
    var(--bg);
}

.layout {
  display: grid;
  grid-template-columns: var(--sidebar-w) 1fr;
  min-height: 0;
  position: relative;
}

/* ------------------------------------------------------------------ */
/* Header                                                              */
/* ------------------------------------------------------------------ */

.header {
  display: flex;
  align-items: center;
  gap: 20px;
  padding: 0 16px 0 18px;
  border-bottom: 1px solid var(--line);
  background: linear-gradient(180deg, rgba(14, 19, 28, 0.96), rgba(10, 14, 21, 0.92));
  backdrop-filter: blur(12px);
  z-index: 30;
}

.header-identity {
  display: flex;
  align-items: center;
  gap: 11px;
  flex-shrink: 0;
}

.seismo {
  width: 42px;
  height: 22px;
  color: var(--accent);
  opacity: 0.9;
  stroke-dasharray: 120;
  animation: trace 4.5s ease-in-out infinite;
}

@keyframes trace {
  0% {
    stroke-dashoffset: 120;
    opacity: 0.35;
  }
  35% {
    opacity: 0.95;
  }
  70% {
    stroke-dashoffset: 0;
    opacity: 0.9;
  }
  100% {
    stroke-dashoffset: -120;
    opacity: 0.35;
  }
}

.header-title {
  font-size: 15.5px;
  font-weight: 650;
  letter-spacing: -0.01em;
  white-space: nowrap;
}

.header-stats {
  display: flex;
  align-items: stretch;
  gap: 2px;
  flex: 1;
  min-width: 0;
  overflow: hidden;
  margin-left: 8px;
}

.stat {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 1px;
  padding: 0 14px;
  min-width: 0;
  border-left: 1px solid var(--line);
  text-align: left;
}

.header-stats .stat:first-child {
  border-left: none;
}

.stat-clickable {
  border-radius: var(--radius-sm);
  transition: background 0.15s ease;
}

.stat-clickable:hover {
  background: rgba(148, 163, 184, 0.07);
}

.stat-label {
  font-size: 9.5px;
  font-weight: 600;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  color: var(--text-3);
  white-space: nowrap;
}

.stat-value {
  font-family: var(--font-mono);
  font-size: 14px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.01em;
  white-space: nowrap;
}

.stat-detail {
  font-size: 10.5px;
  color: var(--text-3);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 150px;
}

.header-side {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-shrink: 0;
}

.live {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 5px 11px 5px 9px;
  border-radius: 99px;
  border: 1px solid var(--line);
  background: var(--surface-1);
}

.live-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #4ade80;
  box-shadow: 0 0 0 0 rgba(74, 222, 128, 0.6);
  animation: beacon 2.6s ease-out infinite;
}

.live-dot.is-busy {
  background: var(--accent);
  animation-duration: 1s;
}

.live.is-error .live-dot {
  background: var(--danger);
}

@keyframes beacon {
  0% {
    box-shadow: 0 0 0 0 rgba(74, 222, 128, 0.55);
  }
  70% {
    box-shadow: 0 0 0 7px rgba(74, 222, 128, 0);
  }
  100% {
    box-shadow: 0 0 0 0 rgba(74, 222, 128, 0);
  }
}

.live-text {
  display: flex;
  flex-direction: column;
  line-height: 1.2;
}

.live-label {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.02em;
}

.live-time {
  font-size: 10px;
  color: var(--text-3);
  white-space: nowrap;
}

.is-spinning {
  animation: spin 1s linear infinite;
  transform-origin: center;
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

/* ------------------------------------------------------------------ */
/* Sidebar                                                             */
/* ------------------------------------------------------------------ */

.sidebar {
  display: flex;
  flex-direction: column;
  min-height: 0;
  border-right: 1px solid var(--line);
  background: linear-gradient(180deg, var(--surface-0), rgba(5, 7, 11, 0.9));
  z-index: 20;
}

.sidebar-scroll {
  flex: 0 1 auto;
  overflow-y: auto;
  overscroll-behavior: contain;
  padding: 16px 16px 6px;
}

.sidebar-list {
  flex: 1 1 46%;
  display: flex;
  flex-direction: column;
  min-height: 210px;
  border-top: 1px solid var(--line);
  background: rgba(6, 9, 14, 0.55);
}

.sidebar-list-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  padding: 11px 16px 9px;
  border-bottom: 1px solid var(--line);
}

.sidebar-list-head h2 {
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.11em;
  text-transform: uppercase;
  color: var(--text-3);
}

.sidebar-list-head span {
  font-family: var(--font-mono);
  font-size: 11.5px;
  color: var(--text-2);
  font-variant-numeric: tabular-nums;
}

.drawer-head {
  display: none;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 12px;
  margin-bottom: 4px;
  border-bottom: 1px solid var(--line);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.11em;
  text-transform: uppercase;
  color: var(--text-3);
}

.scrim {
  display: none;
}

/* ------------------------------------------------------------------ */
/* Stage                                                               */
/* ------------------------------------------------------------------ */

.stage {
  display: grid;
  grid-template-rows: 1fr var(--timeline-h);
  min-height: 0;
  min-width: 0;
}

.stage-map {
  position: relative;
  min-height: 0;
  overflow: hidden;
}

.stage-overlay {
  position: absolute;
  z-index: 10;
  pointer-events: none;
}

.stage-overlay > * {
  pointer-events: auto;
}

.stage-overlay-left {
  top: 12px;
  left: 12px;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 8px;
}

.stage-loading {
  position: absolute;
  inset: 0;
  display: grid;
  place-content: center;
  justify-items: center;
  gap: 18px;
  background: rgba(5, 7, 11, 0.72);
  backdrop-filter: blur(3px);
  z-index: 15;
  color: var(--text-2);
  font-size: 12.5px;
  letter-spacing: 0.02em;
}

.pulse-ring {
  width: 46px;
  height: 46px;
  border-radius: 50%;
  border: 1.5px solid var(--accent);
  animation: pulse-out 1.6s ease-out infinite;
}

@keyframes pulse-out {
  0% {
    transform: scale(0.4);
    opacity: 1;
  }
  100% {
    transform: scale(1.6);
    opacity: 0;
  }
}

/* ------------------------------------------------------------------ */
/* Skeleton                                                            */
/* ------------------------------------------------------------------ */

.skeleton-list {
  padding: 8px 14px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.skeleton-row {
  display: flex;
  align-items: center;
  gap: 12px;
  animation: fade-pulse 1.5s ease-in-out infinite;
}

.skeleton-badge {
  width: 38px;
  height: 34px;
  border-radius: var(--radius-sm);
  background: var(--surface-2);
  flex-shrink: 0;
}

.skeleton-lines {
  display: flex;
  flex-direction: column;
  gap: 7px;
  flex: 1;
}

.skeleton-line {
  height: 9px;
  border-radius: 99px;
  background: var(--surface-2);
}

.skeleton-line-short {
  width: 45%;
  background: var(--surface-1);
}

@keyframes fade-pulse {
  0%,
  100% {
    opacity: 0.45;
  }
  50% {
    opacity: 0.85;
  }
}

/* ------------------------------------------------------------------ */
/* Mobile tab bar                                                      */
/* ------------------------------------------------------------------ */

.tabbar {
  display: none;
}

