import { useEffect, useRef } from "react";

import { COLOR_MODES, RAMPS, rampGradient, type ColorMode } from "../lib/color";
import {
  DEPTH_RANGE,
  MAG_RANGE,
  SORT_OPTIONS,
  activeFilterCount,
  type Filters,
  type SortKey,
} from "../lib/filters";
import { FEED_WINDOWS, type WindowId } from "../lib/usgs";
import { RangeSlider } from "./RangeSlider";

export interface ControlPanelProps {
  windowId: WindowId;
  onWindowChange: (id: WindowId) => void;
  filters: Filters;
  onFiltersChange: (next: Filters) => void;
  sort: SortKey;
  onSortChange: (sort: SortKey) => void;
  colorMode: ColorMode;
  onColorModeChange: (mode: ColorMode) => void;
  onReset: () => void;
  /** Number of events surviving the current filters. */
  resultCount: number;
  totalCount: number;
}

export function ControlPanel(props: ControlPanelProps) {
  const {
    windowId,
    onWindowChange,
    filters,
    onFiltersChange,
    sort,
    onSortChange,
    colorMode,
    onColorModeChange,
    onReset,
    resultCount,
    totalCount,
  } = props;

  const searchRef = useRef<HTMLInputElement>(null);
  const activeCount = activeFilterCount(filters);

  // "/" focuses search, the way every list-and-map tool works.
