              ×
            </button>
          ) : null}
        </div>

        <RangeSlider
          label="Magnitude"
          min={MAG_RANGE[0]}
          max={MAG_RANGE[1]}
          step={0.1}
          value={[filters.minMag, filters.maxMag]}
          onChange={([minMag, maxMag]) => patch({ minMag, maxMag })}
          format={(v) => `M${v.toFixed(1)}`}
