// Minimal Chrome DevTools Protocol client (Node 22 global WebSocket, no deps).
import { writeFileSync } from "node:fs";

const PORT = process.env.CDP_PORT || 9222;

export async function connect() {
  let targets;
  for (let attempt = 0; attempt < 60; attempt += 1) {
    try {
      targets = await (await fetch(`http://127.0.0.1:${PORT}/json/list`)).json();
      if (targets.some((t) => t.type === "page")) break;
    } catch {
      /* chrome still booting */
    }
    await new Promise((r) => setTimeout(r, 250));
  }
  const page = targets?.find((t) => t.type === "page");
  if (!page) throw new Error("no page target on the debugging port");

  const ws = new WebSocket(page.webSocketDebuggerUrl);
  await new Promise((resolve, reject) => {
    ws.onopen = resolve;
    ws.onerror = (e) => reject(new Error(`ws: ${e.message ?? "failed"}`));
  });

  let nextId = 0;
  const pending = new Map();
  const listeners = [];
  const consoleLines = [];

  ws.onmessage = (event) => {
    const msg = JSON.parse(event.data);
    if (msg.id !== undefined) {
      const slot = pending.get(msg.id);
      pending.delete(msg.id);
      if (msg.error) slot.reject(new Error(`${msg.error.message} (${JSON.stringify(msg.error.data ?? "")})`));
      else slot.resolve(msg.result);
      return;
    }
    if (msg.method === "Runtime.consoleAPICalled") {
      consoleLines.push(
        `[${msg.params.type}] ${msg.params.args.map((a) => a.value ?? a.description ?? a.type).join(" ")}`,
      );
    }
    if (msg.method === "Log.entryAdded") {
      const e = msg.params.entry;
      consoleLines.push(`[log:${e.level}] ${e.text}${e.url ? ` (${e.url})` : ""}`);
    }
    if (msg.method === "Runtime.exceptionThrown") {
      const d = msg.params.exceptionDetails;
      consoleLines.push(`[exception] ${d.exception?.description ?? d.text}`);
    }
    for (const fn of listeners) fn(msg);
  };

  const send = (method, params = {}, sessionId) =>
    new Promise((resolve, reject) => {
      const id = ++nextId;
      pending.set(id, { resolve, reject });
      ws.send(JSON.stringify(sessionId ? { id, method, params, sessionId } : { id, method, params }));
    });

  const api = {
    send,
    consoleLines,
    on: (fn) => listeners.push(fn),
    close: () => ws.close(),

    async evaluate(expression) {
      const res = await send("Runtime.evaluate", {
        expression: `(async () => { ${expression} })()`,
        awaitPromise: true,
        returnByValue: true,
      });
      if (res.exceptionDetails) {
        throw new Error(
          res.exceptionDetails.exception?.description ?? res.exceptionDetails.text,
        );
      }
      return res.result.value;
    },

    async screenshot(path, { width, height } = {}) {
      if (width && height) {
        await send("Emulation.setDeviceMetricsOverride", {
          width,
          height,
          deviceScaleFactor: 2,
          mobile: false,
        });
        await new Promise((r) => setTimeout(r, 900));
      }
      const { data } = await send("Page.captureScreenshot", { format: "png" });
      writeFileSync(path, Buffer.from(data, "base64"));
      return path;
    },

    async click(x, y) {
      const base = { x, y, button: "left", clickCount: 1 };
      await send("Input.dispatchMouseEvent", { type: "mouseMoved", ...base });
      await new Promise((r) => setTimeout(r, 80));
      await send("Input.dispatchMouseEvent", { type: "mousePressed", ...base });
      await send("Input.dispatchMouseEvent", { type: "mouseReleased", ...base });
      await new Promise((r) => setTimeout(r, 350));
    },

    async move(x, y) {
      await send("Input.dispatchMouseEvent", { type: "mouseMoved", x, y, button: "none" });
      await new Promise((r) => setTimeout(r, 350));
    },

    async goto(url) {
      await send("Page.navigate", { url });
      await new Promise((r) => setTimeout(r, 400));
    },
  };

  await send("Page.enable");
  await send("Runtime.enable");
  await send("Log.enable");
  await send("Network.enable");
  return api;
}

/** Poll `expression` (returns boolean) until true or timeout. */
export async function waitFor(cdp, expression, { timeout = 30000, label = expression } = {}) {
  const deadline = Date.now() + timeout;
  while (Date.now() < deadline) {
    try {
      if (await cdp.evaluate(`return !!(${expression});`)) return true;
    } catch {
      /* not ready */
    }
    await new Promise((r) => setTimeout(r, 300));
  }
  throw new Error(`timed out waiting for: ${label}`);
}

