      onClick={() => onSelect(quake)}
    >
      <span className="row-mag" style={{ color, borderColor: color }}>
        {magnitudeLabel(quake.mag)}
      </span>
      <span className="row-body">
        <span className="row-place">
          {prefix ? <span className="row-prefix">{prefix} of </span> : null}
          {region}
        </span>
