// Minimal PNG reader: 8-bit, non-interlaced, colour type 2 (RGB) or 6 (RGBA).
// Enough for Chrome's Page.captureScreenshot output, with no dependencies.
import { inflateSync } from "node:zlib";

export function decodePNG(buf) {
  if (buf.readUInt32BE(0) !== 0x89504e47) throw new Error("not a PNG");
  let pos = 8;
  let width = 0;
  let height = 0;
  let channels = 0;
  const idat = [];

  while (pos < buf.length) {
    const len = buf.readUInt32BE(pos);
    const type = buf.toString("ascii", pos + 4, pos + 8);
    const data = buf.subarray(pos + 8, pos + 8 + len);
    if (type === "IHDR") {
      width = data.readUInt32BE(0);
      height = data.readUInt32BE(4);
      const depth = data[8];
      const colorType = data[9];
      if (depth !== 8) throw new Error(`bit depth ${depth} unsupported`);
      if (data[12] !== 0) throw new Error("interlaced PNG unsupported");
      channels = colorType === 6 ? 4 : colorType === 2 ? 3 : 0;
      if (!channels) throw new Error(`colour type ${colorType} unsupported`);
    } else if (type === "IDAT") {
      idat.push(data);
    } else if (type === "IEND") {
      break;
    }
    pos += len + 12;
  }

  const raw = inflateSync(Buffer.concat(idat));
  const stride = width * channels;
  const out = Buffer.alloc(height * stride);

  for (let y = 0; y < height; y += 1) {
    const filter = raw[y * (stride + 1)];
    const line = raw.subarray(y * (stride + 1) + 1, y * (stride + 1) + 1 + stride);
    const cur = out.subarray(y * stride, (y + 1) * stride);
    const prev = y > 0 ? out.subarray((y - 1) * stride, y * stride) : null;
    for (let x = 0; x < stride; x += 1) {
      const a = x >= channels ? cur[x - channels] : 0;
      const b = prev ? prev[x] : 0;
      const c = prev && x >= channels ? prev[x - channels] : 0;
      let v = line[x];
      if (filter === 1) v += a;
      else if (filter === 2) v += b;
      else if (filter === 3) v += (a + b) >> 1;
      else if (filter === 4) {
        const p = a + b - c;
        const pa = Math.abs(p - a);
        const pb = Math.abs(p - b);
        const pc = Math.abs(p - c);
        v += pa <= pb && pa <= pc ? a : pb <= pc ? b : c;
      }
      cur[x] = v & 0xff;
    }
  }

  return { width, height, channels, data: out };
}

/** Average RGB over a square of `radius` px around (x, y) in CSS pixels. */
export function sampleRegion(img, x, y, radius, scale = 1) {
  const cx = Math.round(x * scale);
  const cy = Math.round(y * scale);
  const r = Math.round(radius * scale);
  let rs = 0;
  let gs = 0;
  let bs = 0;
  let n = 0;
  for (let dy = -r; dy <= r; dy += 1) {
    for (let dx = -r; dx <= r; dx += 1) {
      const px = cx + dx;
      const py = cy + dy;
      if (px < 0 || py < 0 || px >= img.width || py >= img.height) continue;
      const i = (py * img.width + px) * img.channels;
      rs += img.data[i];
      gs += img.data[i + 1];
      bs += img.data[i + 2];
      n += 1;
    }
  }
  return [Math.round(rs / n), Math.round(gs / n), Math.round(bs / n)];
}

/** Brightest pixel in the square — the dot core, not the basemap around it. */
export function sampleBrightest(img, x, y, radius, scale = 1) {
  const cx = Math.round(x * scale);
  const cy = Math.round(y * scale);
  const r = Math.round(radius * scale);
  let best = [0, 0, 0];
  let bestSum = -1;
  for (let dy = -r; dy <= r; dy += 1) {
    for (let dx = -r; dx <= r; dx += 1) {
      const px = cx + dx;
      const py = cy + dy;
      if (px < 0 || py < 0 || px >= img.width || py >= img.height) continue;
      const i = (py * img.width + px) * img.channels;
      const sum = img.data[i] + img.data[i + 1] + img.data[i + 2];
      if (sum > bestSum) {
        bestSum = sum;
        best = [img.data[i], img.data[i + 1], img.data[i + 2]];
      }
    }
  }
  return best;
}

