// Does the legend actually describe the dots? Compares the on-screen pixel
// colour of individual earthquake dots against the legend bar sampled at the
// same value, using only what a user can see (tick labels and their positions).
import { readFileSync } from "node:fs";
import { connect, waitFor } from "./cdp.mjs";
import { decodePNG, sampleBrightest, sampleRegion, dist } from "./png.mjs";

const SCALE = 2;
const cdp = await connect();
await cdp.send("Emulation.setDeviceMetricsOverride", {
  width: 1512, height: 845, deviceScaleFactor: SCALE, mobile: false,
});
await cdp.goto("http://localhost:9219/");
await waitFor(cdp, "window.__map && window.__map.isStyleLoaded()", { label: "style" });
await waitFor(cdp, "window.__map.queryRenderedFeatures({layers:['quake-core']}).length > 0", {
  label: "dots", timeout: 40000,
});

const MODES = [
  { label: "Magnitude", prop: "mag" },
  { label: "Depth", prop: "depth" },
  { label: "Recency", prop: "age" },
];

const results = [];

for (const mode of MODES) {
  // Click the colour-mode card the way a user would.
  const clicked = await cdp.evaluate(`
    const card = [...document.querySelectorAll('.mode-card, .mode-grid button')]
      .find(b => b.textContent.trim().startsWith(${JSON.stringify(mode.label)}));
    if (!card) return null;
    const r = card.getBoundingClientRect();
    return { x: r.left + r.width / 2, y: r.top + r.height / 2 };
  `);
  if (!clicked) throw new Error(`no colour-mode card for ${mode.label}`);
  await cdp.click(clicked.x, clicked.y);
  await new Promise((r) => setTimeout(r, 1400));

  const probe = await cdp.evaluate(`
    const map = window.__map;
    const canvas = map.getCanvas().getBoundingClientRect();
    const legend = document.querySelector('.legend');
    const bar = legend.querySelector('.legend-bar').getBoundingClientRect();
    const ticks = [...legend.querySelectorAll('.legend-tick')].map(t => {
      const r = t.getBoundingClientRect();
      return { text: t.textContent.trim(), x: r.left + r.width / 2 };
    });

    // Rendered dots, in screen space, keeping only well-isolated ones so the
    // sampled pixels belong to a single earthquake.
    const feats = map.queryRenderedFeatures({ layers: ['quake-core'] });
    const pts = feats.map(f => {
      const p = map.project(f.geometry.coordinates);
      return {
        qid: f.properties.qid, mag: f.properties.mag,
        depth: f.properties.depth, age: f.properties.age,
        x: canvas.left + p.x, y: canvas.top + p.y,
      };
    });
    const isolated = pts.filter((p, i) =>
      pts.every((q, j) => i === j || Math.hypot(p.x - q.x, p.y - q.y) > 26));

    return {
      legendTitle: legend.querySelector('.legend-title').textContent.trim(),
      legendUnit: legend.querySelector('.legend-unit')?.textContent.trim(),
      paintExpr: JSON.stringify(map.getPaintProperty('quake-core', 'circle-color')).slice(0, 120),
      bar: { left: bar.left, right: bar.right, y: bar.top + bar.height / 2 },
      ticks,
      // Spread the sample across the value range rather than taking the first few.
      samples: isolated
        .sort((a, b) => b.mag - a.mag)
        .filter((_, i, arr) => i % Math.max(1, Math.floor(arr.length / 9)) === 0)
        .slice(0, 9),
    };
  `);

  const shot = `./px-${mode.prop}.png`;
  await cdp.screenshot(shot);
  const img = decodePNG(readFileSync(shot));

  // Value -> x on the legend bar, interpolated between the visible tick labels.
  const numeric = probe.ticks
    .map((t) => ({ x: t.x, v: Number(t.text.replace(/[^\d.]/g, "")) }))
    .filter((t) => Number.isFinite(t.v));
  const legendX = (v) => {
    if (v <= numeric[0].v) return numeric[0].x;
    for (let i = 1; i < numeric.length; i += 1) {
      if (v <= numeric[i].v) {
        const a = numeric[i - 1];
        const b = numeric[i];
        return a.x + ((v - a.v) / (b.v - a.v)) * (b.x - a.x);
      }
    }
    return numeric[numeric.length - 1].x;
  };

  const rows = probe.samples.map((s) => {
    const value = mode.prop === "age" ? s.age / 3_600_000 : s[mode.prop];
    const dot = sampleBrightest(img, s.x, s.y, 3, SCALE);
    const lx = Math.min(Math.max(legendX(value), probe.bar.left + 2), probe.bar.right - 2);
    const leg = sampleRegion(img, lx, probe.bar.y, 1, SCALE);
    return { qid: s.qid, value: Number(value.toFixed(2)), dot, leg, delta: Math.round(dist(dot, leg)) };
  });

  results.push({ mode: mode.label, probe, rows });
}

for (const r of results) {
  console.log(`\n=== ${r.mode} ===`);
  console.log(`legend: "${r.probe.legendTitle}" (${r.probe.legendUnit})  ticks: ${r.probe.ticks.map(t => t.text).join(" ")}`);
  console.log(`paint:  ${r.probe.paintExpr}…`);
  for (const row of r.rows) {
    console.log(
      `  value ${String(row.value).padStart(7)}  dot rgb(${row.dot.join(",")})`.padEnd(46) +
        `legend rgb(${row.leg.join(",")})`.padEnd(24) + `Δ=${row.delta}`,
    );
  }
  const deltas = r.rows.map((x) => x.delta);
  console.log(`  max Δ ${Math.max(...deltas)}   mean Δ ${Math.round(deltas.reduce((a, b) => a + b, 0) / deltas.length)}`);
}

console.log("\nconsole:", cdp.consoleLines.filter((l) => /error|exception/i.test(l)).join("\n") || "(clean)");
cdp.close();

