// Can a user read a dot's value off the legend?
//
// For each sampled dot this takes its on-screen pixel colour, finds the point
// on the legend bar whose pixel colour matches best, and converts that point
// back to a value using only the tick labels the user can see. If the colour
// system is honest, the recovered reading lands on the dot's real value.
import { readFileSync } from "node:fs";
import { connect, waitFor } from "./cdp.mjs";
import { decodePNG, sampleBrightest, sampleRegion, dist } from "./png.mjs";

const SCALE = 2;
const cdp = await connect();
await cdp.send("Emulation.setDeviceMetricsOverride", {
  width: 1512, height: 845, deviceScaleFactor: SCALE, mobile: false,
});
await cdp.goto("http://localhost:9219/");
await waitFor(cdp, "window.__map && window.__map.isStyleLoaded()", { label: "style" });
await waitFor(cdp, "window.__map.queryRenderedFeatures({layers:['quake-core']}).length > 0", {
  label: "dots", timeout: 40000,
});

/** "1.5" -> 1.5, "8+" -> 8, "now" -> 0, "6h" -> 6, "30d" -> 720 (hours). */
function tickValue(text) {
  const t = text.trim().toLowerCase();
  if (t === "now") return 0;
  const m = t.match(/^([\d.]+)\s*([hdm]?)/);
  if (!m) return null;
  const n = Number(m[1]);
  if (!Number.isFinite(n)) return null;
  return m[2] === "d" ? n * 24 : m[2] === "m" ? n / 60 : n;
}

const MODES = [
  { label: "Magnitude", value: (s) => s.mag, unit: "M" },
  { label: "Depth", value: (s) => s.depth, unit: "km" },
  { label: "Recency", value: (s) => s.age / 3_600_000, unit: "h" },
];

let failures = 0;

for (const mode of MODES) {
  const card = await cdp.evaluate(`
    const b = [...document.querySelectorAll('.mode-card')]
      .find(b => b.textContent.trim().startsWith(${JSON.stringify(mode.label)}));
    const r = b.getBoundingClientRect();
    return { x: r.left + r.width / 2, y: r.top + r.height / 2 };
  `);
  await cdp.click(card.x, card.y);
  await new Promise((r) => setTimeout(r, 1500));

  const probe = await cdp.evaluate(`
    const map = window.__map;
    const canvas = map.getCanvas().getBoundingClientRect();
    const legend = document.querySelector('.legend');
    const bar = legend.querySelector('.legend-bar').getBoundingClientRect();
    const feats = map.queryRenderedFeatures({ layers: ['quake-core'] });
    const pts = feats.map(f => {
      const p = map.project(f.geometry.coordinates);
      return { qid: f.properties.qid, mag: f.properties.mag, depth: f.properties.depth,
               age: f.properties.age, x: canvas.left + p.x, y: canvas.top + p.y };
    });
    // Isolated dots only, and big enough that the core is more than one pixel.
    const isolated = pts.filter((p, i) =>
      p.mag >= 2.5 && pts.every((q, j) => i === j || Math.hypot(p.x - q.x, p.y - q.y) > 30));
    return {
      title: legend.querySelector('.legend-title').textContent.trim(),
      unit: legend.querySelector('.legend-unit')?.textContent.trim(),
      driver: JSON.stringify(map.getPaintProperty('quake-core', 'circle-color')[2]),
      bar: { left: bar.left, right: bar.right, y: bar.top + bar.height / 2 },
      ticks: [...legend.querySelectorAll('.legend-tick')].map(t => {
        const r = t.getBoundingClientRect();
        return { text: t.textContent.trim(), x: r.left + r.width / 2 };
      }),
      samples: isolated.sort((a, b) => b.mag - a.mag)
        .filter((_, i, arr) => i % Math.max(1, Math.floor(arr.length / 7)) === 0).slice(0, 7),
    };
  `);

  const shot = `./px-${mode.label.toLowerCase()}.png`;
  await cdp.screenshot(shot);
  const img = decodePNG(readFileSync(shot));

  const ticks = probe.ticks
    .map((t) => ({ ...t, v: tickValue(t.text) }))
    .filter((t) => t.v !== null);

  // Colour of every column of the legend bar.
  const columns = [];
  for (let x = Math.ceil(probe.bar.left) + 2; x <= Math.floor(probe.bar.right) - 2; x += 1) {
    columns.push({ x, rgb: sampleRegion(img, x, probe.bar.y, 1, SCALE) });
  }

  /** Position on the bar -> value, linear between the two labelled ticks. */
  const readValue = (x) => {
    if (x <= ticks[0].x) return ticks[0].v;
    for (let i = 1; i < ticks.length; i += 1) {
      if (x <= ticks[i].x) {
        const a = ticks[i - 1];
        const b = ticks[i];
        return { lo: a, hi: b, v: a.v + ((x - a.x) / (b.x - a.x)) * (b.v - a.v) };
      }
    }
    return { lo: ticks.at(-1), hi: ticks.at(-1), v: ticks.at(-1).v };
  };

  console.log(`\n=== ${mode.label} ===`);
  console.log(`legend "${probe.title}" (${probe.unit})   driven by ${probe.driver}   ticks ${ticks.map((t) => t.text).join(" ")}`);

  for (const s of probe.samples) {
    const truth = mode.value(s);
    const dot = sampleBrightest(img, s.x, s.y, 3, SCALE);
    let best = columns[0];
    let bestD = Infinity;
    for (const c of columns) {
      const d = dist(dot, c.rgb);
      if (d < bestD) {
        bestD = d;
        best = c;
      }
    }
    const read = readValue(best.x);
    const bracket = typeof read === "number" ? null : read;
    // The user reads the dot as "somewhere between these two labels".
    const inBracket =
      bracket === null
        ? truth <= ticks[0].v
        : truth >= bracket.lo.v - 1e-9 && truth <= bracket.hi.v + 1e-9;
    // Allow one bracket of slack: adjacent ramp stops are close in colour.
    const near =
      bracket !== null &&
      truth >= (ticks[ticks.findIndex((t) => t === bracket.lo) - 1]?.v ?? bracket.lo.v) &&
      truth <= (ticks[ticks.findIndex((t) => t === bracket.hi) + 1]?.v ?? bracket.hi.v);
    const ok = inBracket || near;
    if (!ok) failures += 1;
    const label = bracket === null ? `≤${ticks[0].text}` : `${bracket.lo.text}…${bracket.hi.text}`;
    console.log(
      `  ${ok ? "ok  " : "FAIL"} true ${String(truth.toFixed(1)).padStart(6)}${mode.unit}` +
        `  dot rgb(${dot.join(",")})`.padEnd(22) +
        `  reads as ${label.padEnd(11)} (${(typeof read === "number" ? read : read.v).toFixed(1)})` +
        `  match Δ=${Math.round(bestD)}`,
    );
  }
}

console.log(`\n${failures === 0 ? "PASS" : `FAIL (${failures})`} — legend readings vs dot colours`);
console.log("console:", cdp.consoleLines.filter((l) => /error|exception/i.test(l)).join("\n") || "(clean)");
cdp.close();

