    expect(sortQuakes(list, "deep").map((q) => q.depth)).toEqual([300, 100, 10]);
    expect(sortQuakes(list, "felt").map((q) => q.felt)).toEqual([900, 5, null]);
    expect(sortQuakes(list, "significance").map((q) => q.sig)).toEqual([800, 400, 10]);
