    if (!map.getLayer(LYR_PLATES)) {
      map.addLayer({
        id: LYR_PLATES,
        type: "line",
        source: SRC_PLATES,
        layout: {
          "line-cap": "round",
          "line-join": "round",
          visibility: showPlatesRef.current ? "visible" : "none",
