      map.addLayer({
        id: LYR_CORE,
        type: "circle",
        source: SRC_QUAKES,
        paint: {
          "circle-color": color,
          "circle-radius": radiusExpression(),
          "circle-opacity": [
            "interpolate",
            ["linear"],
            ["get", "mag"],
            0,
            light ? 0.8 : 0.62,
            3,
            light ? 0.92 : 0.82,
            6,
            0.95,
          ],
          "circle-stroke-color": [
            "case",
            ["boolean", ["feature-state", "hover"], false],
            "#ffffff",
            theme.haloColor,
          ],
          "circle-stroke-width": [
            "case",
            ["boolean", ["feature-state", "hover"], false],
            2,
            ["interpolate", ["linear"], ["get", "mag"], 2, 0.4, 5, 1.1],
          ],
          "circle-stroke-opacity": 0.9,
        },
      });
    }

    if (!map.getLayer(LYR_SELECTED)) {
      map.addLayer({
        id: LYR_SELECTED,
        type: "circle",
        source: SRC_QUAKES,
        filter: ["==", ["get", "qid"], "�"],
        paint: {
          "circle-color": "rgba(0,0,0,0)",
          "circle-radius": 14,
          "circle-stroke-color": "#ffffff",
          "circle-stroke-width": 2,
          "circle-stroke-opacity": 1,
        },
