// Responsive behaviour: layout integrity, the compact drawer, and the phone
// tab bar — at every breakpoint the stylesheet actually branches on.
import { connect, waitFor } from "./cdp.mjs";

const cdp = await connect();
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
let pass = 0;
const failures = [];
const check = (name, ok, detail = "") => {
  if (ok) { pass += 1; console.log(`  ok   ${name}${detail ? `  — ${detail}` : ""}`); }
  else { failures.push(name); console.log(`  FAIL ${name}${detail ? `  — ${detail}` : ""}`); }
};

async function clickEl(selector, text) {
  const box = await cdp.evaluate(`
    const els = [...document.querySelectorAll(${JSON.stringify(selector)})];
    const el = ${text ? `els.find(e => e.textContent.trim().toLowerCase().startsWith(${JSON.stringify(text.toLowerCase())}))` : "els[0]"};
    if (!el) return null;
    const r = el.getBoundingClientRect();
    return { x: r.left + r.width / 2, y: r.top + r.height / 2 };
  `);
  if (!box) throw new Error(`no element ${selector} ${text ?? ""}`);
  await cdp.click(box.x, box.y);
}

const layout = () =>
  cdp.evaluate(`
    const el = s => document.querySelector(s);
    const box = s => { const e = el(s); if (!e) return null; const r = e.getBoundingClientRect();
      return { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height) }; };
    const canvas = window.__map.getCanvas();
    const doc = document.documentElement;
    // Any element sticking out past the viewport, ignoring intentionally
    // offscreen ones (the closed drawer).
    const overflow = [...document.querySelectorAll('body *')].filter(e => {
      const r = e.getBoundingClientRect();
      return r.width > 0 && r.right > doc.clientWidth + 1 && !e.closest('.sidebar');
    }).map(e => e.className + '@' + Math.round(e.getBoundingClientRect().right)).slice(0, 4);
    return {
      hScroll: doc.scrollWidth > doc.clientWidth,
      overflow,
      compact: document.querySelector('.app').classList.contains('is-compact'),
      tabbar: !!el('.tabbar'),
      sidebarOpen: el('.sidebar')?.classList.contains('is-open') ?? false,
      sidebarBox: box('.sidebar'),
      canvas: [canvas.clientWidth, canvas.clientHeight],
      dots: window.__map.queryRenderedFeatures({ layers: ['quake-core'] }).length,
      legend: box('.legend'),
      mapControls: box('.map-controls'),
      timeline: box('.timeline'),
      rows: document.querySelectorAll('[role="option"]').length,
      hiddenPx: (() => { const s = el('.sidebar-scroll'); return s ? s.scrollHeight - s.clientHeight : null; })(),
    };
  `);

const SIZES = [
  { w: 1360, h: 800, compact: false },
  { w: 1200, h: 780, compact: false },
  { w: 1080, h: 760, compact: true },
  { w: 834, h: 1112, compact: true },
  { w: 640, h: 900, compact: true },
  { w: 390, h: 844, compact: true },
];

for (const size of SIZES) {
  console.log(`\n=== ${size.w}x${size.h} ===`);
  await cdp.send("Emulation.setDeviceMetricsOverride", {
    width: size.w, height: size.h, deviceScaleFactor: 1, mobile: size.w <= 834,
  });
  await cdp.goto("http://localhost:9219/");
  await waitFor(cdp, "window.__map && window.__map.isStyleLoaded()", { label: "style" });
  await waitFor(cdp, "window.__map.queryRenderedFeatures({layers:['quake-core']}).length > 0", {
    label: "dots", timeout: 40000,
  });
  await sleep(2200);

  let l = await layout();
  check("no horizontal page scroll", !l.hScroll && l.overflow.length === 0, l.overflow.join(" ") || "clean");
  check("compact mode matches the breakpoint", l.compact === size.compact, `is-compact=${l.compact}`);
  check("the map fills its stage and draws dots", l.canvas[0] > 200 && l.canvas[1] > 150 && l.dots > 0,
    `${l.canvas.join("x")} · ${l.dots} dots`);
  check("map overlays stay inside the map", l.legend.x >= 0 && l.legend.y >= 0 &&
    l.mapControls.x >= 0 && l.legend.x + l.legend.w <= size.w, `legend ${l.legend.w}px at ${l.legend.x},${l.legend.y}`);

  if (!size.compact) {
    check("the controls column is fully readable", l.hiddenPx <= 20, `${l.hiddenPx}px below the fold`);
    check("the event list is populated", l.rows > 3, `${l.rows} rows`);
  } else {
    check("a tab bar replaces the split layout", l.tabbar);
    check("the filter drawer starts closed", !l.sidebarOpen);

    // Open the drawer from the header, use it, close it with the scrim.
    await clickEl(".header .icon-btn, .header button[aria-label*='ilter'], .filters-btn");
    await sleep(700);
    l = await layout();
    check("the header button opens the drawer", l.sidebarOpen && l.sidebarBox.x >= 0 && l.sidebarBox.w > 200,
      `sidebar ${l.sidebarBox.w}px at x=${l.sidebarBox.x}`);
    check("every control is reachable inside the drawer", l.hiddenPx <= 20, `${l.hiddenPx}px below the fold`);

    await clickEl(".scrim");
    await sleep(700);
    l = await layout();
    check("the scrim closes the drawer", !l.sidebarOpen);

    // Tab bar switches panes.
    await clickEl(".tabbar button", "List");
    await sleep(700);
    const listPane = await cdp.evaluate(`
      const rows = [...document.querySelectorAll('[role="option"]')];
      const first = rows[0]?.getBoundingClientRect();
      return { pane: document.querySelector('.app').dataset.pane, rows: rows.length,
               firstVisible: first ? first.width > 0 && first.right <= innerWidth + 1 : false };
    `);
    check("the List tab shows the events", listPane.pane === "list" && listPane.rows > 3 && listPane.firstVisible,
      `${listPane.rows} rows`);

    await clickEl(".tabbar button", "Map");
    await sleep(900);
    const mapPane = await cdp.evaluate(`return document.querySelector('.app').dataset.pane;`);
    check("the Map tab comes back", mapPane === "map");
  }

  // Selecting an event has to work at every size.
  const dot = await cdp.evaluate(`
    const map = window.__map;
    const c = map.getCanvas().getBoundingClientRect();
    const pts = map.queryRenderedFeatures({ layers: ['quake-core'] }).map(f => {
      const p = map.project(f.geometry.coordinates);
      return { mag: f.properties.mag, x: c.left + p.x, y: c.top + p.y };
    }).filter(p => p.x > c.left + 30 && p.x < c.right - 30 && p.y > c.top + 200 && p.y < c.bottom - 40);
    return pts.sort((a, b) => b.mag - a.mag)[0] ?? null;
  `);
  if (dot) {
    await cdp.click(dot.x, dot.y);
    await sleep(900);
    const detail = await cdp.evaluate(`
      const d = document.querySelector('.detail');
      if (!d) return null;
      const r = d.getBoundingClientRect();
      return { place: d.querySelector('.detail-place')?.textContent ?? '',
               inside: r.left >= -1 && r.right <= innerWidth + 1 && r.top >= -1 && r.bottom <= innerHeight + 1,
               box: [Math.round(r.width), Math.round(r.height)] };
    `);
    check("tapping a dot opens a detail panel that fits on screen",
      detail !== null && detail.inside, detail ? `${detail.box.join("x")} · ${detail.place}` : "no panel");
    await cdp.send("Input.dispatchKeyEvent", { type: "rawKeyDown", key: "Escape", windowsVirtualKeyCode: 27 });
    await cdp.send("Input.dispatchKeyEvent", { type: "keyUp", key: "Escape" });
  } else {
    console.log("  --   no on-screen dot to tap at this size");
  }

  await cdp.screenshot(`./resp-${size.w}.png`);
}

console.log(`\n${failures.length === 0 ? "PASS" : "FAIL"} — ${pass} checks passed, ${failures.length} failed`);
if (failures.length) console.log(failures.map((f) => `  · ${f}`).join("\n"));
console.log("console:", cdp.consoleLines.filter((l) => /error|exception/i.test(l)).join("\n") || "(clean)");
cdp.close();

