             </div>
             <button type="button" className={`plate-toggle ${showPlates ? "is-active" : ""}`}
               aria-pressed={showPlates}
               title="Tectonic plate boundaries — where nearly every quake originates"
               onClick={() => onShowPlatesChange(!showPlates)}>
               <svg viewBox="0 0 16 16" aria-hidden="true">
                 <path d="M1 5.2c2.1 0 2.6 2.1 4.6 2.1S8 4.4 10 4.4s2.4 2.4 5 2.4" fill="none"
                   stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeDasharray="2.6 2.2" />
                 <path d="M1 11.4c2.6 0 3-2.3 5.4-2.3s2.7 2.7 4.8 2.7 2.3-1.6 3.8-1.6" fill="none"
                   stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeDasharray="2.6 2.2" />
