68	
69	  const selectAndFly = useCallback((id: string) => {
70	    setSelectedId(id);
71	    setFlyToken((token) => token + 1);
72	  }, []);
73	
74	  const closeDetail = useCallback(() => setSelectedId(null), []);
75	
