// Drives every interactive control the way a user would and asserts the app
// actually responded. Real clicks, real key events, real map state.
import { connect, waitFor } from "./cdp.mjs";

const cdp = await connect();
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

let pass = 0;
const failures = [];
function check(name, ok, detail = "") {
  if (ok) {
    pass += 1;
    console.log(`  ok   ${name}${detail ? `  — ${detail}` : ""}`);
  } else {
    failures.push(name);
    console.log(`  FAIL ${name}${detail ? `  — ${detail}` : ""}`);
  }
}
const section = (t) => console.log(`\n=== ${t} ===`);

/** Click the centre of the first element matching `selector` (+ optional text). */
async function clickEl(selector, text) {
  const box = await cdp.evaluate(`
    const els = [...document.querySelectorAll(${JSON.stringify(selector)})];
    const el = ${text ? `els.find(e => e.textContent.trim().toLowerCase().startsWith(${JSON.stringify(text.toLowerCase())}))` : "els[0]"};
    if (!el) return null;
    el.scrollIntoView({ block: 'nearest' });
    const r = el.getBoundingClientRect();
    return { x: r.left + r.width / 2, y: r.top + r.height / 2 };
  `);
  if (!box) throw new Error(`no element for ${selector}${text ? ` "${text}"` : ""}`);
  await cdp.click(box.x, box.y);
}

async function typeText(selector, text) {
  await cdp.evaluate(`document.querySelector(${JSON.stringify(selector)}).focus(); return 1;`);
  for (const ch of text) {
    await cdp.send("Input.dispatchKeyEvent", { type: "keyDown", text: ch, key: ch });
    await cdp.send("Input.dispatchKeyEvent", { type: "keyUp", key: ch });
    await sleep(25);
  }
  await sleep(400);
}

async function pressKey(key, times = 1, code = key) {
  for (let i = 0; i < times; i += 1) {
    await cdp.send("Input.dispatchKeyEvent", { type: "rawKeyDown", key, code, windowsVirtualKeyCode: key === "ArrowRight" ? 39 : key === "Escape" ? 27 : 0 });
    await cdp.send("Input.dispatchKeyEvent", { type: "keyUp", key, code });
    await sleep(30);
  }
  await sleep(300);
}

const state = () =>
  cdp.evaluate(`
    const map = window.__map;
    const rows = [...document.querySelectorAll('[role="option"]')];
    const readout = document.querySelector('.control-readout');
    const src = map.getSource('quakes');
    const feats = src._data.geojson.features;
    return {
      resultCount: Number(readout.querySelector('strong').textContent.replace(/,/g,'')),
      totalCount: Number((readout.textContent.match(/of ([\\d,]+)/)||[])[1]?.replace(/,/g,'') ?? -1),
      listCount: Number(document.querySelector('.sidebar-list-head span').textContent.replace(/,/g,'')),
      sourceCount: feats.length,
      rows: rows.map(r => ({
        text: r.innerText.replace(/\\n/g, ' | '),
        mag: Number(r.querySelector('.row-mag').textContent),
        selected: r.getAttribute('aria-selected') === 'true',
      })),
      detail: document.querySelector('.detail') ? {
        place: document.querySelector('.detail-place')?.textContent ?? '',
        mag: document.querySelector('.detail-mag-value')?.textContent ?? '',
      } : null,
      tooltip: document.querySelector('.map-tooltip')?.innerText.replace(/\\n/g,' | ') ?? null,
      zoom: Number(map.getZoom().toFixed(3)),
      center: map.getCenter().toArray().map(n => Number(n.toFixed(3))),
      projection: map.getProjection()?.type ?? null,
      layers: map.getStyle().layers.filter(l => l.id.startsWith('quake') || l.id === 'plate-boundaries').map(l => l.id),
      sources: Object.entries(map.getStyle().sources).map(([k, v]) => k + ':' + v.type + ':' + (v.url ?? v.tiles?.[0] ?? '').slice(0, 42)),
      tilesLoaded: map.areTilesLoaded(),
      timelineLabel: document.querySelector('.timeline')?.innerText.split('\\n')[0] ?? null,
      brush: document.querySelector('.timeline-selection')?.innerText.replace(/\\n/g,' ') ?? null,
      windowChip: document.querySelector('.control-note')?.textContent ?? null,
    };
  `);

/** An isolated, decent-sized dot: screen point + the truth behind it. */
const pickDot = () =>
  cdp.evaluate(`
    const map = window.__map;
    const c = map.getCanvas().getBoundingClientRect();
    const pts = map.queryRenderedFeatures({ layers: ['quake-core'] }).map(f => {
      const p = map.project(f.geometry.coordinates);
      return { qid: f.properties.qid, mag: f.properties.mag, lon: f.geometry.coordinates[0],
               lat: f.geometry.coordinates[1], x: c.left + p.x, y: c.top + p.y };
    });
    const iso = pts.filter((p, i) => p.mag >= 3 &&
      pts.every((q, j) => i === j || Math.hypot(p.x - q.x, p.y - q.y) > 40) &&
      p.x > c.left + 80 && p.x < c.right - 460 && p.y > c.top + 300 && p.y < c.bottom - 80);
    return iso.sort((a, b) => b.mag - a.mag)[0] ?? null;
  `);

await cdp.send("Emulation.setDeviceMetricsOverride", { width: 1512, height: 845, deviceScaleFactor: 1, mobile: false });
await cdp.goto("http://localhost:9219/");
await waitFor(cdp, "window.__map && window.__map.isStyleLoaded()", { label: "style" });
await waitFor(cdp, "window.__map.queryRenderedFeatures({layers:['quake-core']}).length > 0", { label: "dots", timeout: 40000 });
await sleep(3000);

/* ------------------------------------------------------------------ */
section("Selecting an earthquake on the map");
const dot = await pickDot();
if (!dot) throw new Error("no isolated dot to click");
await cdp.move(dot.x, dot.y);
await sleep(500);
let s = await state();
check("hover shows a tooltip", s.tooltip !== null, s.tooltip ?? "");
check("tooltip magnitude matches the dot", s.tooltip?.includes(dot.mag.toFixed(1)) ?? false, `M${dot.mag}`);

await cdp.click(dot.x, dot.y);
await sleep(900);
s = await state();
check("clicking the dot opens the detail panel", s.detail !== null, s.detail?.place ?? "");
check("detail magnitude matches the clicked dot", s.detail?.mag === dot.mag.toFixed(1), `panel ${s.detail?.mag} vs dot ${dot.mag.toFixed(1)}`);
check("the matching list row is selected", s.rows.some((r) => r.selected && r.mag === Number(dot.mag.toFixed(1))));

await pressKey("Escape");
s = await state();
check("Escape closes the detail panel", s.detail === null);

/* ------------------------------------------------------------------ */
section("Selecting from the list");
const before = await state();
await clickEl('[role="option"]');
await sleep(1400);
s = await state();
check("clicking a row opens its detail", s.detail !== null, s.detail?.place ?? "");
check("the map flew to the event", s.center.join() !== before.center.join(), `${before.center} -> ${s.center}`);
check("the row shows as selected", s.rows.some((r) => r.selected));
await pressKey("Escape");

/* ------------------------------------------------------------------ */
section("Time windows");
for (const [label, expect] of [["1H", "hour"], ["7D", "7 days"], ["30D", "30 days"], ["24H", "24 hours"]]) {
  await clickEl(".segmented .segment", label);
  await sleep(2600);
  s = await state();
  check(
    `${label} loads a feed`,
    s.sourceCount > 0 && s.timelineLabel?.toLowerCase().includes(expect),
    `${s.totalCount} events · "${s.timelineLabel}"${s.windowChip ? ` · chip ${s.windowChip}` : ""}`,
  );
  check(`${label}: list, readout and map agree`, s.listCount === s.resultCount && s.sourceCount === s.resultCount,
    `list ${s.listCount} / readout ${s.resultCount} / map ${s.sourceCount}`);
}

/* ------------------------------------------------------------------ */
section("Search");
const base = await state();
await typeText(".search-input", "california");
s = await state();
const allCalifornia = s.rows.length > 0 && s.rows.every((r) => /california|, ca\b/i.test(r.text));
check("search narrows the results", s.resultCount < base.resultCount && s.resultCount > 0, `${base.resultCount} -> ${s.resultCount}`);
check("every result matches the search", allCalifornia, s.rows[0]?.text ?? "no rows");
check("the map is filtered too", s.sourceCount === s.resultCount, `map ${s.sourceCount}`);
await clickEl(".search-clear");
await sleep(400);
s = await state();
check("clearing search restores everything", s.resultCount === base.resultCount, `${s.resultCount}`);

/* ------------------------------------------------------------------ */
section("Magnitude slider");
await cdp.evaluate(`document.querySelector('input[aria-label="Magnitude, minimum"]').focus(); return 1;`);
await pressKey("ArrowRight", 30); // -1.0 + 30 * 0.1 = M2.0
s = await state();
const magReadout = await cdp.evaluate(`return document.querySelector('.range-value').textContent.trim();`);
check("dragging the minimum re-labels the range", magReadout.startsWith("M2.0"), magReadout);
check("every listed event clears the minimum", s.rows.every((r) => r.mag >= 2.0), `min shown ${Math.min(...s.rows.map((r) => r.mag))}`);
check("the map drops the filtered-out events", s.sourceCount === s.resultCount && s.resultCount < base.resultCount,
  `${base.resultCount} -> ${s.resultCount}`);
await clickEl(".link-btn");
await sleep(500);
s = await state();
check("Reset restores the unfiltered set", s.resultCount === base.resultCount, `${s.resultCount}`);

/* ------------------------------------------------------------------ */
section("Quick filters");
for (const chip of ["Significant", "Felt by people", "Tsunami flag", "Tectonic only"]) {
  await clickEl(".chip", chip);
  await sleep(600);
  s = await state();
  const consistent = s.sourceCount === s.resultCount && s.listCount === s.resultCount;
  let honest = true;
  if (chip === "Felt by people") honest = s.rows.every((r) => /reports/.test(r.text));
  if (chip === "Tsunami flag") honest = s.rows.every((r) => /~/.test(r.text));
  check(`"${chip}" filters and stays consistent`, consistent && honest && s.resultCount <= base.resultCount,
    `${s.resultCount} of ${base.resultCount}${s.rows[0] ? ` · e.g. ${s.rows[0].text}` : " · none match"}`);
  await clickEl(".chip", chip);
  await sleep(500);
}
s = await state();
check("toggling the chips back off restores everything", s.resultCount === base.resultCount, `${s.resultCount}`);

/* ------------------------------------------------------------------ */
section("In map view");
await cdp.evaluate(`window.__map.jumpTo({ center: [-120, 37], zoom: 4.2 }); return 1;`);
await sleep(1200);
await clickEl(".chip", "In map view");
await sleep(900);
s = await state();
const inView = await cdp.evaluate(`
  const map = window.__map;
  const b = map.getBounds();
  const feats = map.getSource('quakes')._data.geojson.features;
  return feats.filter(f => {
    const [lon, lat] = f.geometry.coordinates;
    return lat >= b.getSouth() && lat <= b.getNorth() && lon >= b.getWest() && lon <= b.getEast();
  }).length;
`);
check("only events inside the viewport survive", inView === s.resultCount && s.resultCount < base.resultCount,
  `${s.resultCount} listed, ${inView} inside the bounds`);
await clickEl(".chip", "In map view");
await sleep(600);

/* ------------------------------------------------------------------ */
section("Sort");
for (const [label, test] of [
  ["Strongest", (rows) => rows[0].mag === Math.max(...rows.map((r) => r.mag))],
  ["Most recent", () => true],
]) {
  await cdp.evaluate(`
    const sel = document.querySelector('.select-inline');
    const opt = [...sel.options].find(o => o.textContent === ${JSON.stringify(label)});
    sel.value = opt.value;
    sel.dispatchEvent(new Event('change', { bubbles: true }));
    return 1;
  `);
  await sleep(600);
  s = await state();
  check(`sort by "${label}"`, test(s.rows), s.rows[0]?.text ?? "");
}

/* ------------------------------------------------------------------ */
section("Timeline brush");
const tl = await cdp.evaluate(`
  const el = document.querySelector('.timeline-plot, .timeline-bars, .timeline svg, .timeline');
  const r = el.getBoundingClientRect();
  return { left: r.left, right: r.right, y: r.top + r.height * 0.6, cls: el.className };
`);
await cdp.send("Input.dispatchMouseEvent", { type: "mousePressed", x: tl.left + (tl.right - tl.left) * 0.55, y: tl.y, button: "left", clickCount: 1 });
for (let i = 0; i <= 10; i += 1) {
  await cdp.send("Input.dispatchMouseEvent", { type: "mouseMoved", x: tl.left + (tl.right - tl.left) * (0.55 + 0.03 * i), y: tl.y, button: "left" });
  await sleep(25);
}
await cdp.send("Input.dispatchMouseEvent", { type: "mouseReleased", x: tl.left + (tl.right - tl.left) * 0.85, y: tl.y, button: "left", clickCount: 1 });
await sleep(800);
s = await state();
check("dragging the timeline brushes a range", s.brush !== null && /clear/i.test(s.brush), s.brush ?? "no selection");
check("the brush filters the map and list", s.resultCount < base.resultCount && s.sourceCount === s.resultCount,
  `${base.resultCount} -> ${s.resultCount}`);
await clickEl(".timeline-selection button");
await sleep(600);
s = await state();
check("clearing the brush restores everything", s.resultCount === base.resultCount, `${s.resultCount}`);

/* ------------------------------------------------------------------ */
section("Camera actions");
await cdp.evaluate(`window.__map.jumpTo({ center: [0, 0], zoom: 6 }); return 1;`);
await sleep(600);
await clickEl(".map-btn", "Fit results");
await sleep(1600);
const fitted = await state();
check("Fit results frames the data", fitted.zoom < 6, `zoom ${fitted.zoom} centre ${fitted.center}`);
await clickEl(".map-btn", "Reset view");
await sleep(1600);
s = await state();
check("Reset view returns to the world", Math.abs(s.zoom - 1.35) < 0.05, `zoom ${s.zoom}`);

/* ------------------------------------------------------------------ */
section("Basemaps, projection, plate overlay");
for (const [label, needle] of [["Day", "positron"], ["Satellite", "arcgisonline"], ["Night", "dark-matter"]]) {
  await clickEl(".map-controls .segment", label);
  await waitFor(cdp, "window.__map.isStyleLoaded()", { label: `${label} style`, timeout: 20000 });
  await sleep(2500);
  s = await state();
  check(`${label} basemap loads`, s.sources.some((x) => x.includes(needle)) && s.tilesLoaded,
    s.sources.filter((x) => !x.startsWith("quakes") && !x.startsWith("plates")).join(" "));
  check(`${label}: earthquake layers survive the restyle`,
    ["quake-glow", "quake-core", "quake-selected", "quake-hit", "plate-boundaries"].every((l) => s.layers.includes(l)),
    s.layers.join(","));
  check(`${label}: dots still render`,
    (await cdp.evaluate(`return window.__map.queryRenderedFeatures({layers:['quake-core']}).length;`)) > 0);
}

await clickEl(".map-controls .segment", "Globe");
await sleep(2500);
s = await state();
check("globe projection engages", s.projection === "globe", s.projection ?? "null");
check("globe still renders dots", (await cdp.evaluate(`return window.__map.queryRenderedFeatures({layers:['quake-core']}).length;`)) > 0);
await cdp.screenshot("./shot-04-globe.png");
await clickEl(".map-controls .segment", "Flat");
await sleep(2000);
s = await state();
check("back to the flat map", s.projection === "mercator", s.projection ?? "null");

const platesOn = await cdp.evaluate(`return window.__map.getLayoutProperty('plate-boundaries','visibility') ?? 'visible';`);
await clickEl(".plate-toggle");
await sleep(700);
const platesOff = await cdp.evaluate(`
  const map = window.__map;
  return map.getLayer('plate-boundaries') ? (map.getLayoutProperty('plate-boundaries','visibility') ?? 'visible') : 'removed';
`);
check("plate boundaries can be turned off", platesOn === "visible" && platesOff !== "visible", `${platesOn} -> ${platesOff}`);
await clickEl(".plate-toggle");
await sleep(700);
check("plate boundaries come back",
  (await cdp.evaluate(`return window.__map.getLayer('plate-boundaries') ? (window.__map.getLayoutProperty('plate-boundaries','visibility') ?? 'visible') : 'removed';`)) === "visible");

/* ------------------------------------------------------------------ */
console.log(`\n${failures.length === 0 ? "PASS" : "FAIL"} — ${pass} checks passed, ${failures.length} failed`);
if (failures.length) console.log(failures.map((f) => `  · ${f}`).join("\n"));
console.log("console:", cdp.consoleLines.filter((l) => /error|exception/i.test(l)).join("\n") || "(clean)");
cdp.close();

