@media (max-width: 640px) {
  :root {
    --timeline-h: 86px;
  }

  .header {
    padding: 0 8px 0 10px;
  }

  .seismo {
    width: 30px;
  }

  .live {
    padding: 5px 9px;
  }

  .mode-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .facts {
    grid-template-columns: 1fr 1fr;
  }

  .detail-mag {
    width: 62px;
    height: 62px;
  }

  .detail-mag-value {
    font-size: 23px;
  }

  .detail-place {
    font-size: 15px;
  }

  .timeline {
    padding: 8px 12px 6px;
  }

  .timeline-selection {
    display: none;
  }

  .map-tooltip {
    display: none;
  }
}

/* Laptop-height viewports: tighten the control rhythm so the whole filter
   panel stays above the fold instead of hiding its last group. */
@media (max-height: 1100px) and (min-width: 1081px) {
  .sidebar-scroll {
    padding-top: 12px;
  }

  .controls {
    gap: 14px;
  }

  .control-group {
    gap: 8px;
  }
}

/* Short viewports: give the map room by shrinking the list share. */
@media (max-height: 720px) and (min-width: 1081px) {
  :root {
    --timeline-h: 96px;
  }

  .sidebar-list {
    flex-basis: 40%;
  }
}

