  gap: 2px;
  height: 16px;
}

.intensity-step {
  position: relative;
  border-radius: 2px;
  opacity: 0.34;
  transition: opacity 0.2s ease;
}

.intensity-step.is-active {
  opacity: 1;
  box-shadow: 0 0 0 1.5px rgba(255, 255, 255, 0.85);
}

.intensity-caret {
  position: absolute;
  left: 50%;
  bottom: -7px;
  width: 0;
  height: 0;
  transform: translateX(-50%);
  border-left: 4px solid transparent;
  border-right: 4px solid transparent;
  border-bottom: 5px solid rgba(255, 255, 255, 0.85);
}

.intensity-read {
  display: flex;
  align-items: baseline;
  gap: 9px;
  margin-top: 13px;
}

.intensity-roman {
  font-family: var(--font-mono);
  font-size: 17px;
  font-weight: 700;
  letter-spacing: 0.02em;
}

.intensity-word {
  font-size: 12.5px;
  color: var(--text-2);
  flex: 1;
}

.intensity-num {
  font-family: var(--font-mono);
  font-size: 10.5px;
  color: var(--text-3);
}

/* ------------------------------------------------------------------ */
/* Depth profile                                                       */
/* ------------------------------------------------------------------ */

.depth-profile {
  display: flex;
  flex-direction: column;
  gap: 9px;
}

.depth-scale {
  position: relative;
  /* Tall enough that the shallow band — 10% of the range but the home of most
     earthquakes — still has room for its label. */
  height: 168px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--line);
  background: linear-gradient(180deg, rgba(148, 163, 184, 0.07), rgba(2, 4, 8, 0.6));
  overflow: hidden;
}

.depth-band {
  position: absolute;
  left: 0;
  right: 0;
  display: flex;
  align-items: center;
  /* Both texts hug the left so the depth flag owns the right-hand gutter. */
  gap: 8px;
  padding: 0 10px;
  overflow: hidden;
  border-top: 1px dashed rgba(148, 163, 184, 0.16);
}

.depth-band:first-of-type {
  border-top: none;
}

.depth-band-label {
  font-size: 10.5px;
  font-weight: 600;
  color: var(--text-2);
}

.depth-band-range {
  font-family: var(--font-mono);
  font-size: 9.5px;
  color: var(--text-3);
}

.depth-surface {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: linear-gradient(90deg, rgba(233, 238, 247, 0.6), rgba(233, 238, 247, 0.15));
}

.depth-marker {
  position: absolute;
  left: 0;
  right: 0;
  height: 2px;
  box-shadow: 0 0 12px currentColor;
}

.depth-marker-flag {
  position: absolute;
  right: 8px;
  top: 50%;
  transform: translateY(-50%);
  padding: 2px 7px;
  border-radius: 4px;
  border: 1px solid;
  background: rgba(5, 7, 11, 0.92);
  font-family: var(--font-mono);
  font-size: 10.5px;
  font-weight: 600;
  white-space: nowrap;
}

.depth-caption {
  font-size: 11.5px;
  color: var(--text-3);
}

/* ------------------------------------------------------------------ */
/* Nearby                                                              */
/* ------------------------------------------------------------------ */

.nearby {
  display: flex;
  flex-direction: column;
  gap: 1px;
  border-radius: var(--radius-sm);
  overflow: hidden;
  border: 1px solid var(--line);
}

.nearby-row {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 7px 10px;
  background: var(--surface-1);
  text-align: left;
  transition: background 0.13s ease;
}

.nearby-row:hover {
  background: var(--surface-2);
}

.nearby-mag {
  font-family: var(--font-mono);
  font-size: 12.5px;
  font-weight: 650;
  font-variant-numeric: tabular-nums;
  width: 30px;
}

.nearby-text {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.nearby-dist {
  font-size: 11.5px;
  color: var(--text);
  font-variant-numeric: tabular-nums;
}

.nearby-time {
  font-size: 10px;
  color: var(--text-3);
}

.nearby-depth {
  font-family: var(--font-mono);
  font-size: 10.5px;
  color: var(--text-3);
  font-variant-numeric: tabular-nums;
}

