import { useMemo } from "react";

import { quakeColor, type ColorMode } from "../lib/color";
import {
  clockTime,
  depthLabel,
  latLabel,
  localTime,
  lonLabel,
  magnitudeLabel,
  mmiDescriptor,
  mmiRoman,
  relativeTime,
  splitPlace,
  titleCase,
  tntEquivalent,
  utcTime,
} from "../lib/format";
import { compassBearing, haversineKm } from "../lib/geo";
import type { AlertLevel, Quake } from "../lib/usgs";
import { DepthProfile } from "./DepthProfile";

const NEARBY_RADIUS_KM = 300;
const NEARBY_LIMIT = 6;

const ALERT_COPY: Record<AlertLevel, { label: string; body: string }> = {
  green: { label: "Green", body: "No significant losses expected" },
  yellow: { label: "Yellow", body: "Local impact, some losses likely" },
  orange: { label: "Orange", body: "Regional impact, significant losses" },
  red: { label: "Red", body: "Major disaster, extensive losses" },
};

export interface DetailPanelProps {
  quake: Quake;
  /** Full feed, so neighbours are found regardless of the active filters. */
  allQuakes: Quake[];
  colorMode: ColorMode;
  now: number;
  onClose: () => void;
  onSelect: (quake: Quake) => void;
  onLocate: () => void;
}

export function DetailPanel({
  quake,
  allQuakes,
  colorMode,
  now,
  onClose,
  onSelect,
  onLocate,
}: DetailPanelProps) {
  const color = quakeColor(colorMode, quake, now);
  const { prefix, region } = splitPlace(quake.place);

  const nearby = useMemo(() => {
    const found: Array<{ quake: Quake; km: number; bearing: string }> = [];
    for (const other of allQuakes) {
      if (other.id === quake.id) continue;
      const km = haversineKm(quake.lat, quake.lon, other.lat, other.lon);
      if (km > NEARBY_RADIUS_KM) continue;
      found.push({ quake: other, km, bearing: compassBearing(quake.lat, quake.lon, other.lat, other.lon) });
    }
    found.sort((a, b) => a.km - b.km);
    return found.slice(0, NEARBY_LIMIT);
  }, [quake, allQuakes]);

  const intensity = quake.mmi ?? quake.cdi;
  const intensitySource = quake.mmi !== null ? "Instrumental (ShakeMap)" : "Community reports";

  return (
    <aside className="detail" aria-label={`Details for ${quake.title}`}>
      <header className="detail-head">
        <div className="detail-head-top">
          <span className="detail-eyebrow">
            {quake.type === "earthquake" ? "Earthquake" : titleCase(quake.type)}
            <span className="detail-status" data-status={quake.status}>
              {quake.status === "reviewed" ? "Reviewed" : "Automatic"}
            </span>
          </span>
          <button type="button" className="icon-btn" onClick={onClose} aria-label="Close details">
            <svg viewBox="0 0 16 16" aria-hidden="true">
              <path
                d="m4 4 8 8M12 4l-8 8"
                stroke="currentColor"
                strokeWidth="1.6"
                strokeLinecap="round"
              />
            </svg>
          </button>
        </div>

        <div className="detail-hero">
          <div className="detail-mag" style={{ color, borderColor: color }}>
            <span className="detail-mag-value">{magnitudeLabel(quake.mag)}</span>
            <span className="detail-mag-type">{quake.magType?.toUpperCase() ?? "M"}</span>
          </div>
          <div className="detail-hero-text">
            <h2 className="detail-place">
              {prefix ? <span className="detail-prefix">{prefix} of </span> : null}
              {region}
            </h2>
            <p className="detail-when">
              <strong>{relativeTime(quake.time, now)}</strong>
              <span className="detail-when-sep">·</span>
              {localTime(quake.time)}
            </p>
            <p className="detail-when-utc">
              {utcTime(quake.time)} · local clock {clockTime(quake.time)}
            </p>
          </div>
        </div>

        <div className="detail-flags">
          {quake.alert ? (
            <span className={`flag flag-alert flag-${quake.alert}`} title={ALERT_COPY[quake.alert].body}>
              PAGER {ALERT_COPY[quake.alert].label}
            </span>
          ) : null}
          {quake.tsunami ? <span className="flag flag-tsunami">Tsunami evaluated</span> : null}
          {quake.sig >= 600 ? <span className="flag flag-sig">Significant event</span> : null}
          {(quake.felt ?? 0) > 0 ? (
            <span className="flag">{(quake.felt ?? 0).toLocaleString()} felt reports</span>
          ) : null}
        </div>

        <div className="detail-actions">
          <button type="button" className="btn btn-primary" onClick={onLocate}>
            Centre on map
          </button>
          <a className="btn" href={quake.url} target="_blank" rel="noreferrer">
            USGS event page ↗
          </a>
        </div>
      </header>

      <div className="detail-body">
        {intensity !== null ? (
          <Section title="Shaking intensity" hint={intensitySource}>
            <IntensityMeter value={intensity} />
          </Section>
        ) : null}

        <Section title="Depth" hint="Below sea level">
          <DepthProfile depth={quake.depth} />
        </Section>

        <Section title="Energy released" hint="Gutenberg–Richter estimate">
          <p className="energy-line">
            Equivalent to <strong>{tntEquivalent(quake.mag)}</strong>
          </p>
          <p className="energy-note">
            A single step up the magnitude scale releases about 32× more energy.
          </p>
        </Section>

        <Section title="Measurements">
          <dl className="facts">
            <Fact label="Depth" value={depthLabel(quake.depth)} />
            <Fact label="Latitude" value={latLabel(quake.lat)} />
            <Fact label="Longitude" value={lonLabel(quake.lon)} />
            <Fact label="Significance" value={`${quake.sig} / 1000`} />
            <Fact
              label="Stations"
              value={quake.nst !== null ? String(quake.nst) : "—"}
              hint="Seismometers used to locate the event"
            />
            <Fact
              label="Azimuthal gap"
              value={quake.gap !== null ? `${Math.round(quake.gap)}°` : "—"}
              hint="Largest gap between stations; under 180° is a well-constrained location"
            />
            <Fact
              label="RMS residual"
              value={quake.rms !== null ? `${quake.rms.toFixed(2)} s` : "—"}
              hint="Fit between observed and predicted arrival times"
            />
            <Fact label="Network" value={quake.net.toUpperCase() || "—"} />
          </dl>
        </Section>

        <Section
          title="Nearby in this feed"
          hint={`Within ${NEARBY_RADIUS_KM} km`}
        >
          {nearby.length === 0 ? (
            <p className="detail-empty">No other recorded events within {NEARBY_RADIUS_KM} km.</p>
          ) : (
            <ul className="nearby">
              {nearby.map(({ quake: other, km, bearing }) => (
                <li key={other.id}>
                  <button type="button" className="nearby-row" onClick={() => onSelect(other)}>
                    <span
                      className="nearby-mag"
                      style={{ color: quakeColor(colorMode, other, now) }}
                    >
                      {magnitudeLabel(other.mag)}
                    </span>
                    <span className="nearby-text">
                      <span className="nearby-dist">
                        {Math.round(km)} km {bearing}
                      </span>
                      <span className="nearby-time">{relativeTime(other.time, now)}</span>
                    </span>
                    <span className="nearby-depth">{depthLabel(other.depth)}</span>
                  </button>
                </li>
              ))}
            </ul>
          )}
        </Section>

        <p className="detail-id">
          Event ID <code>{quake.id}</code>
        </p>
      </div>
    </aside>
  );
}

function Section({
  title,
  hint,
  children,
}: {
  title: string;
  hint?: string;
  children: React.ReactNode;
}) {
  return (
    <section className="detail-section">
      <div className="detail-section-head">
        <h3>{title}</h3>
        {hint ? <span>{hint}</span> : null}
      </div>
      {children}
    </section>
  );
}

function Fact({ label, value, hint }: { label: string; value: string; hint?: string }) {
  return (
    <div className="fact" title={hint}>
      <dt>{label}</dt>
      <dd>{value}</dd>
    </div>
  );
}

const INTENSITY_COLORS = [
  "#ffffff",
  "#bfccff",
  "#a0e6ff",
  "#80ffc8",
  "#7cf35a",
  "#ffff4d",
  "#ffcc33",
  "#ff9933",
  "#ff5c1a",
  "#e60000",
  "#a60000",
];

/** Modified Mercalli scale, laid out the way USGS ShakeMaps present it. */
function IntensityMeter({ value }: { value: number }) {
  const level = Math.max(1, Math.min(10, Math.round(value)));
  return (
    <div className="intensity">
      <div className="intensity-scale" role="img" aria-label={`Intensity ${mmiRoman(value)}, ${mmiDescriptor(value)}`}>
        {INTENSITY_COLORS.map((color, index) => (
          <span
            key={color}
            className={`intensity-step ${index + 1 === level ? "is-active" : ""}`}
            style={{ background: color }}
          >
            {index + 1 === level ? <span className="intensity-caret" /> : null}
          </span>
        ))}
      </div>
      <div className="intensity-read">
        <span className="intensity-roman">{mmiRoman(value)}</span>
        <span className="intensity-word">{mmiDescriptor(value)}</span>
        <span className="intensity-num">MMI {value.toFixed(1)}</span>
      </div>
    </div>
  );
}

// Responsive behaviour: layout integrity, the compact drawer, and the phone
// tab bar — at every breakpoint the stylesheet actually branches on.
import { connect, waitFor } from "./cdp.mjs";

const cdp = await connect();
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
let pass = 0;
const failures = [];
const check = (name, ok, detail = "") => {
  if (ok) { pass += 1; console.log(`  ok   ${name}${detail ? `  — ${detail}` : ""}`); }
  else { failures.push(name); console.log(`  FAIL ${name}${detail ? `  — ${detail}` : ""}`); }
};

async function clickEl(selector, text) {
  const box = await cdp.evaluate(`
    const els = [...document.querySelectorAll(${JSON.stringify(selector)})];
    const el = ${text ? `els.find(e => e.textContent.trim().toLowerCase().startsWith(${JSON.stringify(text.toLowerCase())}))` : "els[0]"};
    if (!el) return null;
    const r = el.getBoundingClientRect();
    return { x: r.left + r.width / 2, y: r.top + r.height / 2 };
  `);
  if (!box) throw new Error(`no element ${selector} ${text ?? ""}`);
  await cdp.click(box.x, box.y);
}

const layout = () =>
  cdp.evaluate(`
    const el = s => document.querySelector(s);
    const box = s => { const e = el(s); if (!e) return null; const r = e.getBoundingClientRect();
      return { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height) }; };
    const canvas = window.__map.getCanvas();
    const doc = document.documentElement;
    // Any element sticking out past the viewport, ignoring intentionally
    // offscreen ones (the closed drawer).
    const overflow = [...document.querySelectorAll('body *')].filter(e => {
      const r = e.getBoundingClientRect();
      return r.width > 0 && r.right > doc.clientWidth + 1 && !e.closest('.sidebar');
    }).map(e => e.className + '@' + Math.round(e.getBoundingClientRect().right)).slice(0, 4);
    return {
      hScroll: doc.scrollWidth > doc.clientWidth,
      overflow,
      compact: document.querySelector('.app').classList.contains('is-compact'),
      tabbar: !!el('.tabbar'),
      sidebarOpen: el('.sidebar')?.classList.contains('is-open') ?? false,
      sidebarBox: box('.sidebar'),
      canvas: [canvas.clientWidth, canvas.clientHeight],
      dots: window.__map.queryRenderedFeatures({ layers: ['quake-core'] }).length,
      legend: box('.legend'),
      mapControls: box('.map-controls'),
      timeline: box('.timeline'),
      rows: document.querySelectorAll('[role="option"]').length,
      hiddenPx: (() => { const s = el('.sidebar-scroll'); return s ? s.scrollHeight - s.clientHeight : null; })(),
    };
  `);

const SIZES = [
  { w: 1360, h: 800, compact: false },
  { w: 1200, h: 780, compact: false },
  { w: 1080, h: 760, compact: true },
  { w: 834, h: 1112, compact: true },
  { w: 640, h: 900, compact: true },
  { w: 390, h: 844, compact: true },
];

for (const size of SIZES) {
  console.log(`\n=== ${size.w}x${size.h} ===`);
  await cdp.send("Emulation.setDeviceMetricsOverride", {
    width: size.w, height: size.h, deviceScaleFactor: 1, mobile: size.w <= 834,
  });
  await cdp.goto("http://localhost:9219/");
  await waitFor(cdp, "window.__map && window.__map.isStyleLoaded()", { label: "style" });
  await waitFor(cdp, "window.__map.queryRenderedFeatures({layers:['quake-core']}).length > 0", {
    label: "dots", timeout: 40000,
  });
  await sleep(2200);

  let l = await layout();
  check("no horizontal page scroll", !l.hScroll && l.overflow.length === 0, l.overflow.join(" ") || "clean");
  check("compact mode matches the breakpoint", l.compact === size.compact, `is-compact=${l.compact}`);
  check("the map fills its stage and draws dots", l.canvas[0] > 200 && l.canvas[1] > 150 && l.dots > 0,
    `${l.canvas.join("x")} · ${l.dots} dots`);
  check("map overlays stay inside the map", l.legend.x >= 0 && l.legend.y >= 0 &&
    l.mapControls.x >= 0 && l.legend.x + l.legend.w <= size.w, `legend ${l.legend.w}px at ${l.legend.x},${l.legend.y}`);

  if (!size.compact) {
    check("the controls column is fully readable", l.hiddenPx <= 20, `${l.hiddenPx}px below the fold`);
    check("the event list is populated", l.rows > 3, `${l.rows} rows`);
  } else {
    check("a tab bar replaces the split layout", l.tabbar);
    check("the filter drawer starts closed", !l.sidebarOpen);

    // Open the drawer from the header, use it, close it with the scrim.
    await clickEl(".header-filters");
    await sleep(700);
    l = await layout();
    check("the header button opens the drawer", l.sidebarOpen && l.sidebarBox.x >= 0 && l.sidebarBox.w > 200,
      `sidebar ${l.sidebarBox.w}px at x=${l.sidebarBox.x}`);
    check("every control is reachable inside the drawer", l.hiddenPx <= 20, `${l.hiddenPx}px below the fold`);

    // Switching tabs with the sheet open must not strand you behind it.
    await clickEl(".tabbar button", "List");
    await sleep(700);
    l = await layout();
    check("switching tabs dismisses the filter sheet", !l.sidebarOpen);

    await clickEl(".header-filters");
    await sleep(600);
    await clickEl(".drawer-head .icon-btn");
    await sleep(600);
    l = await layout();
    check("the close button dismisses the filter sheet", !l.sidebarOpen);

    // Tab bar switches panes.
    await clickEl(".tabbar button", "List");
    await sleep(700);
    const listPane = await cdp.evaluate(`
      const rows = [...document.querySelectorAll('[role="option"]')];
      const first = rows[0]?.getBoundingClientRect();
      return { pane: document.querySelector('.app').dataset.pane, rows: rows.length,
               firstVisible: first ? first.width > 0 && first.right <= innerWidth + 1 : false };
    `);
    check("the List tab shows the events", listPane.pane === "list" && listPane.rows > 3 && listPane.firstVisible,
      `${listPane.rows} rows`);

    await clickEl(".tabbar button", "Map");
    await sleep(900);
    const mapPane = await cdp.evaluate(`return document.querySelector('.app').dataset.pane;`);
    check("the Map tab comes back", mapPane === "map");
  }

  // Selecting an event has to work at every size.
  const dot = await cdp.evaluate(`
    const map = window.__map;
    const c = map.getCanvas().getBoundingClientRect();
    const pts = map.queryRenderedFeatures({ layers: ['quake-core'] }).map(f => {
      const p = map.project(f.geometry.coordinates);
      return { mag: f.properties.mag, x: c.left + p.x, y: c.top + p.y };
    }).filter(p => p.x > c.left + 260 && p.x < c.right - 30 && p.y > c.top + 30 && p.y < c.bottom - 40);
    return pts.sort((a, b) => b.mag - a.mag)[0] ?? null;
  `);
  if (dot) {
    await cdp.click(dot.x, dot.y);
    await sleep(900);
    const detail = await cdp.evaluate(`
      const d = document.querySelector('.detail');
      if (!d) return null;
      const r = d.getBoundingClientRect();
      return { place: d.querySelector('.detail-place')?.textContent ?? '',
               inside: r.left >= -1 && r.right <= innerWidth + 1 && r.top >= -1 && r.bottom <= innerHeight + 1,
               box: [Math.round(r.width), Math.round(r.height)] };
    `);
    check("tapping a dot opens a detail panel that fits on screen",
      detail !== null && detail.inside, detail ? `${detail.box.join("x")} · ${detail.place}` : "no panel");
    await cdp.send("Input.dispatchKeyEvent", { type: "rawKeyDown", key: "Escape", windowsVirtualKeyCode: 27 });
    await cdp.send("Input.dispatchKeyEvent", { type: "keyUp", key: "Escape" });
  } else {
    console.log("  --   no on-screen dot to tap at this size");
  }

  await cdp.screenshot(`./resp-${size.w}.png`);
}

console.log(`\n${failures.length === 0 ? "PASS" : "FAIL"} — ${pass} checks passed, ${failures.length} failed`);
if (failures.length) console.log(failures.map((f) => `  · ${f}`).join("\n"));
