      });
    }

    if (!map.getLayer(LYR_CORE)) {
      map.addLayer({
        id: LYR_CORE,
        type: "circle",
        source: SRC_QUAKES,
        paint: {
          "circle-color": color,
          "circle-radius": radiusExpression(),
          "circle-opacity": [
            "interpolate",
            ["linear"],
            ["get", "mag"],
            0,
            light ? 0.8 : 0.62,
            3,
            light ? 0.92 : 0.82,
            6,
            0.95,
          ],
          "circle-stroke-color": [
            "case",
            ["boolean", ["feature-state", "hover"], false],
            "#ffffff",
            theme.haloColor,
          ],
          "circle-stroke-width": [
            "case",
            ["boolean", ["feature-state", "hover"], false],
            2,
            ["interpolate", ["linear"], ["get", "mag"], 2, light ? 0.7 : 0.4, 5, light ? 1.4 : 1.1],
