/* ------------------------------------------------------------------ */
/* Floating map actions                                                */
/* ------------------------------------------------------------------ */

.map-actions {
  position: absolute;
  left: 50%;
  bottom: 14px;
  transform: translateX(-50%);
  display: flex;
  gap: 2px;
  padding: 3px;
  border-radius: 99px;
  border: 1px solid var(--line);
  background: rgba(12, 17, 25, 0.85);
  box-shadow: var(--shadow-pop);
  backdrop-filter: blur(12px);
  z-index: 8;
}

.map-btn {
  height: 26px;
  padding: 0 13px;
  border-radius: 99px;
  font-size: 11.5px;
  font-weight: 500;
  color: var(--text-2);
  white-space: nowrap;
  transition: background 0.15s ease, color 0.15s ease;
}

.map-btn:hover {
  background: rgba(148, 163, 184, 0.14);
  color: var(--text);
}

/* ------------------------------------------------------------------ */
/* Map appearance controls (stacked above the legend)                  */
/* ------------------------------------------------------------------ */

.map-controls {
  display: flex;
  flex-direction: column;
  gap: 5px;
  width: 246px;
  padding: 6px;
  border-radius: var(--radius);
  border: 1px solid var(--line);
  background: rgba(10, 14, 21, 0.86);
  box-shadow: var(--shadow-pop);
  backdrop-filter: blur(14px);
}

.map-controls .segmented {
  background: rgba(148, 163, 184, 0.07);
}

.map-controls-row {
  display: flex;
  gap: 5px;
}

.map-controls-row .segmented {
  flex: 1;
}

.plate-toggle {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 0 9px 0 8px;
  border-radius: var(--radius);
  border: 1px solid var(--line);
  background: rgba(148, 163, 184, 0.07);
  font-size: 11.5px;
  font-weight: 550;
  color: var(--text-3);
  white-space: nowrap;
  transition: background 0.15s ease, color 0.15s ease, border-color 0.15s ease;
}

.plate-toggle svg {
  width: 14px;
  height: 14px;
  flex: none;
  opacity: 0.85;
}

.plate-toggle:hover {
  color: var(--text-2);
  background: rgba(148, 163, 184, 0.13);
}

.plate-toggle.is-active {
  color: #a9c4e6;
  border-color: rgba(96, 137, 190, 0.5);
  background: rgba(61, 90, 128, 0.3);
}

