// Smoke test against the production build. window.__map is DEV-only, so this
// works purely through the DOM and rendered pixels.
import { connect, waitFor } from "./cdp.mjs";

const cdp = await connect();
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
let pass = 0;
const failures = [];
const check = (name, ok, detail = "") => {
  if (ok) { pass += 1; console.log(`  ok   ${name}${detail ? `  — ${detail}` : ""}`); }
  else { failures.push(name); console.log(`  FAIL ${name}${detail ? `  — ${detail}` : ""}`); }
};

await cdp.send("Emulation.clearDeviceMetricsOverride", {});
await cdp.goto("http://localhost:9219/");
await waitFor(cdp, `document.querySelectorAll('[role="option"]').length > 3`, { label: "list", timeout: 45000 });
await sleep(4500);

const s = await cdp.evaluate(`
  const rows = [...document.querySelectorAll('[role="option"]')];
  const canvas = document.querySelector('.map-canvas canvas');
  return {
    title: document.title,
    heading: document.querySelector('.header-title')?.textContent ?? null,
    devHandle: typeof window.__map,
    canvas: canvas ? [canvas.clientWidth, canvas.clientHeight] : null,
    rows: rows.length,
    first: rows[0]?.innerText.replace(/\\n/g, ' | ') ?? null,
    fallback: !!document.querySelector('.map-unsupported'),
    legendTicks: [...document.querySelectorAll('.legend-tick, .legend-scale span')].map(e => e.textContent).join(' '),
    attribution: document.querySelector('.maplibregl-ctrl-attrib-inner')?.textContent?.slice(0, 60) ?? null,
    windows: [...document.querySelectorAll('.segmented .segment')].map(b => b.textContent).slice(0, 4),
  };
`);
console.log(JSON.stringify(s, null, 1));

check("browser title is the model name", s.title === "Claude Opus 5", s.title);
check("visible title is the model name", s.heading === "Claude Opus 5", s.heading);
check("the dev-only map handle is stripped from the build", s.devHandle === "undefined", s.devHandle);
check("the map canvas is sized to its stage", s.canvas && s.canvas[0] > 600 && s.canvas[1] > 400, String(s.canvas));
check("the WebGL fallback is not showing", !s.fallback);
check("the feed populated the list", s.rows > 3, s.first);
check("attribution is present", (s.attribution ?? "").length > 10, s.attribution);

// Real pixels on the map, not an empty canvas.
const shot = await cdp.evaluate(`
  const c = document.querySelector('.map-canvas canvas');
  const r = c.getBoundingClientRect();
  return { x: Math.round(r.left), y: Math.round(r.top), w: Math.round(r.width), h: Math.round(r.height) };
`);
await cdp.screenshot("./prod-map.png");
check("the map area occupies the right half of the window", shot.x > 300 && shot.w > 600, JSON.stringify(shot));

// Selecting from the list must open the detail panel in the build too.
const box = await cdp.evaluate(`
  const rows = [...document.querySelectorAll('[role="option"]')];
  const row = rows[1] ?? rows[0];
  const r = row.getBoundingClientRect();
  return { x: r.left + r.width / 2, y: r.top + r.height / 2, text: row.innerText.split('\\n')[1] ?? '' };
`);
await cdp.click(box.x, box.y);
await sleep(2200);
const detail = await cdp.evaluate(`
  const d = document.querySelector('.detail');
  return d ? { place: d.querySelector('.detail-place')?.innerText ?? '', mag: d.querySelector('.detail-mag-value')?.textContent ?? '',
               sections: [...d.querySelectorAll('.section-title, .detail-section h3')].map(e => e.textContent).join(' · ') } : null;
`);
check("clicking a row opens its detail", detail !== null && detail.place.includes(box.text.trim().slice(0, 12)),
  detail ? `${detail.mag} ${detail.place}` : "no panel");
check("the detail panel is fully built", (detail?.sections ?? "").length > 10, detail?.sections);
await cdp.screenshot("./prod-detail.png");

// Escape closes it.
await cdp.send("Input.dispatchKeyEvent", { type: "rawKeyDown", key: "Escape", windowsVirtualKeyCode: 27 });
await cdp.send("Input.dispatchKeyEvent", { type: "keyUp", key: "Escape" });
await sleep(600);
check("Escape closes the detail", await cdp.evaluate(`return !document.querySelector('.detail');`));

console.log(`\n${failures.length === 0 ? "PASS" : "FAIL"} — ${pass} checks passed, ${failures.length} failed`);
if (failures.length) console.log(failures.map((f) => `  · ${f}`).join("\n"));
console.log("console:", cdp.consoleLines.filter((l) => /error|exception/i.test(l)).join("\n") || "(clean)");
cdp.close();

